-- Admins/system_admins can read all
CREATE POLICY "Admins view all email logs"
ON public.email_logs FOR SELECT
TO authenticated
USING (
  public.has_role(auth.uid(), 'admin'::app_role)
  OR public.has_role(auth.uid(), 'system_admin'::app_role)
);

