-- Sample published schedule for CS101 section A if it exists
DO $$
DECLARE v_section uuid; v_room uuid; v_slot uuid; v_faculty uuid;
BEGIN
  SELECT cs.id, cs.faculty_profile_id INTO v_section, v_faculty
  FROM public.course_sections cs
  JOIN public.course_offerings co ON co.id = cs.course_offering_id
  JOIN public.courses c ON c.id = co.course_id
  WHERE c.code = 'CS101' AND upper(cs.section_code) IN ('A','1','A1')
  LIMIT 1;
  IF v_section IS NULL THEN RETURN; END IF;
  SELECT id INTO v_room FROM public.rooms WHERE code = 'ROOM-101' LIMIT 1;
  SELECT id INTO v_slot FROM public.time_slots WHERE day_of_week = 'saturday' AND start_time = '08:00' LIMIT 1;
  IF v_room IS NOT NULL AND v_slot IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.class_schedule WHERE course_section_id = v_section AND time_slot_id = v_slot
  ) THEN
    INSERT INTO public.class_schedule (course_section_id, room_id, faculty_profile_id, time_slot_id, schedule_type, status)
    VALUES (v_section, v_room, v_faculty, v_slot, 'lecture', 'published');
  END IF;
END $$;


-- Migration: 20260602180141_e3488d8f-aadc-4c3a-8c04-22875e69488f.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260602180141', '20260602180141_e3488d8f-aadc-4c3a-8c04-22875e69488f') ON CONFLICT (version) DO NOTHING;
-- Fix duplicate is_current=true semesters; keep the one that actually has course_offerings
DO $$
DECLARE
  v_keep uuid;
  v_demoted jsonb;
BEGIN
  -- Pick semester with most course_offerings, tiebreaker latest created
  SELECT s.id INTO v_keep
  FROM semesters s
  LEFT JOIN course_offerings co ON co.semester_id = s.id
  WHERE s.is_current = true
  GROUP BY s.id, s.created_at
  ORDER BY count(co.id) DESC, s.created_at DESC
  LIMIT 1;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'name', name))
    INTO v_demoted
  FROM semesters
  WHERE is_current = true AND id <> v_keep;

  UPDATE semesters SET is_current = false
  WHERE is_current = true AND id <> v_keep;

  INSERT INTO audit_logs (entity_type, entity_id, action_type, old_values, new_values, notes)
  VALUES (
    'academic_operation',
    v_keep,
    'semester_current_conflict_fixed',
    jsonb_build_object('demoted_semesters', COALESCE(v_demoted, '[]'::jsonb)),
    jsonb_build_object('kept_semester_id', v_keep),
    'QA-02.1: resolved duplicate is_current=true semesters'
  );
END $$;

