-- Migration: 20260618052922_d83c8829-8af9-4e83-96ad-7210de65c71b.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260618052922', '20260618052922_d83c8829-8af9-4e83-96ad-7210de65c71b') ON CONFLICT (version) DO NOTHING;
-- SECURITY-RLS-REMEDIATION-01
-- 1) FACULTY: stop exposing email/phone to anonymous users.
--    Drop the public anon SELECT policy on the base table and expose a
--    safe-columns-only view for public consumption.
DROP POLICY IF EXISTS "Public can view active faculty" ON public.faculty;

CREATE OR REPLACE VIEW public.faculty_directory AS
SELECT
  f.id, f.employee_id, f.full_name_ar, f.full_name_en,
  f.degree, f.specialization, f.program_id, f.rank, f.photo,
  f.bio_ar, f.bio_en, f.sort_order, f.is_active, f.category,
  f.start_year, f.admin_position, f.admin_position_order,
  p.code        AS program_code,
  p.name_ar     AS program_name_ar
FROM public.faculty f
LEFT JOIN public.programs p ON p.id = f.program_id
WHERE f.is_active = true;

GRANT SELECT ON public.faculty_directory TO anon, authenticated;

-- 2) AUDIT LOGS: writes must only happen via SECURITY DEFINER log_audit().
--    Make sure no client can INSERT/UPDATE/DELETE directly.
REVOKE INSERT, UPDATE, DELETE ON public.audit_logs FROM anon, authenticated;

-- 3) MEDIA LIBRARY: was world-readable. Restrict to admin staff only.
DROP POLICY IF EXISTS "Public can view media" ON public.media_library;

CREATE POLICY "Admin staff can view media library"
  ON public.media_library FOR SELECT
  TO authenticated
  USING (
    public.has_any_role(
      auth.uid(),
      ARRAY['admin','system_admin','dean','registrar','student_affairs','hr_officer','finance_officer']
    )
  );

REVOKE SELECT, INSERT, UPDATE, DELETE ON public.media_library FROM anon;

-- 4) NOTIFICATIONS: inserts must only come from SECURITY DEFINER triggers
--    (create_notification) or service_role (admin server fns). Block any
--    direct client INSERT/DELETE. UPDATE is still allowed by the existing
--    notif_update_own_read policy so users can mark as read.
REVOKE INSERT, DELETE ON public.notifications FROM anon, authenticated;
REVOKE SELECT, UPDATE ON public.notifications FROM anon;

-- Migration: 20260618052958_7ea8c28b-e92a-486a-8dab-2261140c2ade.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260618052958', '20260618052958_7ea8c28b-e92a-486a-8dab-2261140c2ade') ON CONFLICT (version) DO NOTHING;
-- SECURITY-RLS-REMEDIATION-01 (follow-up)
-- Replace the security-definer view with column-level privileges on the
-- base table. This keeps anon access scoped to safe public columns only,
-- without introducing a new view object.

DROP VIEW IF EXISTS public.faculty_directory;

-- Re-create the public SELECT policy that was dropped in the previous
-- migration. Row filter is identical to the original ("is_active = true");
-- the protection now comes from column-level GRANTs below.
DROP POLICY IF EXISTS "Public can view active faculty" ON public.faculty;
CREATE POLICY "Public can view active faculty"
  ON public.faculty FOR SELECT
  TO anon, authenticated
  USING (is_active = true);

-- Strip any table-wide SELECT privilege the anon role may have inherited,
-- then grant SELECT only on safe public-directory columns. email and
-- phone are intentionally excluded so they can never be read by anon
-- even if a query asks for them.
REVOKE SELECT ON public.faculty FROM anon;
GRANT SELECT (
  id, employee_id, full_name_ar, full_name_en,
  degree, specialization, program_id, rank, photo,
  bio_ar, bio_en, sort_order, is_active, category,
  start_year, admin_position, admin_position_order
) ON public.faculty TO anon;

-- Authenticated users still need full table SELECT so the existing
-- "Admins can view all faculty" RLS policy and admin pages keep working.
-- (Non-admin authenticated users are filtered out by the existing RLS,
-- so they can only see active rows and only the safe columns above via
-- the anon policy path.)
GRANT SELECT ON public.faculty TO authenticated;

