INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260621233556', '20260621233556_d4696050-cbcf-4c69-b274-047386a14232') ON CONFLICT (version) DO NOTHING;
CREATE OR REPLACE FUNCTION public.generate_verification_code()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_code text;
BEGIN
  LOOP
    v_code := upper(substr(md5(random()::text || clock_timestamp()::text || gen_random_uuid()::text), 1, 10));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.official_documents WHERE verification_code = v_code);
  END LOOP;
  RETURN v_code;
END;
$function$;

