-- Migration: 20260624130000_has_any_role_unify_assignments.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260624130000', '20260624130000_has_any_role_unify_assignments') ON CONFLICT (version) DO NOTHING;
-- P1: Unify has_any_role with user_role_assignments + roles_catalog.app_role_mapping.
CREATE OR REPLACE FUNCTION public.has_any_role(_user_id uuid, _roles text[])
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = _user_id
      AND ur.role::text = ANY(_roles)
  )
  OR EXISTS (
    SELECT 1
    FROM public.user_role_assignments ura
    LEFT JOIN public.roles_catalog rc ON rc.code = ura.role_code
    WHERE ura.user_id = _user_id
      AND (
        ura.role_code = ANY(_roles)
        OR rc.app_role_mapping::text = ANY(_roles)
      )
  )
$$;


-- Migration: 20260624140000_student_requests_workflow_foundation.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260624140000', '20260624140000_student_requests_workflow_foundation') ON CONFLICT (version) DO NOTHING;
-- SR-A1 / SR-A2 / SR-B2: student request workflow foundation
-- - dean alignment in protect + RLS
-- - fix student cancel/resubmit RLS (WITH CHECK)
-- - returned status for correction loop
-- - grade_appeal notification label + returned notifications
-- - audit actor fallback via reviewed_by when service role updates

ALTER TABLE public.student_requests DROP CONSTRAINT IF EXISTS sr_status_chk;
ALTER TABLE public.student_requests ADD CONSTRAINT sr_status_chk
  CHECK (status IN ('draft','submitted','under_review','returned','approved','rejected','cancelled'));

CREATE OR REPLACE FUNCTION public.log_audit(
  _entity_type text,
  _entity_id uuid,
  _action_type text,
  _old jsonb DEFAULT NULL,
  _new jsonb DEFAULT NULL,
  _notes text DEFAULT NULL,
  _actor_user_id uuid DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_uid uuid := COALESCE(_actor_user_id, auth.uid());
BEGIN
  INSERT INTO public.audit_logs(actor_user_id, actor_role, entity_type, entity_id, action_type, old_values, new_values, notes)
  VALUES (v_uid, public.audit_resolve_role(v_uid), _entity_type, _entity_id, _action_type, _old, _new, _notes);
END;
$$;

CREATE OR REPLACE FUNCTION public.protect_student_request()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF public.has_any_role(v_uid, ARRAY['admin','system_admin','dean','registrar','student_affairs']) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.student_profiles sp
    WHERE sp.id = OLD.student_profile_id AND sp.user_id = v_uid
  ) THEN
    IF NEW.status = 'cancelled' AND OLD.status <> 'approved' THEN
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type       := OLD.request_type;
      NEW.submitted_at       := OLD.submitted_at;
      NEW.reviewed_by        := OLD.reviewed_by;
      NEW.reviewed_at        := OLD.reviewed_at;
      NEW.rejection_reason   := OLD.rejection_reason;
      RETURN NEW;
    END IF;

    IF OLD.status = 'draft' AND NEW.status = 'submitted' THEN
      NEW.submitted_at := COALESCE(NEW.submitted_at, now());
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type       := OLD.request_type;
      NEW.reviewed_by        := OLD.reviewed_by;
      NEW.reviewed_at        := OLD.reviewed_at;
      NEW.rejection_reason   := OLD.rejection_reason;
      RETURN NEW;
    END IF;

    IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type       := OLD.request_type;
      NEW.submitted_at       := OLD.submitted_at;
      NEW.reviewed_by        := OLD.reviewed_by;
      NEW.reviewed_at        := OLD.reviewed_at;
      NEW.rejection_reason   := OLD.rejection_reason;
      RETURN NEW;
    END IF;

    IF OLD.status = 'returned' AND NEW.status = 'submitted' THEN
      NEW.submitted_at := COALESCE(NEW.submitted_at, now());
      NEW.rejection_reason := NULL;
      NEW.reviewed_by := NULL;
      NEW.reviewed_at := NULL;
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type       := OLD.request_type;
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Students cannot modify a request after submission';
  END IF;

  RAISE EXCEPTION 'Not authorized to modify this request';
END;
$$;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'student_requests'
      AND policyname = 'sr_update_self'
  ) THEN
    EXECUTE $policy$
      ALTER POLICY sr_update_self ON public.student_requests
      USING (
        EXISTS (
          SELECT 1 FROM public.student_profiles sp
          WHERE sp.id = student_requests.student_profile_id
            AND sp.user_id = auth.uid()
        )
        AND status = ANY (ARRAY['draft','submitted','under_review','returned'])
      )
    $policy$;
    EXECUTE $policy$
      ALTER POLICY sr_update_self ON public.student_requests
      WITH CHECK (
        EXISTS (
          SELECT 1 FROM public.student_profiles sp
          WHERE sp.id = student_profile_id
            AND sp.user_id = auth.uid()
        )
        AND status = ANY (ARRAY['draft','submitted','under_review','returned','cancelled'])
      )
    $policy$;
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'student_requests'
      AND policyname = 'sr_update_priv'
  ) THEN
    EXECUTE $policy$
      ALTER POLICY sr_update_priv ON public.student_requests
      USING (
        public.has_any_role(auth.uid(), ARRAY['admin','system_admin','dean','registrar','student_affairs'])
      )
    $policy$;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.trg_audit_student_requests()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_action text;
  v_actor uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.log_audit('student_request', NEW.id,
      CASE WHEN NEW.status = 'submitted' THEN 'request_submitted' ELSE 'request_created' END,
      NULL,
      jsonb_build_object('request_type', NEW.request_type, 'status', NEW.status, 'student_profile_id', NEW.student_profile_id),
      NULL,
      auth.uid()
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND COALESCE(OLD.status,'') IS DISTINCT FROM COALESCE(NEW.status,'') THEN
    v_action := CASE NEW.status
      WHEN 'submitted' THEN 'request_submitted'
      WHEN 'under_review' THEN 'request_review_started'
      WHEN 'returned' THEN 'request_returned'
      WHEN 'approved' THEN 'request_approved'
      WHEN 'rejected' THEN 'request_rejected'
      WHEN 'cancelled' THEN 'request_cancelled'
      ELSE 'request_status_changed'
    END;
    v_actor := COALESCE(auth.uid(), NEW.reviewed_by);
    PERFORM public.log_audit('student_request', NEW.id, v_action,
      jsonb_build_object('status', OLD.status),
      jsonb_build_object('status', NEW.status, 'request_type', NEW.request_type, 'rejection_reason', NEW.rejection_reason),
      NULL,
      v_actor
    );
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.trg_notify_student_request()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_user_id uuid;
  v_type_label text;
  v_title text;
  v_msg text;
BEGIN
  IF TG_OP <> 'UPDATE' THEN RETURN NEW; END IF;
  IF COALESCE(OLD.status,'') = COALESCE(NEW.status,'') THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('approved','rejected','returned') THEN RETURN NEW; END IF;

  SELECT sp.user_id INTO v_user_id FROM public.student_profiles sp WHERE sp.id = NEW.student_profile_id;
  IF v_user_id IS NULL THEN RETURN NEW; END IF;

  v_type_label := CASE NEW.request_type
    WHEN 'absence_excuse' THEN 'عذر غياب'
    WHEN 'enrollment_suspension' THEN 'وقف القيد'
    WHEN 'extra_chance' THEN 'فرصة إضافية'
    WHEN 'transfer' THEN 'التحويل'
    WHEN 'equivalency' THEN 'المقاصة'
    WHEN 'grade_appeal' THEN 'تظلم درجات'
    ELSE NEW.request_type
  END;

  IF NEW.status = 'approved' THEN
    v_title := 'تم اعتماد طلب ' || v_type_label;
    v_msg := 'تم اعتماد طلبك (' || COALESCE(NEW.title,'') || ').';
  ELSIF NEW.status = 'returned' THEN
    v_title := 'طلب ' || v_type_label || ' يحتاج استكمال';
    v_msg := COALESCE('ملاحظات: ' || NEW.rejection_reason, 'يرجى استكمال بيانات الطلب وإعادة الإرسال.');
  ELSE
    v_title := 'تم رفض طلب ' || v_type_label;
    v_msg := COALESCE('سبب الرفض: ' || NEW.rejection_reason, 'تم رفض طلبك.');
  END IF;

  PERFORM public.create_notification(v_user_id, v_title, v_msg, 'request', 'student_request', NEW.id);
  RETURN NEW;
END;
$$;


-- Migration: 20260625120000_grade_appeal_approval_effect.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260625120000', '20260625120000_grade_appeal_approval_effect') ON CONFLICT (version) DO NOTHING;
-- SR-C1: apply grade changes when a grade_appeal request is approved

ALTER TABLE public.grade_appeal_details
  ADD COLUMN IF NOT EXISTS approved_total_score numeric,
  ADD COLUMN IF NOT EXISTS grades_applied_at timestamptz;

CREATE OR REPLACE FUNCTION public.apply_grade_appeal_on_approval()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_details public.grade_appeal_details%ROWTYPE;
  v_enrollment_id uuid;
  v_current_total numeric := 0;
  v_section_max numeric := 0;
  v_approved_total numeric;
  v_allocated numeric := 0;
  v_grade record;
  v_last_grade_id uuid;
  v_new_score numeric;
  v_staff_id uuid;
BEGIN
  IF NEW.request_type <> 'grade_appeal'
     OR NEW.status <> 'approved'
     OR COALESCE(OLD.status, '') = 'approved' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_details
  FROM public.grade_appeal_details
  WHERE request_id = NEW.id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Grade appeal details missing for request %', NEW.id;
  END IF;

  IF v_details.grades_applied_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_approved_total := v_details.approved_total_score;
  IF v_approved_total IS NULL THEN
    RAISE EXCEPTION 'approved_total_score must be set before approving a grade appeal';
  END IF;

  v_enrollment_id := v_details.student_enrollment_id;
  IF v_enrollment_id IS NULL THEN
    RAISE EXCEPTION 'student_enrollment_id missing on grade appeal details';
  END IF;

  SELECT COALESCE(SUM(gc.max_score), 0) INTO v_section_max
  FROM public.grade_components gc
  JOIN public.student_enrollments se ON se.course_section_id = gc.course_section_id
  WHERE se.id = v_enrollment_id;

  IF v_approved_total < 0 OR v_approved_total > v_section_max THEN
    RAISE EXCEPTION 'Approved total % must be between 0 and section max %', v_approved_total, v_section_max;
  END IF;

  SELECT COALESCE(SUM(sg.score), 0) INTO v_current_total
  FROM public.student_grades sg
  WHERE sg.student_enrollment_id = v_enrollment_id
    AND sg.status IN ('submitted', 'approved');

  IF v_current_total <= 0 THEN
    RAISE EXCEPTION 'No recorded grades to adjust for this enrollment';
  END IF;

  SELECT id INTO v_staff_id
  FROM public.staff_profiles
  WHERE user_id = NEW.reviewed_by
  LIMIT 1;

  SELECT sg.id INTO v_last_grade_id
  FROM public.student_grades sg
  JOIN public.grade_components gc ON gc.id = sg.grade_component_id
  WHERE sg.student_enrollment_id = v_enrollment_id
    AND sg.status IN ('submitted', 'approved')
  ORDER BY gc.sort_order DESC, sg.id DESC
  LIMIT 1;

  FOR v_grade IN
    SELECT sg.id, sg.score, gc.max_score, gc.sort_order
    FROM public.student_grades sg
    JOIN public.grade_components gc ON gc.id = sg.grade_component_id
    WHERE sg.student_enrollment_id = v_enrollment_id
      AND sg.status IN ('submitted', 'approved')
    ORDER BY gc.sort_order, sg.id
  LOOP
    IF v_grade.id = v_last_grade_id THEN
      v_new_score := LEAST(v_grade.max_score, GREATEST(0, v_approved_total - v_allocated));
    ELSE
      v_new_score := LEAST(
        v_grade.max_score,
        ROUND(v_approved_total * (v_grade.score / v_current_total), 2)
      );
      v_allocated := v_allocated + v_new_score;
    END IF;

    UPDATE public.student_grades
       SET score = v_new_score,
           status = 'approved',
           approved_at = now(),
           approved_by = v_staff_id,
           updated_at = now()
     WHERE id = v_grade.id;
  END LOOP;

  UPDATE public.grade_appeal_details
     SET grades_applied_at = now(),
         updated_at = now()
   WHERE id = v_details.id;

  RETURN NEW;
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_apply_grade_appeal_on_approval'
      AND tgrelid = 'public.student_requests'::regclass
  ) THEN
    CREATE TRIGGER trg_apply_grade_appeal_on_approval
      AFTER UPDATE ON public.student_requests
      FOR EACH ROW EXECUTE FUNCTION public.apply_grade_appeal_on_approval();
  END IF;
END $$;


