    CREATE POLICY ssrs_insert_priv ON public.student_service_request_steps FOR INSERT TO authenticated
    WITH CHECK (public.has_any_role(auth.uid(), ARRAY['admin','system_admin','registrar','student_affairs']));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='student_service_request_steps' AND policyname='ssrs_update_priv') THEN
    CREATE POLICY ssrs_update_priv ON public.student_service_request_steps FOR UPDATE TO authenticated
    USING (public.has_any_role(auth.uid(), ARRAY['admin','system_admin','dean','registrar','student_affairs','department_head','faculty_member','finance_officer']));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='student_service_request_events' AND policyname='ssre_select_participants') THEN
    CREATE POLICY ssre_select_participants ON public.student_service_request_events FOR SELECT TO authenticated
    USING (public.is_owner_of_request(auth.uid(), request_id) OR public.has_any_role(auth.uid(), ARRAY['admin','system_admin','dean','registrar','student_affairs','department_head','faculty_member','finance_officer']));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='student_service_request_events' AND policyname='ssre_insert_priv') THEN
    CREATE POLICY ssre_insert_priv ON public.student_service_request_events FOR INSERT TO authenticated
    WITH CHECK (public.has_any_role(auth.uid(), ARRAY['admin','system_admin','dean','registrar','student_affairs','department_head','faculty_member','finance_officer']));
  END IF;
END $mig$;

CREATE OR REPLACE FUNCTION public.protect_student_request()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF public.has_any_role(v_uid, ARRAY['admin','system_admin','dean','registrar','student_affairs']) THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.student_profiles sp WHERE sp.id = OLD.student_profile_id AND sp.user_id = v_uid) THEN
    IF NEW.status = 'cancelled' AND OLD.status NOT IN ('approved','completed') THEN
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type := OLD.request_type;
      NEW.submitted_at := OLD.submitted_at;
      NEW.reviewed_by := OLD.reviewed_by;
      NEW.reviewed_at := OLD.reviewed_at;
      NEW.rejection_reason := OLD.rejection_reason;
      NEW.completed_at := OLD.completed_at;
      NEW.cancelled_at := COALESCE(NEW.cancelled_at, now());
      RETURN NEW;
    END IF;
    IF OLD.status = 'draft' AND NEW.status = 'submitted' THEN
      NEW.submitted_at := COALESCE(NEW.submitted_at, now());
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type := OLD.request_type;
      NEW.reviewed_by := OLD.reviewed_by;
      NEW.reviewed_at := OLD.reviewed_at;
      NEW.rejection_reason := OLD.rejection_reason;
      RETURN NEW;
    END IF;
    IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type := OLD.request_type;
      NEW.submitted_at := OLD.submitted_at;
      NEW.reviewed_by := OLD.reviewed_by;
      NEW.reviewed_at := OLD.reviewed_at;
      NEW.rejection_reason := OLD.rejection_reason;
      RETURN NEW;
    END IF;
    IF OLD.status IN ('returned','returned_for_completion') AND NEW.status = 'submitted' THEN
      NEW.submitted_at := COALESCE(NEW.submitted_at, now());
      NEW.rejection_reason := NULL;
      NEW.reviewed_by := NULL;
      NEW.reviewed_at := NULL;
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type := OLD.request_type;
      RETURN NEW;
    END IF;
    IF OLD.status IN ('returned','returned_for_completion') AND NEW.status IN ('returned','returned_for_completion') THEN
      NEW.student_profile_id := OLD.student_profile_id;
      NEW.request_type := OLD.request_type;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Students cannot modify a request after submission';
  END IF;
  RAISE EXCEPTION 'Not authorized to modify this request';
END;
$fn$;

