-- Migration: 20260704120000_import_students_account_audit_fix.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260704120000', '20260704120000_import_students_account_audit_fix') ON CONFLICT (version) DO NOTHING;
-- IMPORT-STUDENTS-ACCOUNT-AUDIT-FIX-01
-- Fix ambiguous public.log_audit overload resolution during student account linking.
-- This migration does not modify student data and does not drop any audit function.

CREATE OR REPLACE FUNCTION public.link_student_user_account(
  _profile_id uuid,
  _target_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_existing_user uuid;
  v_other_profile uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_any_role(v_caller, ARRAY['admin','system_admin','registrar','student_affairs']) THEN
    RAISE EXCEPTION 'Forbidden: insufficient privileges to link student account'
      USING ERRCODE = '42501';
  END IF;

  IF _profile_id IS NULL OR _target_user_id IS NULL THEN
    RAISE EXCEPTION 'profile_id and target_user_id are required' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_other_profile
  FROM public.student_profiles
  WHERE user_id = _target_user_id AND id <> _profile_id
  LIMIT 1;
  IF v_other_profile IS NOT NULL THEN
    RAISE EXCEPTION 'Target auth user is already linked to another student profile'
      USING ERRCODE = '23505';
  END IF;

  SELECT user_id INTO v_existing_user
  FROM public.student_profiles
  WHERE id = _profile_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Student profile not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_existing_user IS NOT NULL AND v_existing_user = _target_user_id THEN
    RETURN jsonb_build_object('ok', true, 'already_linked', true,
      'profile_id', _profile_id, 'user_id', _target_user_id);
  END IF;
  IF v_existing_user IS NOT NULL AND v_existing_user <> _target_user_id THEN
    RAISE EXCEPTION 'Student profile already linked to a different auth user'
      USING ERRCODE = '23505';
  END IF;

  PERFORM set_config('app.bypass_student_lock', '1', true);
  UPDATE public.student_profiles
     SET user_id = _target_user_id,
         must_change_password = true,
         status = COALESCE(NULLIF(status, ''), 'active'),
         updated_at = now()
   WHERE id = _profile_id;
  PERFORM set_config('app.bypass_student_lock', '0', true);

  -- Use the 7-argument overload explicitly. The database currently has both
  -- log_audit(text, uuid, text, jsonb, jsonb, text) and
  -- log_audit(text, uuid, text, jsonb, jsonb, text, uuid), so untyped literals
  -- in a 6-argument call can resolve ambiguously.
  PERFORM public.log_audit(
    'student_profile'::text,
    _profile_id::uuid,
    'student_account_linked'::text,
    jsonb_build_object('user_id', v_existing_user)::jsonb,
    jsonb_build_object('user_id', _target_user_id)::jsonb,
    'Linked student profile to auth user via link_student_user_account'::text,
    v_caller::uuid
  );

  RETURN jsonb_build_object('ok', true, 'profile_id', _profile_id, 'user_id', _target_user_id);
END;
$$;

REVOKE ALL ON FUNCTION public.link_student_user_account(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.link_student_user_account(uuid, uuid) TO authenticated, service_role;


-- Migration: 20260704200326_b0736829-500e-456c-aa9b-6dc7ccd10012.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260704200326', '20260704200326_b0736829-500e-456c-aa9b-6dc7ccd10012') ON CONFLICT (version) DO NOTHING;
-- COUNCILS-FACULTY-HISTORY-RLS-01
-- Helpers + RLS extensions for former-member archive reads and viewer topic-insert lockdown.

-- 1) Helper: was_council_member_on(_user, _council, _date)
CREATE OR REPLACE FUNCTION public.was_council_member_on(_user uuid, _council uuid, _date date)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.academic_council_members m
    WHERE m.council_id = _council
      AND m.user_id    = _user
      AND m.active_from <= _date
      AND (m.active_to IS NULL OR m.active_to >= _date)
  );
$$;

-- 2) Helper: can_submit_council_topic(_user, _council)
-- Active membership with role in (chair, secretary, member). Excludes viewer.
CREATE OR REPLACE FUNCTION public.can_submit_council_topic(_user uuid, _council uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.academic_council_members m
    WHERE m.council_id = _council
      AND m.user_id    = _user
      AND m.is_active  = true
      AND (m.active_to IS NULL OR m.active_to >= CURRENT_DATE)
      AND m.member_role IN (
        'chair'::public.academic_council_member_role,
        'secretary'::public.academic_council_member_role,
        'member'::public.academic_council_member_role
      )
  );
$$;

-- 3) academic_council_members SELECT: allow user to always read own rows (past + current)
DROP POLICY IF EXISTS "council_members_select" ON public.academic_council_members;
CREATE POLICY "council_members_select"
  ON public.academic_council_members
  FOR SELECT
  TO authenticated
  USING (
    public.is_council_admin(auth.uid())
    OR public.is_council_member(auth.uid(), council_id)
    OR user_id = auth.uid()
  );

-- 4) academic_council_meetings SELECT: include former members within their tenure
DROP POLICY IF EXISTS "meetings_select" ON public.academic_council_meetings;
CREATE POLICY "meetings_select"
  ON public.academic_council_meetings
  FOR SELECT
  TO authenticated
  USING (
    public.is_council_admin(auth.uid())
    OR public.is_council_member(auth.uid(), council_id)
    OR public.was_council_member_on(auth.uid(), council_id, (scheduled_at AT TIME ZONE 'UTC')::date)
  );

-- 5) academic_council_topics INSERT: block viewer role
DROP POLICY IF EXISTS "topics_insert_member" ON public.academic_council_topics;
CREATE POLICY "topics_insert_member"
  ON public.academic_council_topics
  FOR INSERT
  TO authenticated
  WITH CHECK (
    submitted_by = auth.uid()
    AND (
      public.is_council_admin(auth.uid())
      OR public.can_submit_council_topic(auth.uid(), council_id)
    )
  );

-- 6) academic_council_topics SELECT: extend to former members for topics tied to a meeting in their tenure
DROP POLICY IF EXISTS "topics_select" ON public.academic_council_topics;
CREATE POLICY "topics_select"
  ON public.academic_council_topics
  FOR SELECT
  TO authenticated
  USING (
    public.is_council_admin(auth.uid())
    OR public.is_council_member(auth.uid(), council_id)
    OR submitted_by = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.academic_council_meetings mt
      WHERE mt.id = academic_council_topics.meeting_id
        AND public.was_council_member_on(
          auth.uid(),
          academic_council_topics.council_id,
          (mt.scheduled_at AT TIME ZONE 'UTC')::date
        )
    )
  );


-- Migration: 20260705012437_ce22d82a-51b3-4452-bde2-90f0b8d64fa8.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260705012437', '20260705012437_ce22d82a-51b3-4452-bde2-90f0b8d64fa8') ON CONFLICT (version) DO NOTHING;
-- COUNCILS-TOPIC-ATTACHMENTS-DB-APPLY-01
-- Applies supabase/migrations/20260708120000_council_topic_attachments.sql
-- Bucket already created via storage_create_bucket tool; UPDATE its settings below.

CREATE TABLE IF NOT EXISTS public.academic_council_topic_attachments (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  topic_id        uuid NOT NULL
                    REFERENCES public.academic_council_topics(id) ON DELETE RESTRICT,
  council_id      uuid NOT NULL
                    REFERENCES public.academic_councils(id) ON DELETE RESTRICT,
  uploaded_by     uuid NOT NULL
                    REFERENCES auth.users(id) ON DELETE RESTRICT,
  file_name       text NOT NULL,
  file_path       text NOT NULL,
  file_size       bigint NOT NULL,
  mime_type       text NOT NULL,
  file_ext        text NOT NULL,
  storage_bucket  text NOT NULL DEFAULT 'council-topic-attachments',
  created_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  CONSTRAINT acta_file_size_positive CHECK (file_size > 0),
  CONSTRAINT acta_file_size_max CHECK (file_size <= 10485760),
  CONSTRAINT acta_storage_bucket_fixed CHECK (storage_bucket = 'council-topic-attachments'),
  CONSTRAINT acta_mime_allowlist CHECK (
    mime_type = ANY (ARRAY[
      'image/jpeg','image/png','image/webp','application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    ]::text[])
  ),
  CONSTRAINT acta_ext_allowlist CHECK (
    lower(file_ext) = ANY (ARRAY[
      'jpg','jpeg','png','webp','pdf','doc','docx','xls','xlsx'
    ]::text[])
  )
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_acta_file_path
  ON public.academic_council_topic_attachments(file_path)
  WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_acta_topic
  ON public.academic_council_topic_attachments(topic_id)
  WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_acta_council
  ON public.academic_council_topic_attachments(council_id)
  WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_acta_uploader
  ON public.academic_council_topic_attachments(uploaded_by);
CREATE INDEX IF NOT EXISTS idx_acta_created_at
  ON public.academic_council_topic_attachments(created_at);
CREATE INDEX IF NOT EXISTS idx_acta_deleted_at
  ON public.academic_council_topic_attachments(deleted_at)
  WHERE deleted_at IS NOT NULL;

CREATE OR REPLACE FUNCTION public.council_topic_attachment_count(_topic_id uuid)
RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT count(*)::integer
  FROM public.academic_council_topic_attachments a
  WHERE a.topic_id = _topic_id AND a.deleted_at IS NULL;
$$;

CREATE OR REPLACE FUNCTION public.can_add_council_topic_attachment(_topic_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT public.council_topic_attachment_count(_topic_id) < 5;
$$;

CREATE OR REPLACE FUNCTION public.can_read_council_topic_attachment(
  _user uuid, _topic_id uuid, _council_id uuid
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.academic_council_topics t
    WHERE t.id = _topic_id AND t.council_id = _council_id
      AND (
        public.is_council_admin(_user)
        OR public.is_council_member(_user, t.council_id)
        OR t.submitted_by = _user
        OR EXISTS (
          SELECT 1 FROM public.academic_council_meetings mt
          WHERE mt.id = t.meeting_id
            AND public.was_council_member_on(
              _user, t.council_id,
              (mt.scheduled_at AT TIME ZONE 'UTC')::date
            )
        )
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.can_upload_council_topic_attachment(
  _user uuid, _topic_id uuid, _council_id uuid
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.academic_council_topics t
    WHERE t.id = _topic_id AND t.council_id = _council_id
      AND t.submitted_by = _user
      AND t.status IN (
        'draft'::public.academic_council_topic_status,
        'needs_completion'::public.academic_council_topic_status,
        'submitted'::public.academic_council_topic_status
      )
      AND (
        public.is_council_admin(_user)
        OR public.can_submit_council_topic(_user, t.council_id)
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.tg_enforce_council_topic_attachment()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_topic_council   uuid;
  v_submitted_by    uuid;
  v_status          public.academic_council_topic_status;
  v_expected_prefix text;
BEGIN
  NEW.file_ext := lower(trim(NEW.file_ext));
  SELECT t.council_id, t.submitted_by, t.status
    INTO v_topic_council, v_submitted_by, v_status
    FROM public.academic_council_topics t WHERE t.id = NEW.topic_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'academic_council_topic not found for topic_id %', NEW.topic_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NEW.council_id IS DISTINCT FROM v_topic_council THEN
    RAISE EXCEPTION 'council_id must match academic_council_topics.council_id'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.uploaded_by IS DISTINCT FROM v_submitted_by THEN
    RAISE EXCEPTION 'uploaded_by must match topic submitted_by'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_status NOT IN (
    'draft'::public.academic_council_topic_status,
    'needs_completion'::public.academic_council_topic_status,
    'submitted'::public.academic_council_topic_status
  ) THEN
    RAISE EXCEPTION 'topic status does not allow attachments'
      USING ERRCODE = 'check_violation';
  END IF;
  IF public.council_topic_attachment_count(NEW.topic_id) >= 5 THEN
    RAISE EXCEPTION 'maximum 5 active attachments per topic'
      USING ERRCODE = 'check_violation';
  END IF;
  v_expected_prefix := 'council-topics/' || NEW.council_id::text || '/'
    || NEW.topic_id::text || '/' || NEW.id::text || '-';
  IF NEW.file_path IS NULL OR left(NEW.file_path, length(v_expected_prefix)) <> v_expected_prefix THEN
    RAISE EXCEPTION 'file_path must match council-topics/{council_id}/{topic_id}/{attachment_id}-{filename}'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'deleted_at must be null on insert'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DO $mig$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_acta_enforce'
      AND tgrelid = 'public.academic_council_topic_attachments'::regclass
  ) THEN
    CREATE TRIGGER trg_acta_enforce
      BEFORE INSERT ON public.academic_council_topic_attachments
      FOR EACH ROW EXECUTE FUNCTION public.tg_enforce_council_topic_attachment();
  END IF;
END $mig$;

REVOKE ALL ON TABLE public.academic_council_topic_attachments FROM anon;
GRANT SELECT, INSERT ON public.academic_council_topic_attachments TO authenticated;
GRANT ALL ON public.academic_council_topic_attachments TO service_role;
REVOKE DELETE ON public.academic_council_topic_attachments FROM authenticated;

REVOKE EXECUTE ON FUNCTION public.council_topic_attachment_count(uuid) FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.can_add_council_topic_attachment(uuid) FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.can_read_council_topic_attachment(uuid, uuid, uuid) FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.can_upload_council_topic_attachment(uuid, uuid, uuid) FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.tg_enforce_council_topic_attachment() FROM anon, PUBLIC;

GRANT EXECUTE ON FUNCTION public.council_topic_attachment_count(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_add_council_topic_attachment(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_read_council_topic_attachment(uuid, uuid, uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_upload_council_topic_attachment(uuid, uuid, uuid) TO authenticated, service_role;

ALTER TABLE public.academic_council_topic_attachments ENABLE ROW LEVEL SECURITY;

DO $mig$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='public' AND tablename='academic_council_topic_attachments'
      AND policyname='acta_select'
  ) THEN
    CREATE POLICY acta_select
      ON public.academic_council_topic_attachments
      FOR SELECT TO authenticated
      USING (
        deleted_at IS NULL
        AND public.can_read_council_topic_attachment(auth.uid(), topic_id, council_id)
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='public' AND tablename='academic_council_topic_attachments'
      AND policyname='acta_insert'
  ) THEN
    CREATE POLICY acta_insert
      ON public.academic_council_topic_attachments
      FOR INSERT TO authenticated
      WITH CHECK (
        uploaded_by = auth.uid()
        AND deleted_at IS NULL
        AND public.can_upload_council_topic_attachment(auth.uid(), topic_id, council_id)
        AND public.can_add_council_topic_attachment(topic_id)
      );
  END IF;
END $mig$;

DO $mig$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='storage' AND tablename='objects' AND policyname='acta_storage_select'
  ) THEN
    CREATE POLICY acta_storage_select
      ON storage.objects
      FOR SELECT TO authenticated
      USING (
        bucket_id = 'council-topic-attachments'
        AND EXISTS (
          SELECT 1 FROM public.academic_council_topic_attachments att
          WHERE att.file_path = storage.objects.name
            AND att.deleted_at IS NULL
            AND att.storage_bucket = 'council-topic-attachments'
            AND public.can_read_council_topic_attachment(
              auth.uid(), att.topic_id, att.council_id
            )
        )
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='storage' AND tablename='objects' AND policyname='acta_storage_insert'
  ) THEN
    CREATE POLICY acta_storage_insert
      ON storage.objects
      FOR INSERT TO authenticated
      WITH CHECK (
        bucket_id = 'council-topic-attachments'
        AND (storage.foldername(name))[1] = 'council-topics'
        AND coalesce(array_length(storage.foldername(name), 1), 0) = 4
        AND public.can_upload_council_topic_attachment(
          auth.uid(),
          ((storage.foldername(name))[3])::uuid,
          ((storage.foldername(name))[2])::uuid
        )
      );
  END IF;
END $mig$;

-- Migration: 20260705023313_9670638e-3742-4ace-824c-d58522b0a7cd.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260705023313', '20260705023313_9670638e-3742-4ace-824c-d58522b0a7cd') ON CONFLICT (version) DO NOTHING;
DO $mig$
DECLARE
  v_created_by uuid;
  v_inserted   integer;
BEGIN
  SELECT ur.user_id
    INTO v_created_by
    FROM public.user_roles ur
   WHERE ur.role IN ('system_admin'::public.app_role, 'admin'::public.app_role)
   ORDER BY CASE ur.role WHEN 'system_admin'::public.app_role THEN 0 ELSE 1 END, ur.user_id
   LIMIT 1;

  IF v_created_by IS NULL THEN
    RAISE NOTICE 'skipped — no system_admin or admin user for created_by';
    RETURN;
  END IF;

  INSERT INTO public.academic_councils (name, name_en, council_type, department_id, description, is_active, created_by)
  SELECT
    'مجلس ' || d.name_ar,
    'Department Council — ' || COALESCE(NULLIF(trim(d.name_en), ''), d.name_ar),
    'department'::public.academic_council_type,
    d.id,
    'مجلس أكاديمي لـ ' || d.name_ar || ' — سجل تأسيسي (department council seed)',
    true,
    v_created_by
  FROM public.departments d
  WHERE d.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM public.academic_councils ac
      WHERE ac.council_type = 'department'::public.academic_council_type
        AND ac.department_id = d.id
    );

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RAISE NOTICE 'inserted % department council row(s)', v_inserted;
END $mig$;

