-- Path: council-topics/{council_id}/{topic_id}/{attachment_id}-{safe_filename}

DO $mig$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname = 'storage'
      AND tablename = 'objects'
      AND policyname = 'acta_storage_select'
  ) THEN
    CREATE POLICY acta_storage_select
      ON storage.objects
      FOR SELECT
      TO authenticated
      USING (
        bucket_id = 'council-topic-attachments'
        AND EXISTS (
          SELECT 1
          FROM public.academic_council_topic_attachments att
          WHERE att.file_path = storage.objects.name
            AND att.deleted_at IS NULL
            AND att.storage_bucket = 'council-topic-attachments'
            AND public.can_read_council_topic_attachment(
              auth.uid(), att.topic_id, att.council_id
            )
        )
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname = 'storage'
      AND tablename = 'objects'
      AND policyname = 'acta_storage_insert'
  ) THEN
    CREATE POLICY acta_storage_insert
      ON storage.objects
      FOR INSERT
      TO authenticated
      WITH CHECK (
        bucket_id = 'council-topic-attachments'
        AND (storage.foldername(name))[1] = 'council-topics'
        AND coalesce(array_length(storage.foldername(name), 1), 0) = 4
        AND public.can_upload_council_topic_attachment(
          auth.uid(),
          ((storage.foldername(name))[3])::uuid,
          ((storage.foldername(name))[2])::uuid
        )
      );
  END IF;
END $mig$;

-- No storage UPDATE or DELETE policies in MVP.


-- Migration: 20260709120000_department_councils_seed.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260709120000', '20260709120000_department_councils_seed') ON CONFLICT (version) DO NOTHING;
-- COUNCILS-DEPARTMENT-COUNCILS-SEED-PREP-01
-- Idempotent seed: create missing department councils for active departments only.
-- Does NOT touch college council. Does NOT create memberships.
-- Repo-only migration prep — apply via approved deploy pipeline only.

DO $mig$
DECLARE
  v_created_by uuid;
  v_inserted   integer;
BEGIN
  SELECT ur.user_id
    INTO v_created_by
    FROM public.user_roles ur
   WHERE ur.role IN (
           'system_admin'::public.app_role,
           'admin'::public.app_role
         )
   ORDER BY CASE ur.role
              WHEN 'system_admin'::public.app_role THEN 0
              ELSE 1
            END,
            ur.user_id
   LIMIT 1;

  IF v_created_by IS NULL THEN
    RAISE NOTICE
      'COUNCILS-DEPARTMENT-COUNCILS-SEED-PREP-01: skipped — no system_admin or admin user for created_by';
    RETURN;
  END IF;

  INSERT INTO public.academic_councils (
    name,
    name_en,
    council_type,
    department_id,
    description,
    is_active,
    created_by
  )
  SELECT
    'مجلس ' || d.name_ar,
    'Department Council — ' || COALESCE(NULLIF(trim(d.name_en), ''), d.name_ar),
    'department'::public.academic_council_type,
    d.id,
    'مجلس أكاديمي لـ ' || d.name_ar || ' — سجل تأسيسي (department council seed)',
    true,
    v_created_by
  FROM public.departments d
  WHERE d.is_active = true
    AND NOT EXISTS (
      SELECT 1
      FROM public.academic_councils ac
      WHERE ac.council_type = 'department'::public.academic_council_type
        AND ac.department_id = d.id
    );

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RAISE NOTICE
    'COUNCILS-DEPARTMENT-COUNCILS-SEED-PREP-01: inserted % department council row(s)',
    v_inserted;
END $mig$;


