END $$;

COMMENT ON TABLE public.request_processing_roles IS
  'Operational job titles within a processing unit for student request routing '
  '(e.g. student_affairs_specialist, department_chair). Populated later via admin.';

COMMENT ON COLUMN public.request_processing_roles.app_role IS
