INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260713020000', '20260713020000_enrollment_certificate_hidden_e2e_draft_and_submit_window') ON CONFLICT (version) DO NOTHING;
-- ENROLLMENT-CERTIFICATE-HIDDEN-DRAFT-AND-SUBMIT-WINDOW-01S-B2
