-- ENROLLMENT-CERTIFICATE-HIDDEN-DRAFT-AND-SUBMIT-WINDOW-01S-B2
-- Guarded admin E2E helpers for hidden enrollment_certificate drafts + temporary
-- submit window (is_active true, student_visible false).
-- Does NOT modify create_student_request / submit_student_request.
-- Applying this migration does not create requests or change request_types data.

-- =============================================================================
-- Internal auth guard (admin / system_admin only)
-- =============================================================================

CREATE OR REPLACE FUNCTION public.assert_can_admin_enrollment_certificate_e2e()
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول'
      USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_any_role(
    auth.uid(),
    ARRAY['admin', 'system_admin']::text[]
  ) THEN
    RAISE EXCEPTION 'غير مصرح بإدارة اختبار شهادة القيد المخفي'
      USING ERRCODE = '42501';
  END IF;
END;
$$;

COMMENT ON FUNCTION public.assert_can_admin_enrollment_certificate_e2e() IS
  'Internal guard for enrollment_certificate hidden E2E admin RPCs. '
  'Allows admin/system_admin only.';

REVOKE ALL ON FUNCTION public.assert_can_admin_enrollment_certificate_e2e()
  FROM PUBLIC, anon, authenticated;

-- =============================================================================
-- Shared readiness helper (internal)
-- =============================================================================

CREATE OR REPLACE FUNCTION public._assert_enrollment_certificate_e2e_processing_assignments()
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pair text[];
  v_unit_code text;
  v_role_code text;
  v_unit public.request_processing_units%ROWTYPE;
  v_role public.request_processing_roles%ROWTYPE;
  v_active_count integer;
  v_resolved_user uuid;
  v_required text[][] := ARRAY[
    ARRAY['student_affairs', 'student_affairs_manager'],
    ARRAY['student_affairs', 'student_affairs_specialist'],
    ARRAY['finance', 'revenue_finance_officer'],
    ARRAY['registrar', 'registrar_general'],
    ARRAY['dean', 'dean'],
    ARRAY['archive', 'archive_officer']
  ];
BEGIN
  FOREACH v_pair SLICE 1 IN ARRAY v_required
  LOOP
    v_unit_code := v_pair[1];
    v_role_code := v_pair[2];

    SELECT * INTO v_unit
    FROM public.request_processing_units u
    WHERE u.code = v_unit_code;

    IF NOT FOUND OR v_unit.is_active IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'وحدة المعالجة % غير موجودة أو غير نشطة لنافذة اختبار شهادة القيد', v_unit_code
        USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_role
    FROM public.request_processing_roles r
    WHERE r.code = v_role_code
      AND r.unit_id = v_unit.id;

    IF NOT FOUND OR v_role.is_active IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'دور المعالجة % غير موجود أو غير نشط ضمن وحدة %', v_role_code, v_unit_code
        USING ERRCODE = '42501';
    END IF;

    SELECT count(*)::integer INTO v_active_count
    FROM public.request_processing_assignments a
    WHERE a.role_id = v_role.id
      AND a.unit_id = v_unit.id
      AND a.is_active IS TRUE
      AND (a.starts_at IS NULL OR a.starts_at <= now())
      AND (a.ends_at IS NULL OR a.ends_at > now());

    IF v_active_count = 0 THEN
      RAISE EXCEPTION 'لا يوجد إسناد نشط قابل للاستخدام للدور %', v_role_code
        USING ERRCODE = '42501';
    END IF;

    IF v_active_count > 1 THEN
      RAISE EXCEPTION 'يوجد أكثر من إسناد نشط للدور %', v_role_code
        USING ERRCODE = '42501';
    END IF;

    SELECT COALESCE(a.user_id, sp.user_id, fp.user_id, pa.user_id)
    INTO v_resolved_user
    FROM public.request_processing_assignments a
    LEFT JOIN public.staff_profiles sp ON sp.id = a.staff_profile_id
    LEFT JOIN public.faculty_profiles fp ON fp.id = a.faculty_profile_id
    LEFT JOIN public.position_assignments pa ON pa.id = a.position_assignment_id
    WHERE a.role_id = v_role.id
      AND a.unit_id = v_unit.id
      AND a.is_active IS TRUE
      AND (a.starts_at IS NULL OR a.starts_at <= now())
      AND (a.ends_at IS NULL OR a.ends_at > now())
    LIMIT 1;

    IF v_resolved_user IS NULL OR NOT EXISTS (
      SELECT 1 FROM auth.users u WHERE u.id = v_resolved_user
    ) THEN
      RAISE EXCEPTION 'إسناد الدور % لا يشير إلى مستخدم قابل للحل', v_role_code
        USING ERRCODE = '42501';
    END IF;
  END LOOP;
END;
$$;

COMMENT ON FUNCTION public._assert_enrollment_certificate_e2e_processing_assignments() IS
  'Internal: validates the six enrollment_certificate processing assignments by '
  'unit/role codes (exactly one currently-effective resolvable assignment each). '
  'Does not require the global active assignment count to equal 6.';

REVOKE ALL ON FUNCTION public._assert_enrollment_certificate_e2e_processing_assignments()
  FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._enrollment_certificate_e2e_load_hidden_type(
  p_require_inactive boolean
)
RETURNS public.request_types
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_type public.request_types%ROWTYPE;
  v_type_count integer;
  v_workflow public.request_type_workflows%ROWTYPE;
  v_steps integer;
  v_transitions integer;
BEGIN
  SELECT count(*)::integer INTO v_type_count
  FROM public.request_types rt
  WHERE rt.code = 'enrollment_certificate';

  IF v_type_count IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'نوع طلب enrollment_certificate غير فريد أو غير موجود'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_type
  FROM public.request_types rt
  WHERE rt.code = 'enrollment_certificate';

  IF v_type.student_visible IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'نافذة اختبار شهادة القيد تتطلب student_visible=false'
      USING ERRCODE = '42501';
  END IF;

  IF v_type.requires_attachment IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'نافذة اختبار شهادة القيد تتطلب requires_attachment=false'
      USING ERRCODE = '42501';
  END IF;

  IF p_require_inactive THEN
    IF v_type.is_active IS DISTINCT FROM false THEN
      RAISE EXCEPTION 'إنشاء مسودة E2E يتطلب is_active=false وstudent_visible=false'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT * INTO v_workflow
  FROM public.get_active_workflow_for_request_type(v_type.id);

  IF v_workflow.id IS NULL THEN
    RAISE EXCEPTION 'لا توجد workflow نشطة لشهادة القيد'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_workflow.version IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'workflow النشطة لشهادة القيد يجب أن تكون version=2'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer INTO v_steps
  FROM public.request_type_workflow_steps s
  WHERE s.workflow_id = v_workflow.id;

  SELECT count(*)::integer INTO v_transitions
  FROM public.request_type_workflow_transitions t
  WHERE t.workflow_id = v_workflow.id;

  IF v_steps IS DISTINCT FROM 7 OR v_transitions IS DISTINCT FROM 9 THEN
    RAISE EXCEPTION 'تكوين workflow شهادة القيد غير مطابق (المتوقع 7 خطوات و9 انتقالات)'
      USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_enrollment_certificate_e2e_processing_assignments();

  RETURN v_type;
END;
$$;

COMMENT ON FUNCTION public._enrollment_certificate_e2e_load_hidden_type(boolean) IS
  'Internal helper: loads enrollment_certificate and validates hidden E2E readiness '
  '(workflow v2, 7/9, six coded processing assignments, student_visible=false).';

REVOKE ALL ON FUNCTION public._enrollment_certificate_e2e_load_hidden_type(boolean)
  FROM PUBLIC, anon, authenticated;

-- =============================================================================
-- RPC: admin_create_enrollment_certificate_e2e_draft
-- =============================================================================

CREATE OR REPLACE FUNCTION public.admin_create_enrollment_certificate_e2e_draft(
  p_student_user_id uuid,
  p_e2e_marker text,
  p_student_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_marker text;
  v_type public.request_types%ROWTYPE;
  v_profile_id uuid;
  v_profile_status text;
  v_profile_count integer;
  v_existing public.student_requests%ROWTYPE;
  v_open_other integer;
  v_request_id uuid;
  v_request_number text;
  v_created_at timestamptz;
  v_form jsonb;
  v_notes text;
BEGIN
  PERFORM public.assert_can_admin_enrollment_certificate_e2e();

  IF p_student_user_id IS NULL THEN
    RAISE EXCEPTION 'معرّف الطالب مطلوب'
      USING ERRCODE = '22023';
  END IF;

  v_marker := btrim(COALESCE(p_e2e_marker, ''));
  IF char_length(v_marker) < 8 OR char_length(v_marker) > 100 THEN
    RAISE EXCEPTION 'وسم E2E يجب أن يكون بين 8 و100 حرف'
      USING ERRCODE = '22023';
  END IF;

  IF v_marker !~ '^[A-Z0-9][A-Z0-9_-]{7,99}$' THEN
    RAISE EXCEPTION 'صيغة وسم E2E غير صالحة'
      USING ERRCODE = '22023';
  END IF;

  -- Serialize create/reuse per student + enrollment_certificate (marker excluded).
  PERFORM pg_advisory_xact_lock(
    hashtext(
      'enrollment_cert_e2e_draft:'
      || p_student_user_id::text
      || ':enrollment_certificate'
    )
  );

  v_type := public._enrollment_certificate_e2e_load_hidden_type(true);

  IF NOT EXISTS (
    SELECT 1
    FROM auth.users u
    WHERE u.id = p_student_user_id
  ) THEN
    RAISE EXCEPTION 'حساب المستخدم غير موجود'
      USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM auth.users u
    WHERE u.id = p_student_user_id
      AND u.banned_until IS NOT NULL
      AND u.banned_until > now()
  ) THEN
    RAISE EXCEPTION 'حساب المستخدم موقوف'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer INTO v_profile_count
  FROM public.student_profiles sp
  WHERE sp.user_id = p_student_user_id;

  IF v_profile_count IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'ملف الطالب غير موجود أو غير فريد لهذا المستخدم'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT sp.id, sp.status
  INTO v_profile_id, v_profile_status
  FROM public.student_profiles sp
  WHERE sp.user_id = p_student_user_id;

  IF NOT public.has_any_role(p_student_user_id, ARRAY['student']::text[]) THEN
    RAISE EXCEPTION 'المستخدم لا يملك دور student'
      USING ERRCODE = '42501';
  END IF;

  PERFORM public.assert_student_can_use_request_type(
    v_profile_status,
    v_type.request_audience
  );

  -- Idempotent reuse for same student + type + marker (still draft).
  SELECT * INTO v_existing
  FROM public.student_requests sr
  WHERE sr.student_profile_id = v_profile_id
    AND sr.request_type = 'enrollment_certificate'
    AND sr.status = 'draft'
    AND COALESCE(sr.form_data->>'e2e_marker', '') = v_marker
    AND COALESCE((sr.form_data->>'internal_e2e')::boolean, false) IS TRUE
  ORDER BY sr.created_at ASC
  LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'request_id', v_existing.id,
      'request_type_id', v_type.id,
      'student_user_id', p_student_user_id,
      'status', v_existing.status,
      'e2e_marker', v_marker,
      'reused_existing', true,
      'created_at', v_existing.created_at
    );
  END IF;

  SELECT count(*)::integer INTO v_open_other
  FROM public.student_requests sr
  WHERE sr.student_profile_id = v_profile_id
    AND sr.request_type = 'enrollment_certificate'
    AND sr.status NOT IN ('approved', 'rejected', 'cancelled', 'completed')
    AND COALESCE(sr.form_data->>'e2e_marker', '') IS DISTINCT FROM v_marker;

  IF v_open_other > 0 THEN
    RAISE EXCEPTION 'يوجد طلب شهادة قيد مفتوح سابق لهذا الطالب'
      USING ERRCODE = '42501';
  END IF;

  v_form := jsonb_build_object(
    'internal_e2e', true,
    'e2e_scenario', 'zero_fee',
    'e2e_marker', v_marker,
    'created_by_admin_user_id', v_uid::text
  );

  v_notes := NULLIF(btrim(COALESCE(p_student_notes, '')), '');

  v_request_number := 'SR-' || to_char(now(), 'YYYYMMDD') || '-'
    || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  INSERT INTO public.student_requests (
    request_number,
    student_profile_id,
    request_type,
    title,
    description,
    status,
    form_data,
    student_notes
  ) VALUES (
    v_request_number,
    v_profile_id,
    v_type.code,
    'اختبار داخلي — شهادة قيد — رسوم صفرية',
    v_notes,
    'draft',
    v_form,
    v_notes
  )
  RETURNING id, created_at INTO v_request_id, v_created_at;

  PERFORM public.log_audit(
    'student_request',
    v_request_id,
    'admin_e2e_request_draft_created',
    NULL,
    jsonb_build_object(
      'student_user_id', p_student_user_id,
      'request_type_code', 'enrollment_certificate',
      'e2e_marker', v_marker,
      'scenario', 'zero_fee',
      'hidden_request_type', true,
      'status', 'draft'
    ),
    'Hidden enrollment_certificate E2E draft created by admin',
    v_uid
  );

  RETURN jsonb_build_object(
    'success', true,
    'request_id', v_request_id,
    'request_type_id', v_type.id,
    'student_user_id', p_student_user_id,
    'status', 'draft',
    'e2e_marker', v_marker,
    'reused_existing', false,
    'created_at', v_created_at
  );
END;
$$;

COMMENT ON FUNCTION public.admin_create_enrollment_certificate_e2e_draft(uuid, text, text) IS
  'Admin/system_admin only: create a draft enrollment_certificate request for a '
  'specific student while the type remains inactive+hidden. Idempotent on '
  'student+type+e2e_marker. Does not submit or initialize workflow runtime.';

REVOKE ALL ON FUNCTION public.admin_create_enrollment_certificate_e2e_draft(uuid, text, text)
  FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.admin_create_enrollment_certificate_e2e_draft(uuid, text, text)
  TO authenticated;

-- =============================================================================
-- RPC: admin_set_enrollment_certificate_e2e_submit_window
-- =============================================================================

CREATE OR REPLACE FUNCTION public.admin_set_enrollment_certificate_e2e_submit_window(
  p_open boolean,
  p_e2e_marker text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_marker text;
  v_type public.request_types%ROWTYPE;
  v_req public.student_requests%ROWTYPE;
  v_match_drafts integer;
  v_match_any integer;
  v_open_other integer;
  v_previous_active boolean;
  v_new_active boolean;
  v_profile_status text;
  v_student_user_id uuid;
  v_emergency_close boolean := false;
  v_close_audit jsonb;
BEGIN
  PERFORM public.assert_can_admin_enrollment_certificate_e2e();

  IF p_open IS NULL THEN
    RAISE EXCEPTION 'قيمة فتح/إغلاق النافذة مطلوبة'
      USING ERRCODE = '22023';
  END IF;

  v_marker := btrim(COALESCE(p_e2e_marker, ''));
  IF char_length(v_marker) < 8 OR char_length(v_marker) > 100 THEN
    RAISE EXCEPTION 'وسم E2E يجب أن يكون بين 8 و100 حرف'
      USING ERRCODE = '22023';
  END IF;

  IF v_marker !~ '^[A-Z0-9][A-Z0-9_-]{7,99}$' THEN
    RAISE EXCEPTION 'صيغة وسم E2E غير صالحة'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_type
  FROM public.request_types rt
  WHERE rt.code = 'enrollment_certificate'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'نوع طلب enrollment_certificate غير موجود'
      USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('enrollment_cert_e2e_window:' || v_type.id::text)
  );

  -- Re-read after lock.
  SELECT * INTO v_type
  FROM public.request_types rt
  WHERE rt.id = v_type.id
  FOR UPDATE;

  v_previous_active := COALESCE(v_type.is_active, false);

  IF v_type.student_visible IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'نافذة اختبار شهادة القيد تتطلب student_visible=false'
      USING ERRCODE = '42501';
  END IF;

  IF p_open IS TRUE THEN
    -- Open path: require exactly one matching draft (status=draft).
    SELECT count(*)::integer INTO v_match_drafts
    FROM public.student_requests sr
    WHERE sr.request_type = 'enrollment_certificate'
      AND COALESCE(sr.form_data->>'e2e_marker', '') = v_marker
      AND COALESCE((sr.form_data->>'internal_e2e')::boolean, false) IS TRUE
      AND COALESCE(sr.form_data->>'e2e_scenario', '') = 'zero_fee'
      AND sr.status = 'draft';

    SELECT * INTO v_req
    FROM public.student_requests sr
    WHERE sr.request_type = 'enrollment_certificate'
      AND COALESCE(sr.form_data->>'e2e_marker', '') = v_marker
      AND COALESCE((sr.form_data->>'internal_e2e')::boolean, false) IS TRUE
      AND COALESCE(sr.form_data->>'e2e_scenario', '') = 'zero_fee'
      AND sr.status = 'draft'
    ORDER BY sr.created_at ASC
    LIMIT 1;

    IF v_match_drafts = 0 OR v_req.id IS NULL THEN
      RAISE EXCEPTION 'لا توجد مسودة E2E مطابقة لوسم الاختبار'
        USING ERRCODE = 'P0002';
    END IF;

    IF v_match_drafts > 1 THEN
      RAISE EXCEPTION 'يوجد أكثر من مسودة E2E بنفس الوسم'
        USING ERRCODE = '42501';
    END IF;

    -- Opening requires full hidden readiness (inactive+hidden + workflow gates).
    PERFORM public._enrollment_certificate_e2e_load_hidden_type(true);

    SELECT count(*)::integer INTO v_open_other
    FROM public.student_requests sr
    WHERE sr.request_type = 'enrollment_certificate'
      AND sr.status NOT IN ('approved', 'rejected', 'cancelled', 'completed')
      AND sr.id IS DISTINCT FROM v_req.id;

    IF v_open_other > 0 THEN
      RAISE EXCEPTION 'يوجد طلب شهادة قيد غير نهائي آخر يمنع فتح النافذة'
        USING ERRCODE = '42501';
    END IF;

    SELECT sp.user_id, sp.status
    INTO v_student_user_id, v_profile_status
    FROM public.student_profiles sp
    WHERE sp.id = v_req.student_profile_id;

    IF v_student_user_id IS NULL THEN
      RAISE EXCEPTION 'مالك المسودة غير صالح'
        USING ERRCODE = '42501';
    END IF;

    IF NOT public.has_any_role(v_student_user_id, ARRAY['student']::text[]) THEN
      RAISE EXCEPTION 'مالك المسودة لا يملك دور student'
        USING ERRCODE = '42501';
    END IF;

    PERFORM public.assert_student_can_use_request_type(
      v_profile_status,
      v_type.request_audience
    );

    IF v_previous_active IS TRUE THEN
      RAISE EXCEPTION 'نافذة تقديم شهادة القيد مفتوحة مسبقاً'
        USING ERRCODE = '42501';
    END IF;

    UPDATE public.request_types
    SET is_active = true
    WHERE id = v_type.id
      AND student_visible IS FALSE
      AND is_active IS FALSE
    RETURNING is_active INTO v_new_active;

    IF v_new_active IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'تعذر فتح نافذة التقديم مع الإبقاء على student_visible=false'
        USING ERRCODE = '42501';
    END IF;

    -- Hard assert visibility unchanged.
    SELECT student_visible, is_active
    INTO v_type.student_visible, v_type.is_active
    FROM public.request_types
    WHERE id = v_type.id;

    IF v_type.student_visible IS DISTINCT FROM false
       OR v_type.is_active IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'حالة نوع الطلب بعد فتح النافذة غير آمنة'
        USING ERRCODE = '42501';
    END IF;

    PERFORM public.log_audit(
      'request_type',
      v_type.id,
      'enrollment_certificate_e2e_submit_window_opened',
      jsonb_build_object(
        'is_active', v_previous_active,
        'student_visible', false
      ),
      jsonb_build_object(
        'is_active', true,
        'student_visible', false,
        'e2e_marker', v_marker,
        'request_type_id', v_type.id,
        'request_id', v_req.id,
        'previous_is_active', v_previous_active,
        'new_is_active', true,
        'actor', v_uid
      ),
      'Temporary enrollment_certificate E2E submit window opened',
      v_uid
    );

    RETURN jsonb_build_object(
      'success', true,
      'window_open', true,
      'request_type_id', v_type.id,
      'request_id', v_req.id,
      'e2e_marker', v_marker,
      'is_active', true,
      'student_visible', false,
      'previous_is_active', v_previous_active,
      'new_is_active', true
    );
  END IF;

  -- Close path: restore is_active=false; keep student_visible=false.
  -- Lookup by marker across post-submit statuses (draft filter applies to open only).
  SELECT count(*)::integer INTO v_match_any
  FROM public.student_requests sr
  WHERE sr.request_type = 'enrollment_certificate'
    AND COALESCE(sr.form_data->>'e2e_marker', '') = v_marker
    AND COALESCE((sr.form_data->>'internal_e2e')::boolean, false) IS TRUE
    AND COALESCE(sr.form_data->>'e2e_scenario', '') = 'zero_fee';

  SELECT * INTO v_req
  FROM public.student_requests sr
  WHERE sr.request_type = 'enrollment_certificate'
    AND COALESCE(sr.form_data->>'e2e_marker', '') = v_marker
    AND COALESCE((sr.form_data->>'internal_e2e')::boolean, false) IS TRUE
    AND COALESCE(sr.form_data->>'e2e_scenario', '') = 'zero_fee'
  ORDER BY sr.created_at DESC
  LIMIT 1;

  IF v_match_any = 0 OR v_req.id IS NULL THEN
    v_emergency_close := true;
  END IF;

  UPDATE public.request_types
  SET is_active = false
  WHERE id = v_type.id
    AND student_visible IS FALSE
  RETURNING is_active INTO v_new_active;

  IF v_new_active IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'تعذر إغلاق نافذة التقديم بأمان'
      USING ERRCODE = '42501';
  END IF;

  -- Hard assert visibility unchanged.
  SELECT student_visible, is_active
  INTO v_type.student_visible, v_type.is_active
  FROM public.request_types
  WHERE id = v_type.id;

  IF v_type.student_visible IS DISTINCT FROM false
     OR v_type.is_active IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'حالة نوع الطلب بعد إغلاق النافذة غير آمنة'
      USING ERRCODE = '42501';
  END IF;

  v_close_audit := jsonb_build_object(
    'is_active', false,
    'student_visible', false,
    'e2e_marker', v_marker,
    'request_type_id', v_type.id,
    'request_id', v_req.id,
    'request_status_at_close', v_req.status,
    'emergency_close', v_emergency_close,
    'previous_is_active', v_previous_active,
    'new_is_active', false,
    'actor', v_uid
  );

  PERFORM public.log_audit(
    'request_type',
    v_type.id,
    'enrollment_certificate_e2e_submit_window_closed',
    jsonb_build_object(
      'is_active', v_previous_active,
      'student_visible', false
    ),
    v_close_audit,
    CASE WHEN v_emergency_close
         THEN 'Emergency close: enrollment_certificate E2E submit window forced inactive'
         ELSE 'Enrollment_certificate E2E submit window closed'
    END,
    v_uid
  );

  RETURN jsonb_build_object(
    'success', true,
    'window_open', false,
    'request_type_id', v_type.id,
    'request_id', v_req.id,
    'e2e_marker', v_marker,
    'is_active', false,
    'student_visible', false,
    'previous_is_active', v_previous_active,
    'new_is_active', false,
    'emergency_close', v_emergency_close,
    'request_status_at_close', v_req.status
  );
END;
$$;

COMMENT ON FUNCTION public.admin_set_enrollment_certificate_e2e_submit_window(boolean, text) IS
  'Admin/system_admin only: temporarily open/close is_active for enrollment_certificate '
  'while keeping student_visible=false. Open requires a matching draft; close is idempotent '
  'and supports emergency close (no matching row).';

REVOKE ALL ON FUNCTION public.admin_set_enrollment_certificate_e2e_submit_window(boolean, text)
  FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.admin_set_enrollment_certificate_e2e_submit_window(boolean, text)
  TO authenticated;

-- Migration: 20260713100000_enrollment_certificate_post_zero_fee_execution_contract_remediation_01.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260713100000', '20260713100000_enrollment_certificate_post_zero_fee_execution_contract_remediation_01') ON CONFLICT (version) DO NOTHING;
-- =============================================================================
-- ENROLLMENT-CERTIFICATE-POST-ZERO-FEE-EXECUTION-CONTRACT-REMEDIATION-01
-- Functions only — no data mutation, no seed, no request updates.
--
-- Fixes:
--   * Accept action `sign` and map sign → signed (event: signed)
--   * Map issue_document → issued, archive → archived (event types preserved)
--   * Fail closed: resolve transition BEFORE completing the runtime step
--   * Require action_type match for sign / issue_document / archive
--   * Require step status = active for mutating actions
--
-- HOLD (intentional):
--   * issue_document raises DOCUMENT_ISSUANCE_EXECUTION_CONTRACT_MISSING
--     until a durable student_request ↔ official_documents issuance path exists
--     (no student_request_id FK; no enrollment_certificate details table).
--   * archive raises ARCHIVE_REQUIRES_ISSUED_DOCUMENT_CONTRACT for the same reason.
--   Signature remapping alone is NOT safe to apply without issuance completion.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.is_valid_actor_request_action(p_action text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
  SELECT p_action IN (
    'approve',
    'reject',
    'return',
    'comment',
    'request_attachment',
    'request_payment',
    'sign',
    'archive',
    'issue_document',
    'complete',
    'skip'
  );
$$;

COMMENT ON FUNCTION public.is_valid_actor_request_action(text) IS
  'Whitelist of actor actions for staff workflow steps. Includes sign '
  '(post–zero-fee enrollment certificate remediation 01).';

CREATE OR REPLACE FUNCTION public.act_on_student_request_step(
  p_step_id uuid,
  p_action text,
  p_comment text DEFAULT NULL,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_step public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_action_result text;
  v_transition public.request_type_workflow_transitions%ROWTYPE;
  v_event_type text;
  v_visible_to_student boolean := false;
  v_new_step_status text;
  v_new_request_status text;
  v_decision text;
  v_next_runtime_step_id uuid;
  v_actor_unit_id uuid;
  v_actor_role_id uuid;
  v_required_action_type text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول'
      USING ERRCODE = '28000';
  END IF;

  -- auth.uid() only — service role without JWT cannot bypass (v_uid null → 28000).
  IF NOT public.can_current_user_act_on_step(p_step_id, p_action) THEN
    RAISE EXCEPTION 'غير مصرح بتنفيذ هذا الإجراء على هذه الخطوة'
      USING ERRCODE = '42501';
  END IF;

  SELECT s.* INTO v_step
  FROM public.student_request_workflow_steps s
  WHERE s.id = p_step_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الخطوة غير موجودة'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT c.* INTO v_config
  FROM public.request_type_workflow_steps c
  WHERE c.id = v_step.workflow_step_id;

  IF p_action IN ('reject', 'return') AND COALESCE(btrim(p_comment), '') = '' THEN
    RAISE EXCEPTION 'التعليق مطلوب لهذا الإجراء'
      USING ERRCODE = '22023';
  END IF;

  -- Comment does not mutate step status.
  IF p_action = 'comment' THEN
    INSERT INTO public.student_request_workflow_events (
      student_request_id,
      workflow_step_runtime_id,
      event_type,
      actor_user_id,
      actor_unit_id,
      actor_role_id,
      message_ar,
      payload,
      visible_to_student
    )
    VALUES (
      v_step.student_request_id,
      v_step.id,
      'commented',
      v_uid,
      v_step.processing_unit_id,
      v_step.processing_role_id,
      p_comment,
      COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('action', p_action),
      false
    );

    RETURN jsonb_build_object(
      'success', true,
      'action', p_action,
      'step_id', p_step_id,
      'terminal', false
    );
  END IF;

  -- Mutating actions require an active runtime step.
  IF v_step.status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'الخطوة ليست نشطة — لا يمكن تنفيذ الإجراء'
      USING ERRCODE = '22023';
  END IF;

  -- action_type compatibility for specialized post-fee actions.
  v_required_action_type := CASE p_action
    WHEN 'sign' THEN 'sign'
    WHEN 'issue_document' THEN 'issue_document'
    WHEN 'archive' THEN 'archive'
    ELSE NULL
  END;

  IF v_required_action_type IS NOT NULL THEN
    IF COALESCE(v_config.action_type, '') IS DISTINCT FROM v_required_action_type THEN
      RAISE EXCEPTION 'الإجراء % غير متوافق مع نوع الخطوة %',
        p_action, COALESCE(v_config.action_type, 'null')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  -- Reject approve on sign steps (forces signed transition contract).
  IF p_action = 'approve' AND COALESCE(v_config.action_type, '') = 'sign' THEN
    RAISE EXCEPTION 'خطوة التوقيع تتطلب إجراء sign وليس approve'
      USING ERRCODE = '22023';
  END IF;

  -- -------------------------------------------------------------------------
  -- HOLD: document issuance / archive execution contracts are incomplete.
  -- official_documents has no student_request_id FK; enrollment_certificate
  -- has no request-details linkage comparable to official_transcript.
  -- Do not invent inserts — fail before any runtime mutation.
  -- -------------------------------------------------------------------------
  IF p_action = 'issue_document' THEN
    RAISE EXCEPTION
      'DOCUMENT_ISSUANCE_EXECUTION_CONTRACT_MISSING: عقد إصدار شهادة القيد من خطوة workflow غير مكتمل — لا يوجد ربط student_request_id بـ official_documents ولا مسار إصدار طلب آمن'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_action = 'archive' THEN
    RAISE EXCEPTION
      'ARCHIVE_REQUIRES_ISSUED_DOCUMENT_CONTRACT: الأرشفة متوقفة حتى يكتمل عقد إصدار الوثيقة وربطها بالطلب'
      USING ERRCODE = 'P0001';
  END IF;

  v_action_result := CASE p_action
    WHEN 'approve' THEN 'approve'
    WHEN 'reject' THEN 'reject'
    WHEN 'return' THEN 'return'
    WHEN 'request_attachment' THEN 'request_attachment'
    WHEN 'request_payment' THEN 'request_payment'
    WHEN 'skip' THEN 'skip'
    WHEN 'complete' THEN 'complete'
    WHEN 'sign' THEN 'signed'
    WHEN 'archive' THEN 'archived'
    WHEN 'issue_document' THEN 'issued'
    ELSE NULL
  END;

  IF v_action_result IS NULL THEN
    RAISE EXCEPTION 'إجراء غير مدعوم: %', p_action
      USING ERRCODE = '22023';
  END IF;

  v_event_type := CASE p_action
    WHEN 'approve' THEN 'approved'
    WHEN 'reject' THEN 'rejected'
    WHEN 'return' THEN 'returned'
    WHEN 'request_attachment' THEN 'attachment_requested'
    WHEN 'request_payment' THEN 'payment_requested'
    WHEN 'sign' THEN 'signed'
    WHEN 'archive' THEN 'archived'
    WHEN 'issue_document' THEN 'document_issued'
    WHEN 'complete' THEN 'completed'
    WHEN 'skip' THEN 'approved'
    ELSE 'commented'
  END;

  v_visible_to_student := p_action IN (
    'approve', 'reject', 'return', 'request_attachment',
    'request_payment', 'complete', 'issue_document', 'sign'
  );

  v_decision := CASE p_action
    WHEN 'approve' THEN 'approved'
    WHEN 'reject' THEN 'rejected'
    WHEN 'return' THEN 'returned'
    WHEN 'skip' THEN 'skipped'
    WHEN 'complete' THEN 'completed'
    WHEN 'sign' THEN 'signed'
    WHEN 'issue_document' THEN 'issued'
    WHEN 'archive' THEN 'archived'
    ELSE NULL
  END;

  -- Fail closed: locate transition BEFORE mutating the step.
  IF v_step.workflow_id IS NULL THEN
    RAISE EXCEPTION 'لا يوجد workflow مرتبط بهذه الخطوة'
      USING ERRCODE = '22023';
  END IF;

  SELECT t.* INTO v_transition
  FROM public.request_type_workflow_transitions t
  WHERE t.workflow_id = v_step.workflow_id
    AND t.from_step_id IS NOT DISTINCT FROM v_step.workflow_step_id
    AND t.action_result = v_action_result
  ORDER BY t.is_default DESC, t.created_at
  LIMIT 1;

  IF v_transition.id IS NULL THEN
    RAISE EXCEPTION 'لا يوجد انتقال للنتيجة: %', v_action_result
      USING ERRCODE = '22023';
  END IF;

  -- If next config step exists, the matching runtime row must exist before we complete.
  IF v_transition.to_step_id IS NOT NULL THEN
    SELECT s.id INTO v_next_runtime_step_id
    FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = v_step.student_request_id
      AND s.workflow_step_id = v_transition.to_step_id
    LIMIT 1;

    IF v_next_runtime_step_id IS NULL THEN
      RAISE EXCEPTION 'الخطوة التالية غير مهيأة في runtime — أُلغيت المعاملة دون تغيير'
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  v_new_step_status := CASE p_action
    WHEN 'reject' THEN 'rejected'
    WHEN 'return' THEN 'returned'
    WHEN 'skip' THEN 'skipped'
    ELSE 'completed'
  END;

  UPDATE public.student_request_workflow_steps
  SET
    status = v_new_step_status,
    decision = v_decision,
    comment = p_comment,
    completed_by = v_uid,
    completed_at = now(),
    updated_at = now()
  WHERE id = v_step.id;

  SELECT a.unit_id, a.role_id
  INTO v_actor_unit_id, v_actor_role_id
  FROM public.current_user_processing_assignments() a
  WHERE a.unit_id IS NOT DISTINCT FROM v_step.processing_unit_id
  LIMIT 1;

  v_actor_unit_id := COALESCE(v_actor_unit_id, v_step.processing_unit_id);
  v_actor_role_id := COALESCE(v_actor_role_id, v_step.processing_role_id);

  INSERT INTO public.student_request_workflow_events (
    student_request_id,
    workflow_step_runtime_id,
    event_type,
    actor_user_id,
    actor_unit_id,
    actor_role_id,
    message_ar,
    payload,
    visible_to_student
  )
  VALUES (
    v_step.student_request_id,
    v_step.id,
    v_event_type,
    v_uid,
    v_actor_unit_id,
    v_actor_role_id,
    p_comment,
    COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object(
      'action', p_action,
      'action_result', v_action_result,
      'previous_status', v_step.status,
      'new_step_status', v_new_step_status
    ),
    v_visible_to_student
  );

  v_new_request_status := NULL;

  IF v_transition.to_step_id IS NOT NULL THEN
    UPDATE public.student_request_workflow_steps
    SET status = 'active', entered_at = now(), updated_at = now()
    WHERE id = v_next_runtime_step_id
      AND status IS DISTINCT FROM 'active';

    INSERT INTO public.student_request_workflow_events (
      student_request_id,
      workflow_step_runtime_id,
      event_type,
      actor_user_id,
      actor_unit_id,
      actor_role_id,
      message_ar,
      payload,
      visible_to_student
    )
    VALUES (
      v_step.student_request_id,
      v_next_runtime_step_id,
      'step_entered',
      v_uid,
      NULL,
      NULL,
      'دخول خطوة جديدة',
      jsonb_build_object(
        'from_step_id', v_step.id,
        'transition_id', v_transition.id,
        'action_result', v_action_result
      ),
      false
    );

    v_new_request_status := COALESCE(v_config.status_on_complete, 'in_review');
  ELSE
    -- Terminal transition (to_step_id NULL).
    v_new_request_status := CASE v_action_result
      WHEN 'reject' THEN 'rejected'
      WHEN 'return' THEN 'returned_for_completion'
      WHEN 'complete' THEN 'completed'
      WHEN 'archived' THEN 'completed'
      WHEN 'cancel' THEN 'cancelled'
      ELSE 'completed'
    END;
  END IF;

  IF v_new_request_status IS NOT NULL THEN
    UPDATE public.student_requests
    SET
      status = v_new_request_status,
      updated_at = now(),
      completed_at = CASE
        WHEN v_new_request_status IN ('completed', 'approved', 'rejected', 'cancelled')
        THEN now()
        ELSE completed_at
      END
    WHERE id = v_step.student_request_id;
  END IF;

  IF p_action = 'skip' AND public.is_current_user_admin_actor() THEN
    PERFORM public.log_audit(
      'student_request_workflow_step',
      v_step.id,
      'workflow_step_skipped',
      NULL,
      jsonb_build_object('action', p_action, 'comment', p_comment)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action,
    'action_result', v_action_result,
    'step_id', p_step_id,
    'next_step_id', v_next_runtime_step_id,
    'request_status', v_new_request_status,
    'transition_applied', true,
    'terminal', v_transition.to_step_id IS NULL
  );
END;
$$;

COMMENT ON FUNCTION public.act_on_student_request_step(uuid, text, text, jsonb) IS
  'Staff workflow actor. Maps sign→signed with fail-closed transitions. '
  'issue_document/archive raise DOCUMENT_ISSUANCE / ARCHIVE contract HOLD '
  'until request-scoped enrollment_certificate issuance exists. '
  'auth.uid() required; no service-role auth bypass.';

-- Re-assert grants (no broaden).
REVOKE ALL ON FUNCTION public.is_valid_actor_request_action(text)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_valid_actor_request_action(text)
  TO authenticated;

REVOKE ALL ON FUNCTION public.act_on_student_request_step(uuid, text, text, jsonb)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.act_on_student_request_step(uuid, text, text, jsonb)
  TO authenticated;


-- Migration: 20260713210000_enrollment_certificate_document_issuance_and_archive_contract_01.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260713210000', '20260713210000_enrollment_certificate_document_issuance_and_archive_contract_01') ON CONFLICT (version) DO NOTHING;
-- =============================================================================
-- ENROLLMENT-CERTIFICATE-DOCUMENT-ISSUANCE-AND-ARCHIVE-CONTRACT-01
-- Schema + specialized RPCs prepared for review. NOT applied to production here.
--
-- Completes durable request↔ document linkage and typed enrollment snapshot.
-- Specialized issue/archive RPCs validate the full path then FAIL CLOSED on:
--   HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING
-- because no reusable server PDF/Storage generator exists in this repo.
-- Creating official_documents alone is NOT complete issuance.
--
-- No data mutation of trial request 93807768-…, no cleanup, no backfill.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- G3 support: allow signed / issued / archived on runtime decision + events
-- ---------------------------------------------------------------------------

ALTER TABLE public.student_request_workflow_steps
  DROP CONSTRAINT IF EXISTS student_request_workflow_steps_decision_chk;

ALTER TABLE public.student_request_workflow_steps
  ADD CONSTRAINT student_request_workflow_steps_decision_chk
  CHECK (
    decision IS NULL
    OR decision IN (
      'approved',
      'rejected',
      'returned',
      'skipped',
      'completed',
      'signed',
      'issued',
      'archived'
    )
  );

ALTER TABLE public.student_request_workflow_events
  DROP CONSTRAINT IF EXISTS student_request_workflow_events_event_type_chk;

ALTER TABLE public.student_request_workflow_events
  ADD CONSTRAINT student_request_workflow_events_event_type_chk
  CHECK (event_type IN (
    'created',
    'submitted',
    'step_entered',
    'assigned',
    'commented',
    'approved',
    'rejected',
    'returned',
    'attachment_requested',
    'payment_requested',
    'signed',
    'archived',
    'document_issued',
    'completed',
    'cancelled'
  ));

-- ---------------------------------------------------------------------------
-- G1: durable student_requests ↔ official_documents link
-- ---------------------------------------------------------------------------

ALTER TABLE public.official_documents
  ADD COLUMN IF NOT EXISTS student_request_id uuid
    REFERENCES public.student_requests(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_official_documents_student_request_id
  ON public.official_documents(student_request_id);

-- At most one non-cancelled document per request (NULL allowed for legacy rows).
CREATE UNIQUE INDEX IF NOT EXISTS idx_official_documents_one_active_per_request
  ON public.official_documents(student_request_id)
  WHERE student_request_id IS NOT NULL
    AND status IS DISTINCT FROM 'cancelled';

DO $$
DECLARE
  v_conname text;
BEGIN
  FOR v_conname IN
    SELECT c.conname
    FROM pg_constraint c
    WHERE c.conrelid = 'public.official_documents'::regclass
      AND c.contype = 'c'
      AND pg_get_constraintdef(c.oid) ILIKE '%status%'
  LOOP
    EXECUTE format('ALTER TABLE public.official_documents DROP CONSTRAINT %I', v_conname);
  END LOOP;

  ALTER TABLE public.official_documents
    ADD CONSTRAINT official_documents_status_chk
    CHECK (status IN ('draft', 'issued', 'cancelled', 'archived'));
END $$;

COMMENT ON COLUMN public.official_documents.student_request_id IS
  'Optional durable link to student_requests. NULL for legacy / ad-hoc documents. '
  'At most one non-cancelled document per request (partial unique index).';

-- ---------------------------------------------------------------------------
-- G2: typed enrollment certificate details (issuance snapshot)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.enrollment_certificate_document_details (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  official_document_id uuid NOT NULL
    REFERENCES public.official_documents(id) ON DELETE CASCADE,
  student_request_id uuid NOT NULL
    REFERENCES public.student_requests(id) ON DELETE CASCADE,
  student_profile_id uuid NOT NULL
    REFERENCES public.student_profiles(id) ON DELETE RESTRICT,
  academic_number text NOT NULL,
  student_name_ar text NOT NULL,
  department_id uuid REFERENCES public.departments(id) ON DELETE SET NULL,
  department_name_ar text NOT NULL,
  program_id uuid REFERENCES public.programs(id) ON DELETE SET NULL,
  program_name_ar text NOT NULL,
  study_system text,
  student_study_status text,
  academic_year_id uuid REFERENCES public.academic_years(id) ON DELETE SET NULL,
  academic_year_name text NOT NULL,
  semester_id uuid REFERENCES public.semesters(id) ON DELETE SET NULL,
  semester_name text NOT NULL,
  level_id uuid REFERENCES public.academic_levels(id) ON DELETE SET NULL,
  level_name text NOT NULL,
  enrollment_status text NOT NULL,
  issued_snapshot_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT enrollment_certificate_document_details_doc_unique
    UNIQUE (official_document_id),
  CONSTRAINT enrollment_certificate_document_details_request_unique
    UNIQUE (student_request_id)
);

CREATE INDEX IF NOT EXISTS idx_ecdd_student_profile
  ON public.enrollment_certificate_document_details(student_profile_id);

CREATE INDEX IF NOT EXISTS idx_ecdd_request
  ON public.enrollment_certificate_document_details(student_request_id);

COMMENT ON TABLE public.enrollment_certificate_document_details IS
  'Issuance-time academic snapshot for enrollment certificates. Verification and '
  'document views must prefer this snapshot over live student profile data.';

GRANT SELECT, INSERT, UPDATE ON public.enrollment_certificate_document_details TO authenticated;
GRANT ALL ON public.enrollment_certificate_document_details TO service_role;

ALTER TABLE public.enrollment_certificate_document_details ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'enrollment_certificate_document_details'
      AND policyname = 'ecdd_select'
  ) THEN
    CREATE POLICY ecdd_select ON public.enrollment_certificate_document_details
      FOR SELECT TO authenticated
      USING (
        public.is_owner_of_request(auth.uid(), student_request_id)
        OR public.has_any_role(
          auth.uid(),
          ARRAY['admin', 'system_admin', 'dean', 'registrar', 'student_affairs']
        )
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'enrollment_certificate_document_details'
      AND policyname = 'ecdd_staff_insert'
  ) THEN
    CREATE POLICY ecdd_staff_insert ON public.enrollment_certificate_document_details
      FOR INSERT TO authenticated
      WITH CHECK (
        public.has_any_role(
          auth.uid(),
          ARRAY['admin', 'system_admin', 'dean', 'registrar', 'student_affairs']
        )
      );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'enrollment_certificate_document_details'
      AND policyname = 'ecdd_staff_update'
  ) THEN
    CREATE POLICY ecdd_staff_update ON public.enrollment_certificate_document_details
      FOR UPDATE TO authenticated
      USING (
        public.has_any_role(
          auth.uid(),
          ARRAY['admin', 'system_admin', 'dean', 'registrar', 'student_affairs']
        )
      );
  END IF;
END $$;

DROP TRIGGER IF EXISTS trg_ecdd_updated_at ON public.enrollment_certificate_document_details;
CREATE TRIGGER trg_ecdd_updated_at
  BEFORE UPDATE ON public.enrollment_certificate_document_details
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- ---------------------------------------------------------------------------
-- PDF/Storage gate — no inventing file generation
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.assert_enrollment_certificate_pdf_generation_ready()
RETURNS void
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
BEGIN
  -- Catalog scan is intentional: no official-documents Storage bucket / PDF
  -- generator exists in this codebase path. Keep fail-closed until a durable
  -- reusable generator is introduced in a later phase.
  RAISE EXCEPTION
    'HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING: مولّد PDF/Storage لشهادة القيد غير متوفر كمسار خادم قابل لإعادة الاستخدام — إنشاء صف official_documents وحده لا يُعد إصداراً كاملاً'
    USING ERRCODE = 'P0001';
END;
$$;

COMMENT ON FUNCTION public.assert_enrollment_certificate_pdf_generation_ready() IS
  'Always raises HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING until '
  'a reusable server PDF/Storage generator is introduced. Do not remove without '
  'replacing with a real generator that writes an accessible file artifact.';

REVOKE ALL ON FUNCTION public.assert_enrollment_certificate_pdf_generation_ready()
  FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Snapshot builder (read-only; used by issue RPC after PDF gate is lifted)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.build_enrollment_certificate_issuance_snapshot(
  p_student_profile_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_sp public.student_profiles%ROWTYPE;
  v_sas public.student_academic_status%ROWTYPE;
  v_dept_name text;
  v_program_name text;
  v_year_name text;
  v_semester_name text;
  v_level_name text;
BEGIN
  SELECT * INTO v_sp
  FROM public.student_profiles
  WHERE id = p_student_profile_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الطالب غير موجود'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_sas
  FROM public.student_academic_status
  WHERE student_profile_id = p_student_profile_id
  ORDER BY updated_at DESC NULLS LAST, created_at DESC
  LIMIT 1;

  SELECT d.name_ar INTO v_dept_name
  FROM public.departments d
  WHERE d.id = v_sp.department_id;

  SELECT p.name_ar INTO v_program_name
  FROM public.programs p
  WHERE p.id = v_sp.program_id;

  IF v_sas.academic_year_id IS NOT NULL THEN
    SELECT ay.name INTO v_year_name
    FROM public.academic_years ay
    WHERE ay.id = v_sas.academic_year_id;
  END IF;

  IF v_sas.semester_id IS NOT NULL THEN
    SELECT s.name INTO v_semester_name
    FROM public.semesters s
    WHERE s.id = v_sas.semester_id;
  END IF;

  IF v_sas.level_id IS NOT NULL THEN
    SELECT l.name INTO v_level_name
    FROM public.academic_levels l
    WHERE l.id = v_sas.level_id;
  END IF;

  IF NULLIF(btrim(COALESCE(v_sp.academic_number, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(v_sp.full_name_ar, '')), '') IS NULL
     OR v_sp.department_id IS NULL
     OR NULLIF(btrim(COALESCE(v_dept_name, '')), '') IS NULL
     OR v_sp.program_id IS NULL
     OR NULLIF(btrim(COALESCE(v_program_name, '')), '') IS NULL
     OR v_sas.id IS NULL
     OR v_sas.academic_year_id IS NULL
     OR NULLIF(btrim(COALESCE(v_year_name, '')), '') IS NULL
     OR v_sas.semester_id IS NULL
     OR NULLIF(btrim(COALESCE(v_semester_name, '')), '') IS NULL
     OR v_sas.level_id IS NULL
     OR NULLIF(btrim(COALESCE(v_level_name, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(v_sas.enrollment_status, '')), '') IS NULL
  THEN
    RAISE EXCEPTION 'اللقطة الأكاديمية غير مكتملة — لا يمكن إصدار شهادة القيد'
      USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'student_profile_id', v_sp.id,
    'academic_number', v_sp.academic_number,
    'student_name_ar', v_sp.full_name_ar,
    'department_id', v_sp.department_id,
    'department_name_ar', v_dept_name,
    'program_id', v_sp.program_id,
    'program_name_ar', v_program_name,
    'study_system', v_sp.study_system,
    'student_study_status', v_sp.student_study_status,
    'academic_year_id', v_sas.academic_year_id,
    'academic_year_name', v_year_name,
    'semester_id', v_sas.semester_id,
    'semester_name', v_semester_name,
    'level_id', v_sas.level_id,
    'level_name', v_level_name,
    'enrollment_status', v_sas.enrollment_status,
    'issued_snapshot_at', now()
  );
END;
$$;

COMMENT ON FUNCTION public.build_enrollment_certificate_issuance_snapshot(uuid) IS
  'Builds complete academic snapshot for enrollment certificate issuance. '
  'Raises if any required field is missing. Prefer details table after issue.';

REVOKE ALL ON FUNCTION public.build_enrollment_certificate_issuance_snapshot(uuid)
  FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------------
-- G4: specialized issuance RPC (fail-closed on PDF before any issued write)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.issue_enrollment_certificate_from_workflow_step(
  p_step_id uuid,
  p_comment text DEFAULT NULL,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_step public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_req public.student_requests%ROWTYPE;
  v_fee public.student_request_fee_assessments%ROWTYPE;
  v_registrar_ok boolean := false;
  v_dean_ok boolean := false;
  v_snapshot jsonb;
  v_existing uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول'
      USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_current_user_act_on_step(p_step_id, 'issue_document') THEN
    RAISE EXCEPTION 'غير مصرح بتنفيذ هذا الإجراء على هذه الخطوة'
      USING ERRCODE = '42501';
  END IF;

  SELECT s.* INTO v_step
  FROM public.student_request_workflow_steps s
  WHERE s.id = p_step_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الخطوة غير موجودة'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT c.* INTO v_config
  FROM public.request_type_workflow_steps c
  WHERE c.id = v_step.workflow_step_id;

  SELECT r.* INTO v_req
  FROM public.student_requests r
  WHERE r.id = v_step.student_request_id
  FOR UPDATE;

  IF v_req.request_type IS DISTINCT FROM 'enrollment_certificate' THEN
    RAISE EXCEPTION 'الإصدار مخصص لطلب شهادة القيد فقط'
      USING ERRCODE = '22023';
  END IF;

  IF v_req.status IN ('cancelled', 'rejected', 'completed') THEN
    RAISE EXCEPTION 'لا يمكن إصدار وثيقة لطلب منتهٍ أو مرفوض أو ملغى'
      USING ERRCODE = '22023';
  END IF;

  IF v_step.status IS DISTINCT FROM 'active'
     OR COALESCE(v_step.step_key, '') IS DISTINCT FROM 'document_issuance'
     OR COALESCE(v_config.action_type, '') IS DISTINCT FROM 'issue_document'
  THEN
    RAISE EXCEPTION 'خطوة الإصدار ليست النشطة أو غير متوافقة'
      USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = v_req.id
      AND s.step_key = 'registrar_signature'
      AND s.status = 'completed'
      AND s.decision = 'signed'
  ) INTO v_registrar_ok;

  SELECT EXISTS (
    SELECT 1
    FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = v_req.id
      AND s.step_key = 'dean_signature'
      AND s.status = 'completed'
      AND s.decision = 'signed'
  ) INTO v_dean_ok;

  IF NOT v_registrar_ok OR NOT v_dean_ok THEN
    RAISE EXCEPTION 'توقيع المسجل والعميد مطلوبان قبل الإصدار'
      USING ERRCODE = '22023';
  END IF;

  SELECT f.* INTO v_fee
  FROM public.student_request_fee_assessments f
  WHERE f.request_id = v_req.id
    AND f.payment_status <> 'cancelled'
  ORDER BY f.created_at DESC
  LIMIT 1;

  IF NOT FOUND
     OR v_fee.payment_status NOT IN ('not_required', 'paid', 'waived')
  THEN
    RAISE EXCEPTION 'تقييم الرسوم يجب أن يكون not_required أو paid أو waived'
      USING ERRCODE = '22023';
  END IF;

  SELECT d.id INTO v_existing
  FROM public.official_documents d
  WHERE d.student_request_id = v_req.id
    AND d.status IS DISTINCT FROM 'cancelled'
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'توجد وثيقة فعّالة مرتبطة بهذا الطلب مسبقاً'
      USING ERRCODE = '22023';
  END IF;

  -- Snapshot completeness gate (raises if incomplete).
  v_snapshot := public.build_enrollment_certificate_issuance_snapshot(v_req.student_profile_id);

  -- CRITICAL: fail before creating document/file/status transitions.
  -- G4: do not treat row insert as issuance without durable file generation.
  PERFORM public.assert_enrollment_certificate_pdf_generation_ready();

  -- Unreachable until PDF generator is implemented.
  RETURN jsonb_build_object(
    'success', false,
    'code', 'HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING',
    'step_id', p_step_id,
    'snapshot_keys', (SELECT array_agg(key) FROM jsonb_object_keys(v_snapshot) AS key),
    'comment', p_comment,
    'payload', COALESCE(p_payload, '{}'::jsonb)
  );
END;
$$;

COMMENT ON FUNCTION public.issue_enrollment_certificate_from_workflow_step(uuid, text, jsonb) IS
  'Enrollment certificate issuance from document_issuance step. Validates signatures, '
  'fees, snapshot, and uniqueness then raises PDF HOLD before any issued write.';

REVOKE ALL ON FUNCTION public.issue_enrollment_certificate_from_workflow_step(uuid, text, jsonb)
  FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.issue_enrollment_certificate_from_workflow_step(uuid, text, jsonb)
  TO authenticated;

-- ---------------------------------------------------------------------------
-- G6: specialized archive RPC (requires issued linked document + accessible file)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.archive_enrollment_certificate_from_workflow_step(
  p_step_id uuid,
  p_comment text DEFAULT NULL,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_step public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_req public.student_requests%ROWTYPE;
  v_doc public.official_documents%ROWTYPE;
  v_registrar_ok boolean := false;
  v_dean_ok boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول'
      USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_current_user_act_on_step(p_step_id, 'archive') THEN
    RAISE EXCEPTION 'غير مصرح بتنفيذ هذا الإجراء على هذه الخطوة'
      USING ERRCODE = '42501';
  END IF;

  SELECT s.* INTO v_step
  FROM public.student_request_workflow_steps s
  WHERE s.id = p_step_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الخطوة غير موجودة'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT c.* INTO v_config
  FROM public.request_type_workflow_steps c
  WHERE c.id = v_step.workflow_step_id;

  SELECT r.* INTO v_req
  FROM public.student_requests r
  WHERE r.id = v_step.student_request_id
  FOR UPDATE;

  IF v_step.status IS DISTINCT FROM 'active'
     OR COALESCE(v_step.step_key, '') IS DISTINCT FROM 'archive'
     OR COALESCE(v_config.action_type, '') IS DISTINCT FROM 'archive'
  THEN
    RAISE EXCEPTION 'خطوة الأرشفة ليست النشطة أو غير متوافقة'
      USING ERRCODE = '22023';
  END IF;

  IF v_req.status IN ('cancelled', 'rejected') THEN
    RAISE EXCEPTION 'لا يمكن أرشفة طلب مرفوض أو ملغى'
      USING ERRCODE = '22023';
  END IF;

  SELECT d.* INTO v_doc
  FROM public.official_documents d
  WHERE d.student_request_id = v_req.id
    AND d.status IS DISTINCT FROM 'cancelled'
  ORDER BY d.issued_at DESC NULLS LAST
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'لا توجد وثيقة مرتبطة بالطلب'
      USING ERRCODE = '22023';
  END IF;

  IF v_doc.status IS DISTINCT FROM 'issued' AND v_doc.status IS DISTINCT FROM 'archived' THEN
    RAISE EXCEPTION 'الأرشفة تتطلب وثيقة صادرة'
      USING ERRCODE = '22023';
  END IF;

  IF NULLIF(btrim(COALESCE(v_doc.pdf_url, '')), '') IS NULL THEN
    RAISE EXCEPTION
      'HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING: الملف الفعلي للوثيقة غير موجود أو غير قابل للوصول داخلياً'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = v_req.id
      AND s.step_key = 'registrar_signature'
      AND s.status = 'completed' AND s.decision = 'signed'
  ) INTO v_registrar_ok;

  SELECT EXISTS (
    SELECT 1 FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = v_req.id
      AND s.step_key = 'dean_signature'
      AND s.status = 'completed' AND s.decision = 'signed'
  ) INTO v_dean_ok;

  IF NOT v_registrar_ok OR NOT v_dean_ok THEN
    RAISE EXCEPTION 'التوقيعات يجب أن تكون مكتملة قبل الأرشفة'
      USING ERRCODE = '22023';
  END IF;

  -- Hard stop: until PDF/file generation exists, archive remains gated.
  PERFORM public.assert_enrollment_certificate_pdf_generation_ready();

  RETURN jsonb_build_object(
    'success', false,
    'code', 'HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING',
    'step_id', p_step_id,
    'document_id', v_doc.id,
    'comment', p_comment,
    'payload', COALESCE(p_payload, '{}'::jsonb)
  );
END;
$$;

COMMENT ON FUNCTION public.archive_enrollment_certificate_from_workflow_step(uuid, text, jsonb) IS
  'Archive enrollment certificate workflow step. Requires linked issued document '
  'with accessible file; currently fails closed on PDF HOLD.';

REVOKE ALL ON FUNCTION public.archive_enrollment_certificate_from_workflow_step(uuid, text, jsonb)
  FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.archive_enrollment_certificate_from_workflow_step(uuid, text, jsonb)
  TO authenticated;

-- ---------------------------------------------------------------------------
-- Wire act_on: preserve post-zero-fee sign path; route enrollment issue/archive
-- to specialized RPCs that HOLD on missing PDF generation before any mutation.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.act_on_student_request_step(
  p_step_id uuid,
  p_action text,
  p_comment text DEFAULT NULL,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_step public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_action_result text;
  v_transition public.request_type_workflow_transitions%ROWTYPE;
  v_event_type text;
  v_visible_to_student boolean := false;
  v_new_step_status text;
  v_new_request_status text;
  v_decision text;
  v_next_runtime_step_id uuid;
  v_actor_unit_id uuid;
  v_actor_role_id uuid;
  v_required_action_type text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول'
      USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_current_user_act_on_step(p_step_id, p_action) THEN
    RAISE EXCEPTION 'غير مصرح بتنفيذ هذا الإجراء على هذه الخطوة'
      USING ERRCODE = '42501';
  END IF;

  SELECT s.* INTO v_step
  FROM public.student_request_workflow_steps s
  WHERE s.id = p_step_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'الخطوة غير موجودة'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT c.* INTO v_config
  FROM public.request_type_workflow_steps c
  WHERE c.id = v_step.workflow_step_id;

  IF p_action IN ('reject', 'return') AND COALESCE(btrim(p_comment), '') = '' THEN
    RAISE EXCEPTION 'التعليق مطلوب لهذا الإجراء'
      USING ERRCODE = '22023';
  END IF;

  IF p_action = 'comment' THEN
    INSERT INTO public.student_request_workflow_events (
      student_request_id,
      workflow_step_runtime_id,
      event_type,
      actor_user_id,
      actor_unit_id,
      actor_role_id,
      message_ar,
      payload,
      visible_to_student
    )
    VALUES (
      v_step.student_request_id,
      v_step.id,
      'commented',
      v_uid,
      v_step.processing_unit_id,
      v_step.processing_role_id,
      p_comment,
      COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('action', p_action),
      false
    );

    RETURN jsonb_build_object(
      'success', true,
      'action', p_action,
      'step_id', p_step_id,
      'terminal', false
    );
  END IF;

  IF v_step.status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'الخطوة ليست نشطة — لا يمكن تنفيذ الإجراء'
      USING ERRCODE = '22023';
  END IF;

  v_required_action_type := CASE p_action
    WHEN 'sign' THEN 'sign'
    WHEN 'issue_document' THEN 'issue_document'
    WHEN 'archive' THEN 'archive'
    ELSE NULL
  END;

  IF v_required_action_type IS NOT NULL THEN
    IF COALESCE(v_config.action_type, '') IS DISTINCT FROM v_required_action_type THEN
      RAISE EXCEPTION 'الإجراء % غير متوافق مع نوع الخطوة %',
        p_action, COALESCE(v_config.action_type, 'null')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_action = 'approve' AND COALESCE(v_config.action_type, '') = 'sign' THEN
    RAISE EXCEPTION 'خطوة التوقيع تتطلب إجراء sign وليس approve'
      USING ERRCODE = '22023';
  END IF;

  -- Delegate enrollment_certificate issue/archive (PDF HOLD inside specialized RPCs).
  IF p_action = 'issue_document' THEN
    IF (
      SELECT r.request_type FROM public.student_requests r
      WHERE r.id = v_step.student_request_id
    ) = 'enrollment_certificate' THEN
      RETURN public.issue_enrollment_certificate_from_workflow_step(p_step_id, p_comment, p_payload);
    END IF;
    RAISE EXCEPTION
      'DOCUMENT_ISSUANCE_EXECUTION_CONTRACT_MISSING: عقد إصدار الوثيقة لهذا النوع غير مكتمل'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_action = 'archive' THEN
    IF (
      SELECT r.request_type FROM public.student_requests r
      WHERE r.id = v_step.student_request_id
    ) = 'enrollment_certificate' THEN
      RETURN public.archive_enrollment_certificate_from_workflow_step(p_step_id, p_comment, p_payload);
    END IF;
    RAISE EXCEPTION
      'ARCHIVE_REQUIRES_ISSUED_DOCUMENT_CONTRACT: الأرشفة متوقفة حتى يكتمل عقد الإصدار'
      USING ERRCODE = 'P0001';
  END IF;

  v_action_result := CASE p_action
    WHEN 'approve' THEN 'approve'
    WHEN 'reject' THEN 'reject'
    WHEN 'return' THEN 'return'
    WHEN 'request_attachment' THEN 'request_attachment'
    WHEN 'request_payment' THEN 'request_payment'
    WHEN 'skip' THEN 'skip'
    WHEN 'complete' THEN 'complete'
    WHEN 'sign' THEN 'signed'
    WHEN 'archive' THEN 'archived'
    WHEN 'issue_document' THEN 'issued'
    ELSE NULL
  END;

  IF v_action_result IS NULL THEN
    RAISE EXCEPTION 'إجراء غير مدعوم: %', p_action
      USING ERRCODE = '22023';
  END IF;

  v_event_type := CASE p_action
    WHEN 'approve' THEN 'approved'
    WHEN 'reject' THEN 'rejected'
    WHEN 'return' THEN 'returned'
    WHEN 'request_attachment' THEN 'attachment_requested'
    WHEN 'request_payment' THEN 'payment_requested'
    WHEN 'sign' THEN 'signed'
    WHEN 'archive' THEN 'archived'
    WHEN 'issue_document' THEN 'document_issued'
    WHEN 'complete' THEN 'completed'
    WHEN 'skip' THEN 'approved'
    ELSE 'commented'
  END;

  v_visible_to_student := p_action IN (
    'approve', 'reject', 'return', 'request_attachment',
    'request_payment', 'complete', 'issue_document', 'sign'
  );

  v_decision := CASE p_action
    WHEN 'approve' THEN 'approved'
    WHEN 'reject' THEN 'rejected'
    WHEN 'return' THEN 'returned'
    WHEN 'skip' THEN 'skipped'
    WHEN 'complete' THEN 'completed'
    WHEN 'sign' THEN 'signed'
    WHEN 'issue_document' THEN 'issued'
    WHEN 'archive' THEN 'archived'
    ELSE NULL
  END;

  IF v_step.workflow_id IS NULL THEN
    RAISE EXCEPTION 'لا يوجد workflow مرتبط بهذه الخطوة'
      USING ERRCODE = '22023';
  END IF;

  SELECT t.* INTO v_transition
  FROM public.request_type_workflow_transitions t
  WHERE t.workflow_id = v_step.workflow_id
    AND t.from_step_id IS NOT DISTINCT FROM v_step.workflow_step_id
    AND t.action_result = v_action_result
  ORDER BY t.is_default DESC, t.created_at
  LIMIT 1;

  IF v_transition.id IS NULL THEN
    RAISE EXCEPTION 'لا يوجد انتقال للنتيجة: %', v_action_result
      USING ERRCODE = '22023';
  END IF;

  IF v_transition.to_step_id IS NOT NULL THEN
    SELECT s.id INTO v_next_runtime_step_id
    FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = v_step.student_request_id
      AND s.workflow_step_id = v_transition.to_step_id
    LIMIT 1;

    IF v_next_runtime_step_id IS NULL THEN
      RAISE EXCEPTION 'الخطوة التالية غير مهيأة في runtime — أُلغيت المعاملة دون تغيير'
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  v_new_step_status := CASE p_action
    WHEN 'reject' THEN 'rejected'
    WHEN 'return' THEN 'returned'
    WHEN 'skip' THEN 'skipped'
    ELSE 'completed'
  END;

  UPDATE public.student_request_workflow_steps
  SET
    status = v_new_step_status,
    decision = v_decision,
    comment = p_comment,
    completed_by = v_uid,
    completed_at = now(),
    updated_at = now()
  WHERE id = v_step.id;

  SELECT a.unit_id, a.role_id
  INTO v_actor_unit_id, v_actor_role_id
  FROM public.current_user_processing_assignments() a
  WHERE a.unit_id IS NOT DISTINCT FROM v_step.processing_unit_id
  LIMIT 1;

  v_actor_unit_id := COALESCE(v_actor_unit_id, v_step.processing_unit_id);
  v_actor_role_id := COALESCE(v_actor_role_id, v_step.processing_role_id);

  INSERT INTO public.student_request_workflow_events (
    student_request_id,
    workflow_step_runtime_id,
    event_type,
    actor_user_id,
    actor_unit_id,
    actor_role_id,
    message_ar,
    payload,
    visible_to_student
  )
  VALUES (
    v_step.student_request_id,
    v_step.id,
    v_event_type,
    v_uid,
    v_actor_unit_id,
    v_actor_role_id,
    p_comment,
    COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object(
      'action', p_action,
      'action_result', v_action_result,
      'previous_status', v_step.status,
      'new_step_status', v_new_step_status
    ),
    v_visible_to_student
  );

  v_new_request_status := NULL;

  IF v_transition.to_step_id IS NOT NULL THEN
    UPDATE public.student_request_workflow_steps
    SET status = 'active', entered_at = now(), updated_at = now()
    WHERE id = v_next_runtime_step_id
      AND status IS DISTINCT FROM 'active';

    INSERT INTO public.student_request_workflow_events (
      student_request_id,
      workflow_step_runtime_id,
      event_type,
      actor_user_id,
      actor_unit_id,
      actor_role_id,
      message_ar,
      payload,
      visible_to_student
    )
    VALUES (
      v_step.student_request_id,
      v_next_runtime_step_id,
      'step_entered',
      v_uid,
      NULL,
      NULL,
      'دخول خطوة جديدة',
      jsonb_build_object(
        'from_step_id', v_step.id,
        'transition_id', v_transition.id,
        'action_result', v_action_result
      ),
      false
    );

    v_new_request_status := COALESCE(v_config.status_on_complete, 'in_review');
  ELSE
    v_new_request_status := CASE v_action_result
      WHEN 'reject' THEN 'rejected'
      WHEN 'return' THEN 'returned_for_completion'
      WHEN 'complete' THEN 'completed'
      WHEN 'archived' THEN 'completed'
      WHEN 'cancel' THEN 'cancelled'
      ELSE 'completed'
    END;
  END IF;

  IF v_new_request_status IS NOT NULL THEN
    UPDATE public.student_requests
    SET
      status = v_new_request_status,
      updated_at = now(),
      completed_at = CASE
        WHEN v_new_request_status IN ('completed', 'approved', 'rejected', 'cancelled')
        THEN now()
        ELSE completed_at
      END
    WHERE id = v_step.student_request_id;
  END IF;

  IF p_action = 'skip' AND public.is_current_user_admin_actor() THEN
    PERFORM public.log_audit(
      'student_request_workflow_step',
      v_step.id,
      'workflow_step_skipped',
      NULL,
      jsonb_build_object('action', p_action, 'comment', p_comment)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action,
    'action_result', v_action_result,
    'step_id', p_step_id,
    'next_step_id', v_next_runtime_step_id,
    'request_status', v_new_request_status,
    'transition_applied', true,
    'terminal', v_transition.to_step_id IS NULL
  );
END;
$$;

COMMENT ON FUNCTION public.act_on_student_request_step(uuid, text, text, jsonb) IS
  'Staff workflow actor. Maps sign→signed with fail-closed transitions. '
  'Enrollment certificate issue_document/archive delegate to specialized RPCs '
  'that HOLD on HOLD_ENROLLMENT_CERTIFICATE_PDF_GENERATION_CONTRACT_MISSING. '
  'auth.uid() required; no service-role auth bypass.';

REVOKE ALL ON FUNCTION public.act_on_student_request_step(uuid, text, text, jsonb)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.act_on_student_request_step(uuid, text, text, jsonb)
  TO authenticated;

-- ---------------------------------------------------------------------------
-- G5: public verification — expose safe fields including student identity
-- Prefer enrollment snapshot when present; never expose verification_code back.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.verify_document(_query text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_doc public.official_documents%ROWTYPE;
  v_q text := upper(trim(COALESCE(_query, '')));
  v_name text;
  v_academic text;
BEGIN
  IF length(v_q) < 6 THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'invalid_input');
  END IF;

  SELECT * INTO v_doc
  FROM public.official_documents
  WHERE upper(document_number) = v_q
     OR upper(verification_code) = v_q
  LIMIT 1;

  IF v_doc.id IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'not_found');
  END IF;

  SELECT d.student_name_ar, d.academic_number
    INTO v_name, v_academic
  FROM public.enrollment_certificate_document_details d
  WHERE d.official_document_id = v_doc.id;

  IF v_name IS NULL THEN
    SELECT sp.full_name_ar, sp.academic_number
      INTO v_name, v_academic
    FROM public.student_profiles sp
    WHERE sp.id = v_doc.student_profile_id;
  END IF;

  RETURN jsonb_build_object(
    'valid', v_doc.status IN ('issued', 'archived'),
    'document_type', v_doc.document_type,
    'document_number', v_doc.document_number,
    'status', v_doc.status,
    'issued_at', v_doc.issued_at,
    'student_name_ar', v_name,
    'academic_number', v_academic
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.verify_document(text) TO anon, authenticated;


