CREATE OR REPLACE FUNCTION public.get_public_faculty_directory()
RETURNS TABLE (
  id uuid,
  employee_id text,
  full_name_ar text,
  full_name_en text,
  degree text,
  specialization text,
  program_id uuid,
  rank text,
  photo text,
  bio_ar text,
  bio_en text,
  sort_order integer,
  is_active boolean,
  category text,
  start_year integer,
  admin_position text,
  admin_position_order integer,
  programs jsonb
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT
    f.id,
    f.employee_id,
    f.full_name_ar,
    f.full_name_en,
    f.degree,
    f.specialization,
    f.program_id,
    f.rank,
    f.photo,
    f.bio_ar,
    f.bio_en,
    f.sort_order,
    f.is_active,
    f.category,
    f.start_year,
    f.admin_position,
    f.admin_position_order,
    CASE WHEN p.id IS NULL THEN NULL
         ELSE jsonb_build_object('code', p.code, 'name_ar', p.name_ar)
    END AS programs
  FROM public.faculty f
  LEFT JOIN public.programs p ON p.id = f.program_id
  WHERE f.is_active = true
  ORDER BY f.admin_position_order ASC NULLS LAST, f.sort_order ASC, f.full_name_ar ASC, f.id ASC;
$$;

