  (unit_id, role_id, assignment_type, faculty_profile_id, department_id, is_active)
SELECT (SELECT id FROM u),
       (SELECT id FROM r),
       'faculty_profile',
       fp.id,
       fp.department_id,
       true
FROM public.faculty_profiles fp
JOIN chairs c ON c.faculty_profile_id = fp.id
WHERE NOT EXISTS (
