-- New function. Copied VERBATIM from -01; no production conflict.
create or replace function public.workflow_action_result_matches(p_action_type text,p_result text)
returns boolean language sql immutable set search_path=public as $function$
  select case p_action_type
    when 'review' then p_result='reviewed'
    when 'approve' then p_result='approved'
    when 'apply_decision' then p_result='applied'
    when 'clear' then p_result='cleared'
    when 'archive' then p_result='archived'
    when 'confirm_payment' then p_result='payment_confirmed'
    when 'sign' then p_result='signed'
    when 'issue_document' then p_result='issued'
    else false end
$function$;

-- New function. Copied VERBATIM from -01; no production conflict.
create or replace function public.workflow_runtime_predecessors_satisfied(p_step_id uuid)
returns boolean
language plpgsql stable security definer set search_path=public
as $function$
declare
  v_step public.student_request_workflow_steps%rowtype;
  v_config public.request_type_workflow_steps%rowtype;
  v_incoming integer;
  v_pred record;
begin
  if p_step_id is null then return false; end if;
  select * into v_step from public.student_request_workflow_steps where id=p_step_id;
  if not found or v_step.status<>'active' or v_step.workflow_id is null or v_step.workflow_step_id is null then return false; end if;

  select * into v_config from public.request_type_workflow_steps
    where id=v_step.workflow_step_id and workflow_id=v_step.workflow_id;
  if not found or v_config.step_key is distinct from v_step.step_key
    or v_config.step_order is distinct from v_step.step_order then return false; end if;

  -- Runtime/config correspondence is exactly one for this request and version.
  if (select count(*) from public.student_request_workflow_steps r
      where r.student_request_id=v_step.student_request_id and r.workflow_id=v_step.workflow_id
        and r.workflow_step_id=v_step.workflow_step_id)<>1 then return false; end if;

  select count(*) into v_incoming from public.request_type_workflow_transitions t
    where t.workflow_id=v_step.workflow_id and t.to_step_id=v_step.workflow_step_id;
  if v_config.step_order=1 then
    if v_incoming<>1 or not exists(select 1 from public.request_type_workflow_transitions t
      where t.workflow_id=v_step.workflow_id and t.from_step_id is null
        and t.to_step_id=v_step.workflow_step_id and t.action_result='submit') then return false; end if;
  elsif v_incoming=0 then return false;
  end if;
  if v_config.step_order<>1 and exists(select 1 from public.request_type_workflow_transitions t
    where t.workflow_id=v_step.workflow_id and t.to_step_id=v_step.workflow_step_id
      and t.from_step_id is null) then return false; end if;
  if exists(select 1 from public.request_type_workflow_transitions t
    where t.workflow_id=v_step.workflow_id and t.to_step_id=v_step.workflow_step_id
    group by t.from_step_id,t.to_step_id having count(*)<>1) then return false; end if;
  if exists(
    select 1 from public.request_type_workflow_transitions t
    left join public.request_type_workflow_steps source_config on source_config.id=t.from_step_id
    left join public.request_type_workflow_steps target_config on target_config.id=t.to_step_id
    where t.workflow_id=v_step.workflow_id and
      ((t.from_step_id is not null and source_config.workflow_id is distinct from t.workflow_id) or
       (t.to_step_id is not null and target_config.workflow_id is distinct from t.workflow_id))
  ) then return false; end if;

  -- Every incoming edge is unique and its exact predecessor runtime is terminal-valid.
  for v_pred in
    select t.from_step_id,t.action_result,pc.can_skip,pc.action_type from public.request_type_workflow_transitions t
    left join public.request_type_workflow_steps pc on pc.id=t.from_step_id and pc.workflow_id=t.workflow_id
    where t.workflow_id=v_step.workflow_id and t.to_step_id=v_step.workflow_step_id
      and t.from_step_id is not null
  loop
    if v_pred.can_skip is null then return false; end if;
    if not public.workflow_action_result_matches(v_pred.action_type,v_pred.action_result)
      and not (v_pred.action_result='skip' and v_pred.can_skip) then return false; end if;
    if (select count(*) from public.student_request_workflow_steps pr
        where pr.student_request_id=v_step.student_request_id and pr.workflow_id=v_step.workflow_id
          and pr.workflow_step_id=v_pred.from_step_id)<>1 then return false; end if;
    if not exists(select 1 from public.student_request_workflow_steps pr
        where pr.student_request_id=v_step.student_request_id and pr.workflow_id=v_step.workflow_id
          and pr.workflow_step_id=v_pred.from_step_id
          and (pr.status='completed' or (pr.status='skipped' and v_pred.can_skip))) then return false; end if;
  end loop;

  -- Every earlier required config must have one terminal-valid runtime and a
  -- legal directed path to this step. A mere runtime row is never sufficient.
  if exists (
    select 1 from public.request_type_workflow_steps pc
    where pc.workflow_id=v_step.workflow_id and pc.step_order<v_config.step_order and pc.is_required
      and ((select count(*) from public.student_request_workflow_steps pr
            where pr.student_request_id=v_step.student_request_id and pr.workflow_id=v_step.workflow_id
              and pr.workflow_step_id=pc.id)<>1
        or not exists(select 1 from public.student_request_workflow_steps pr
            where pr.student_request_id=v_step.student_request_id and pr.workflow_id=v_step.workflow_id
              and pr.workflow_step_id=pc.id
              and (pr.status='completed' or (pr.status='skipped' and pc.can_skip)))
        or not exists(
          with recursive reachable(step_id) as (
            select pc.id
            union
            select t.to_step_id from reachable r
            join public.request_type_workflow_transitions t
              on t.workflow_id=v_step.workflow_id and t.from_step_id=r.step_id
            join public.request_type_workflow_steps source_config
              on source_config.id=t.from_step_id and source_config.workflow_id=t.workflow_id
                and source_config.workflow_id=v_step.workflow_id
            join public.request_type_workflow_steps target_config
              on target_config.id=t.to_step_id and target_config.workflow_id=t.workflow_id
                and target_config.workflow_id=v_step.workflow_id
            where t.to_step_id is not null and
              (public.workflow_action_result_matches(source_config.action_type,t.action_result) or
               (t.action_result='skip' and source_config.can_skip))
          ) select 1 from reachable where step_id=v_step.workflow_step_id
        ))
  ) then return false; end if;

  return true;
end;
$function$;

revoke all on function public.workflow_runtime_predecessors_satisfied(uuid) from public,anon;
grant execute on function public.workflow_runtime_predecessors_satisfied(uuid) to authenticated,service_role;

-- Starts from the CURRENTLY APPLIED definition (see header). ONLY the B1
-- branch (v_is_b1 = true) is modified; the non-B1 lenient path below is the
-- applied contract preserved exactly (status active/pending,
-- comment-on-completed, reject/return flag checks, final RETURN true).
create or replace function public.can_current_user_act_on_step(p_step_id uuid, p_action text)
returns boolean
language plpgsql
stable security definer
set search_path to 'public'
as $function$
declare
  v_uid  uuid := auth.uid();
  v_step public.student_request_workflow_steps%rowtype;
  v_config public.request_type_workflow_steps%rowtype;
  v_request_type text;
  v_canonical_request_type text;
  v_is_b1 boolean := false;
  v_unit_code text;
  v_role_code text;
  v_transition_count integer;
begin
  if v_uid is null or p_step_id is null then
    return false;
  end if;

  if not public.is_valid_actor_request_action(p_action) then
    return false;
  end if;

  select s.* into v_step
  from public.student_request_workflow_steps s
  where s.id = p_step_id;

  if not found then
    return false;
  end if;

  select r.request_type into v_request_type
  from public.student_requests r
  where r.id = v_step.student_request_id;
  v_is_b1 := v_request_type in (
    'enrollment_suspension',
    'excused_absence', 'absence_excuse',
    'department_transfer', 'transfer',
    'final_chance', 'extra_chance',
    'file_withdrawal'
  );
  v_canonical_request_type := case v_request_type
    when 'absence_excuse' then 'excused_absence'
    when 'transfer' then 'department_transfer'
    when 'extra_chance' then 'final_chance'
    else v_request_type
  end;

  -- Every B1 staff step is active-only and directly assigned. A role-pool
  -- assignment, including admin/registrar/dean, can never substitute for the
  -- exact runtime assignee on these services.
  if v_is_b1 and (
    v_step.status is distinct from 'active'
    or num_nonnulls(
      v_step.assigned_user_id,
      v_step.assigned_staff_profile_id,
      v_step.assigned_faculty_profile_id,
      v_step.assigned_position_assignment_id
    ) is distinct from 1
  ) then
    return false;
  end if;

  if public.is_owner_of_request(v_uid, v_step.student_request_id) then
    return false;
  end if;

  if v_step.status not in ('active', 'pending') then
    if p_action = 'comment' and v_step.status = 'completed' then
      return public.user_matches_workflow_runtime_step(p_step_id);
    end if;
    return false;
  end if;

  -- Strict assignee match ALWAYS required (no admin/registrar/dean bypass).
  if not public.user_matches_workflow_runtime_step(p_step_id) then
    return false;
  end if;

  if v_is_b1 and not public.current_user_has_exact_processing_binding(
    v_step.processing_unit_id, v_step.processing_role_id
  ) then
    return false;
  end if;

  if v_canonical_request_type = 'department_transfer'
     and v_step.step_key in ('source_department_head_approval','target_department_head_approval')
     and not public.current_user_matches_transfer_department_scope(p_step_id, v_step.step_key) then
    return false;
  end if;

  select c.* into v_config
  from public.request_type_workflow_steps c
  where c.id = v_step.workflow_step_id;

  if v_is_b1 then
    -- B1-ONLY strict runtime/config correspondence: the applied config lookup
    -- above lacks workflow_id and never checks step_order; re-align it here
    -- for B1 steps only. The non-B1 path below keeps the applied lookup.
    select c.* into v_config
    from public.request_type_workflow_steps c
    where c.id = v_step.workflow_step_id
      and c.workflow_id = v_step.workflow_id;
    if not found
      or v_config.step_key is distinct from v_step.step_key
      or v_config.step_order is distinct from v_step.step_order
      or v_config.processing_unit_id is distinct from v_step.processing_unit_id
      or v_config.processing_role_id is distinct from v_step.processing_role_id then
      return false;
    end if;

    -- B1-ONLY predecessor guard: a successor step may never execute while any
    -- required predecessor runtime is missing, pending, or unreachable.
    if not public.workflow_runtime_predecessors_satisfied(p_step_id) then
      return false;
    end if;

    select u.code, pr.code into v_unit_code, v_role_code
    from public.request_processing_units u
    join public.request_processing_roles pr on pr.id = v_step.processing_role_id
    where u.id = v_step.processing_unit_id;
    if not public.is_valid_b1_runtime_step_contract(
      v_canonical_request_type, v_step.step_key, v_unit_code,
      v_role_code, v_config.action_type
    ) then
      return false;
    end if;

    -- B1-ONLY action gate (replaces the applied B1 action check, which it
    -- subsumes and strengthens): the executed action must equal the configured
    -- action_type with exactly one outgoing transition whose action_result
    -- matches workflow_action_result_matches, or be 'skip' on a skippable
    -- step with exactly one skip transition.
    if p_action = v_config.action_type then
      select count(*) into v_transition_count
      from public.request_type_workflow_transitions t
      where t.workflow_id = v_step.workflow_id
        and t.from_step_id = v_step.workflow_step_id
        and public.workflow_action_result_matches(v_config.action_type, t.action_result);
      return v_transition_count = 1;
    elsif p_action = 'skip' then
      select count(*) into v_transition_count
      from public.request_type_workflow_transitions t
      where t.workflow_id = v_step.workflow_id
        and t.from_step_id = v_step.workflow_step_id
        and t.action_result = 'skip';
      return coalesce(v_config.can_skip, false) and v_transition_count = 1;
    end if;
    return false;
  end if;

  -- Non-B1 path: applied lenient contract preserved EXACTLY.
  if p_action = 'skip' then
    if v_config.id is null or not coalesce(v_config.can_skip, false) then
      return false;
    end if;
    return true;
  end if;

  if p_action = 'reject' and v_config.id is not null and not coalesce(v_config.can_reject, true) then
    return false;
  end if;

  if p_action = 'return' and v_config.id is not null and not coalesce(v_config.can_return_to_student, true) then
    return false;
  end if;

  return true;
end;
$function$;

revoke all on function public.can_current_user_act_on_step(uuid,text) from public,anon;
grant execute on function public.can_current_user_act_on_step(uuid,text) to authenticated;
revoke all on function public.workflow_action_result_matches(text,text) from public,anon;
grant execute on function public.workflow_action_result_matches(text,text) to authenticated,service_role;

do $postcheck$
declare
  v_src text;
begin
  select p.prosrc into v_src from pg_proc p
  where p.oid='public.can_current_user_act_on_step(uuid,text)'::regprocedure;
  if position('workflow_runtime_predecessors_satisfied' in coalesce(v_src,''))=0
     or position('v_is_b1' in coalesce(v_src,''))=0
     or position('pending' in coalesce(v_src,''))=0 then
    raise exception 'B1_RUNTIME_PREDECESSOR_GUARD_REMEDIATION_02_POSTCHECK_FAILED';
  end if;
end;
$postcheck$;

commit;

-- Migration: 20260724022428_91130036-f132-4935-b492-260d403dfa8c.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260724022428', '20260724022428_91130036-f132-4935-b492-260d403dfa8c') ON CONFLICT (version) DO NOTHING;
-- LOG-AUDIT-CALL-DISAMBIGUATION-CLOSURE-01
BEGIN;

DO $$
DECLARE
  v_six regprocedure;
  v_seven regprocedure;
  v_overloads integer;
  v_seven_defaults integer;
  v_seven_secdef boolean;
  v_seven_rettype regtype;
  v_six_defaults integer;
  v_six_secdef boolean;
  v_col_matches integer;
  v_notnull_matches integer;
BEGIN
  v_six   := to_regprocedure('public.log_audit(text,uuid,text,jsonb,jsonb,text)');
  v_seven := to_regprocedure('public.log_audit(text,uuid,text,jsonb,jsonb,text,uuid)');

  IF v_seven IS NULL THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_SEVEN_ARG_MISSING';
  END IF;

  SELECT count(*) INTO v_overloads
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'log_audit';

  IF v_six IS NOT NULL AND v_overloads <> 2 THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_UNEXPECTED_OVERLOAD_COUNT_%', v_overloads;
  END IF;
  IF v_six IS NULL AND v_overloads <> 1 THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_UNEXPECTED_OVERLOAD_COUNT_%', v_overloads;
  END IF;

  SELECT p.pronargdefaults, p.prosecdef, p.prorettype
    INTO v_seven_defaults, v_seven_secdef, v_seven_rettype
  FROM pg_proc p WHERE p.oid = v_seven::oid;
  IF v_seven_defaults <> 4 OR v_seven_rettype <> 'void'::regtype OR NOT v_seven_secdef THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_SEVEN_ARG_SHAPE_UNEXPECTED defaults=% secdef=%', v_seven_defaults, v_seven_secdef;
  END IF;

  IF v_six IS NOT NULL THEN
    SELECT p.pronargdefaults, p.prosecdef INTO v_six_defaults, v_six_secdef
    FROM pg_proc p WHERE p.oid = v_six::oid;
    IF v_six_defaults <> 3 OR NOT v_six_secdef THEN
      RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_SIX_ARG_SHAPE_UNEXPECTED defaults=% secdef=%', v_six_defaults, v_six_secdef;
    END IF;
  END IF;

  SELECT count(*) INTO v_col_matches
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.table_name = 'audit_logs'
    AND (c.column_name, c.data_type) IN (
      ('id','uuid'),('created_at','timestamp with time zone'),('actor_user_id','uuid'),
      ('actor_role','text'),('entity_type','text'),('entity_id','uuid'),
      ('action_type','text'),('old_values','jsonb'),('new_values','jsonb'),
      ('notes','text'),('ip_address','text'),('user_agent','text'));
  SELECT count(*) INTO v_notnull_matches
  FROM information_schema.columns c
  WHERE c.table_schema='public' AND c.table_name='audit_logs' AND c.is_nullable='NO'
    AND c.column_name IN ('id','created_at','entity_type','action_type');
  IF v_col_matches <> 12 OR v_notnull_matches <> 4 THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_AUDIT_LOGS_SHAPE_MISMATCH cols=% nn=%', v_col_matches, v_notnull_matches;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_ROLE_MISSING';
  END IF;
END $$;

DROP FUNCTION IF EXISTS public.log_audit(text, uuid, text, jsonb, jsonb, text);

REVOKE EXECUTE ON FUNCTION public.log_audit(text, uuid, text, jsonb, jsonb, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.log_audit(text, uuid, text, jsonb, jsonb, text, uuid) TO service_role;

COMMENT ON FUNCTION public.log_audit(text, uuid, text, jsonb, jsonb, text, uuid) IS
  'LOGAUDIT_CLOSURE_01=1; canonical single overload; legacy 6-arg overload dropped; EXECUTE server-only (service_role + owner)';

DO $$
DECLARE
  v_overloads integer;
  v_acl aclitem[];
BEGIN
  SELECT count(*) INTO v_overloads
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname='public' AND p.proname='log_audit';
  IF v_overloads <> 1
     OR to_regprocedure('public.log_audit(text,uuid,text,jsonb,jsonb,text,uuid)') IS NULL THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_POST_OVERLOAD_STATE_%', v_overloads;
  END IF;

  SELECT p.proacl INTO v_acl FROM pg_proc p
  WHERE p.oid = to_regprocedure('public.log_audit(text,uuid,text,jsonb,jsonb,text,uuid)')::oid;

  IF v_acl IS NULL OR EXISTS (
    SELECT 1 FROM aclexplode(v_acl) a
    WHERE a.privilege_type='EXECUTE'
      AND (a.grantee=0 OR a.grantee IN (SELECT r.oid FROM pg_roles r WHERE r.rolname IN ('anon','authenticated')))
  ) THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_POST_ACL_CLIENT_EXECUTE';
  END IF;

  IF NOT has_function_privilege('service_role','public.log_audit(text,uuid,text,jsonb,jsonb,text,uuid)','EXECUTE') THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_POST_ACL_SERVICE_ROLE_MISSING';
  END IF;

  IF has_function_privilege('anon','public.log_audit(text,uuid,text,jsonb,jsonb,text,uuid)','EXECUTE')
     OR has_function_privilege('authenticated','public.log_audit(text,uuid,text,jsonb,jsonb,text,uuid)','EXECUTE') THEN
    RAISE EXCEPTION 'LOGAUDIT_CLOSURE_01_POST_ACL_CLIENT_PRIVILEGE';
  END IF;
END $$;

COMMIT;

-- Migration: 20260724053904_ecf769d1-a414-48b5-985a-d3b55a307402.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260724053904', '20260724053904_ecf769d1-a414-48b5-985a-d3b55a307402') ON CONFLICT (version) DO NOTHING;
-- DRAFT ONLY — NEVER APPLY WITHOUT SEPARATE EXPLICIT AUTHORIZATION.
-- Source-only forward correction. faculty_profiles is immutable in this phase.
BEGIN;

SELECT pg_advisory_xact_lock(hashtextextended(
  'DEPARTMENT-ADMINISTRATIVE-POSITIONS-SEPARATION-01', 0
));
LOCK TABLE public.organizational_positions IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.position_assignments IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.request_processing_assignments IN SHARE ROW EXCLUSIVE MODE;

DO $phase$
DECLARE
  v_unit uuid;
  v_role uuid;
  v_state text;
  v_item record;
  v_position uuid;
  v_pa uuid;
  v_count integer;
  v_updated integer;
BEGIN
  -- Fail closed on identity drift before the first write.
  IF NOT EXISTS (
    SELECT 1 FROM public.faculty_profiles
    WHERE id='d08a8509-4c04-472e-885f-053a80be12ec'
      AND employee_number='F2025006'
      AND user_id='97acbe02-c59c-409c-8d51-7d4ef72e6db7'
      AND status='active'
      AND department_id='ce485c67-5f7c-498d-b120-4b1130a86ae8'
  ) THEN RAISE EXCEPTION 'OSAMA_IDENTITY_OR_ACADEMIC_AFFILIATION_MISMATCH'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.faculty_profiles
    WHERE id='6f9f004d-c5f6-4dfe-b212-7f79ce8658e3'
      AND employee_number='F2025005'
      AND user_id='d4aaa5c9-72d1-4996-b0e8-d30c6327da6e'
      AND status='active'
  ) THEN RAISE EXCEPTION 'KHALED_IDENTITY_MISMATCH'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.faculty_profiles
    WHERE id='c1fe6084-e594-482e-a178-ac8eaffed376'
      AND employee_number='F2025004'
      AND user_id='f602b62c-194b-4591-8e9c-956e5cbb347d'
      AND status='active'
  ) THEN RAISE EXCEPTION 'RAMZI_IDENTITY_MISMATCH'; END IF;

  SELECT count(*),(array_agg(u.id ORDER BY u.id))[1] INTO v_count,v_unit
  FROM public.request_processing_units u WHERE u.code='department' AND u.is_active;
  IF v_count<>1 THEN RAISE EXCEPTION 'DEPARTMENT_UNIT_MUST_RESOLVE_ONCE:%',v_count; END IF;
  SELECT count(*),(array_agg(r.id ORDER BY r.id))[1] INTO v_count,v_role
  FROM public.request_processing_roles r
  WHERE r.unit_id=v_unit AND r.code='department_head' AND r.is_active;
  IF v_count<>1 THEN RAISE EXCEPTION 'DEPARTMENT_HEAD_ROLE_MUST_RESOLVE_ONCE:%',v_count; END IF;

  -- Classify before mutation. Only the exact legacy or exact final state is accepted.
  IF (
    SELECT count(*)=3 AND bool_and(assignment_type='faculty_profile'
      AND user_id IS NULL AND staff_profile_id IS NULL AND position_assignment_id IS NULL AND (
      (id='7ab0b14f-9007-40d6-9aaf-f1cba454ac8f'
        AND faculty_profile_id='d08a8509-4c04-472e-885f-053a80be12ec'
        AND department_id='ce485c67-5f7c-498d-b120-4b1130a86ae8')
      OR (id='912bdb96-3fb9-494c-8caa-7778c7d0d402'
        AND faculty_profile_id='6f9f004d-c5f6-4dfe-b212-7f79ce8658e3'
        AND department_id='ce485c67-5f7c-498d-b120-4b1130a86ae8')
      OR (id='4d0f434e-57ab-40b2-8a6f-5f27f330db97'
        AND faculty_profile_id='c1fe6084-e594-482e-a178-ac8eaffed376'
        AND department_id='22222222-2222-4222-8222-222222222222'))
    )
    FROM public.request_processing_assignments
    WHERE unit_id=v_unit AND role_id=v_role AND is_active
  ) THEN
    v_state:='KNOWN_LEGACY_PRESTATE';
  ELSIF (
    SELECT count(*)=3 AND count(DISTINCT department_id)=3 AND bool_and(
      assignment_type='position_assignment'
      AND position_assignment_id IS NOT NULL
      AND user_id IS NULL AND staff_profile_id IS NULL AND faculty_profile_id IS NULL
      AND department_id IN (
        '11111111-1111-4111-8111-111111111111',
        'ce485c67-5f7c-498d-b120-4b1130a86ae8',
        '22222222-2222-4222-8222-222222222222')
    )
    FROM public.request_processing_assignments
    WHERE unit_id=v_unit AND role_id=v_role AND is_active
  ) THEN
    v_state:='EXACT_FINAL_STATE';
  ELSE
    v_state:='UNEXPECTED_STATE';
  END IF;
  IF v_state='UNEXPECTED_STATE' THEN
    RAISE EXCEPTION 'UNEXPECTED_DEPARTMENT_HEAD_STATE';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.request_processing_assignments
    WHERE unit_id=v_unit AND role_id=v_role AND is_active
      AND department_id NOT IN (
        '11111111-1111-4111-8111-111111111111',
        'ce485c67-5f7c-498d-b120-4b1130a86ae8',
        '22222222-2222-4222-8222-222222222222')
  ) THEN RAISE EXCEPTION 'ACTIVE_CHAIR_OUTSIDE_APPROVED_DEPARTMENTS'; END IF;

  FOR v_item IN SELECT * FROM (VALUES
    ('cs_department_head','رئيس قسم علوم الحاسوب','97acbe02-c59c-409c-8d51-7d4ef72e6db7'::uuid,'11111111-1111-4111-8111-111111111111'::uuid),
    ('it_department_head','رئيس قسم تكنولوجيا المعلومات','d4aaa5c9-72d1-4996-b0e8-d30c6327da6e'::uuid,'ce485c67-5f7c-498d-b120-4b1130a86ae8'::uuid),
    ('is_department_head','رئيس قسم نظم المعلومات الحاسوبية','f602b62c-194b-4591-8e9c-956e5cbb347d'::uuid,'22222222-2222-4222-8222-222222222222'::uuid)
  ) x(position_code,name_ar,user_id,department_id)
  LOOP
    IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=v_item.user_id) THEN
      RAISE EXCEPTION 'EXPECTED_AUTH_USER_MISSING:%',v_item.user_id;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.organizational_positions
      WHERE code=v_item.position_code AND (
        name_ar IS DISTINCT FROM v_item.name_ar
        OR parent_code IS DISTINCT FROM 'academic_departments'
        OR unit_type IS DISTINCT FROM 'position'
        OR is_active IS DISTINCT FROM true)
    ) THEN RAISE EXCEPTION 'CONFLICTING_POSITION_DEFINITION:%',v_item.position_code; END IF;
    INSERT INTO public.organizational_positions(code,name_ar,parent_code,unit_type,is_active)
    SELECT v_item.position_code,v_item.name_ar,'academic_departments','position',true
    WHERE NOT EXISTS(SELECT 1 FROM public.organizational_positions WHERE code=v_item.position_code);
    SELECT id INTO STRICT v_position FROM public.organizational_positions
    WHERE code=v_item.position_code;

    IF EXISTS(SELECT 1 FROM public.position_assignments
      WHERE position_id=v_position AND is_active
        AND (assigned_to IS NOT NULL AND assigned_to<CURRENT_DATE)) THEN
      RAISE EXCEPTION 'EXPIRED_BUT_ACTIVE_POSITION_ASSIGNMENT:%',v_item.position_code;
    END IF;
    SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_count,v_pa
    FROM public.position_assignments
    WHERE position_id=v_position AND is_active
      AND assigned_from<=CURRENT_DATE AND (assigned_to IS NULL OR assigned_to>=CURRENT_DATE);
    IF v_count>1 THEN RAISE EXCEPTION 'MULTIPLE_CURRENT_POSITION_ASSIGNMENTS:%',v_item.position_code; END IF;
    IF v_count=1 AND NOT EXISTS(SELECT 1 FROM public.position_assignments
      WHERE id=v_pa AND user_id=v_item.user_id) THEN
      RAISE EXCEPTION 'UNEXPECTED_ACTIVE_POSITION_HOLDER:%',v_item.position_code;
    END IF;
    IF v_count=0 THEN
      INSERT INTO public.position_assignments(position_id,user_id,assigned_from,is_active,notes)
      VALUES(v_position,v_item.user_id,CURRENT_DATE,true,
        'DEPARTMENT-ADMINISTRATIVE-POSITIONS-SEPARATION-01')
      RETURNING id INTO v_pa;
    END IF;

    IF EXISTS(SELECT 1 FROM public.request_processing_assignments
      WHERE unit_id=v_unit AND role_id=v_role AND department_id=v_item.department_id
        AND is_active AND assignment_type='position_assignment'
        AND (position_assignment_id IS DISTINCT FROM v_pa
          OR user_id IS NOT NULL OR staff_profile_id IS NOT NULL OR faculty_profile_id IS NOT NULL))
    THEN RAISE EXCEPTION 'CONFLICTING_POSITION_PROCESSING_ASSIGNMENT:%',v_item.department_id; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.request_processing_assignments
      WHERE unit_id=v_unit AND role_id=v_role AND department_id=v_item.department_id
        AND assignment_type='position_assignment' AND position_assignment_id=v_pa
        AND user_id IS NULL AND staff_profile_id IS NULL AND faculty_profile_id IS NULL
        AND is_active AND (starts_at IS NULL OR starts_at<=now())
        AND (ends_at IS NULL OR ends_at>now())) THEN
      INSERT INTO public.request_processing_assignments(
        unit_id,role_id,assignment_type,position_assignment_id,department_id,is_active,starts_at)
      VALUES(v_unit,v_role,'position_assignment',v_pa,v_item.department_id,true,now());
    END IF;
  END LOOP;

  IF v_state='KNOWN_LEGACY_PRESTATE' THEN
    UPDATE public.request_processing_assignments
    SET is_active=false,ends_at=COALESCE(ends_at,now()),updated_at=now()
    WHERE id IN (
      '7ab0b14f-9007-40d6-9aaf-f1cba454ac8f',
      '912bdb96-3fb9-494c-8caa-7778c7d0d402',
      '4d0f434e-57ab-40b2-8a6f-5f27f330db97')
      AND unit_id=v_unit AND role_id=v_role
      AND assignment_type='faculty_profile' AND is_active;
    GET DIAGNOSTICS v_updated=ROW_COUNT;
    IF v_updated<>3 THEN RAISE EXCEPTION 'KNOWN_LEGACY_ROWS_DISABLED_COUNT:%',v_updated; END IF;
  END IF;
END
$phase$;

CREATE OR REPLACE FUNCTION public.current_user_matches_transfer_department_scope(
  p_step_id uuid,p_step_key text
) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT auth.uid() IS NOT NULL AND (
    SELECT count(*)=1
    FROM public.student_request_workflow_steps s
    JOIN public.transfer_request_details d ON d.request_id=s.student_request_id
    JOIN public.position_assignments pa ON pa.id=s.assigned_position_assignment_id
      AND pa.user_id=auth.uid() AND pa.is_active AND pa.assigned_from<=CURRENT_DATE
      AND (pa.assigned_to IS NULL OR pa.assigned_to>=CURRENT_DATE)
    JOIN public.request_processing_assignments rpa ON rpa.position_assignment_id=pa.id
      AND rpa.assignment_type='position_assignment' AND rpa.is_active
      AND (rpa.starts_at IS NULL OR rpa.starts_at<=now())
      AND (rpa.ends_at IS NULL OR rpa.ends_at>now())
      AND rpa.unit_id=s.processing_unit_id AND rpa.role_id=s.processing_role_id
    WHERE s.id=p_step_id AND s.step_key=p_step_key
      AND s.assigned_user_id IS NULL AND s.assigned_staff_profile_id IS NULL
      AND s.assigned_faculty_profile_id IS NULL
      AND ((p_step_key='source_department_head_approval'
        AND rpa.department_id=d.current_department_id)
        OR (p_step_key='target_department_head_approval'
        AND rpa.department_id=d.requested_department_id))
  )
$$;
REVOKE ALL ON FUNCTION public.current_user_matches_transfer_department_scope(uuid,text)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.current_user_matches_transfer_department_scope(uuid,text)
  TO authenticated,service_role;

DO $post$
DECLARE v_body text;
BEGIN
  SELECT pg_get_functiondef('public.current_user_matches_transfer_department_scope(uuid,text)'::regprocedure)
    INTO v_body;
  IF position('assigned_position_assignment_id' in v_body)=0
    OR position('faculty_profiles' in v_body)>0 THEN
    RAISE EXCEPTION 'TRANSFER_SCOPE_FUNCTION_CONTRACT_MISMATCH';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.faculty_profiles
    WHERE id='d08a8509-4c04-472e-885f-053a80be12ec'
      AND department_id='ce485c67-5f7c-498d-b120-4b1130a86ae8')
  THEN RAISE EXCEPTION 'OSAMA_ACADEMIC_AFFILIATION_CHANGED'; END IF;
  IF EXISTS(SELECT 1 FROM public.request_processing_assignments
    WHERE id IN ('7ab0b14f-9007-40d6-9aaf-f1cba454ac8f','912bdb96-3fb9-494c-8caa-7778c7d0d402',
      '4d0f434e-57ab-40b2-8a6f-5f27f330db97') AND is_active)
  THEN RAISE EXCEPTION 'LEGACY_ROWS_STILL_ACTIVE'; END IF;
  IF (SELECT count(*) FROM public.request_processing_assignments a
    JOIN public.request_processing_units u ON u.id=a.unit_id AND u.code='department'
    JOIN public.request_processing_roles r ON r.id=a.role_id AND r.code='department_head'
    WHERE a.is_active AND a.assignment_type='position_assignment'
      AND a.department_id IN ('11111111-1111-4111-8111-111111111111',
        'ce485c67-5f7c-498d-b120-4b1130a86ae8','22222222-2222-4222-8222-222222222222'))<>3
  THEN RAISE EXCEPTION 'FINAL_ACTIVE_PROCESSING_ASSIGNMENT_COUNT_MISMATCH'; END IF;
END
$post$;

COMMIT;

