-- Migration: 20260725110100_b1_08_trusted_reference_validators_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110100', '20260725110100_b1_08_trusted_reference_validators_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 8
-- Source draft: docs/migration-drafts/REQUEST-B1-TRUSTED-REFERENCE-VALIDATORS-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Shared trusted-reference validators. Installs no dispatcher and activates no service.

BEGIN;

CREATE OR REPLACE FUNCTION public.assert_b1_academic_period_reference(
  p_academic_year_id uuid,
  p_semester_id uuid
) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF p_academic_year_id IS NULL OR p_semester_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.semesters s JOIN public.academic_years y ON y.id=s.academic_year_id
    WHERE s.id=p_semester_id AND y.id=p_academic_year_id
      AND s.status='active' AND y.status='active'
  ) THEN RAISE EXCEPTION 'B1_TRUSTED_ACADEMIC_PERIOD_REQUIRED' USING ERRCODE='23503'; END IF;
END $$;

CREATE OR REPLACE FUNCTION public.assert_b1_active_course_enrollment(
  p_student_profile_id uuid,
  p_course_section_id uuid
) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF p_student_profile_id IS NULL OR p_course_section_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.student_enrollments e
    JOIN public.course_sections s ON s.id=e.course_section_id
    JOIN public.course_offerings o ON o.id=s.course_offering_id
    WHERE e.student_profile_id=p_student_profile_id
      AND e.course_section_id=p_course_section_id
      AND e.enrollment_status='enrolled' AND s.status='active' AND o.status='active'
  ) THEN RAISE EXCEPTION 'B1_ACTIVE_COURSE_ENROLLMENT_REQUIRED' USING ERRCODE='23503'; END IF;
END $$;

CREATE OR REPLACE FUNCTION public.assert_b1_target_program_department(
  p_program_id uuid,
  p_department_id uuid
) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF p_program_id IS NULL OR p_department_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.programs p JOIN public.departments d ON d.id=p.department_id
    WHERE p.id=p_program_id AND d.id=p_department_id
      AND p.is_active=true AND d.is_active=true
  ) THEN RAISE EXCEPTION 'B1_TARGET_PROGRAM_DEPARTMENT_REQUIRED' USING ERRCODE='23503'; END IF;
END $$;

REVOKE ALL ON FUNCTION public.assert_b1_academic_period_reference(uuid,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.assert_b1_active_course_enrollment(uuid,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.assert_b1_target_program_department(uuid,uuid) FROM PUBLIC,anon,authenticated;

COMMIT;


-- Migration: 20260725110200_b1_09_excused_absence_vocabulary_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110200', '20260725110200_b1_09_excused_absence_vocabulary_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 9
-- Source draft: docs/migration-drafts/REQUEST-B1-EXCUSED-ABSENCE-VOCABULARY-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Extends new excused-absence writes to the approved canonical vocabulary while
-- preserving historical values. No row rewrite, mapping, backfill, or activation.

BEGIN;

DO $preflight$
DECLARE
  v_definition text;
  v_normalized text;
  v_validated boolean;
BEGIN
  -- Use the raw catalog definition so CHECK((...)) parentheses match production
  -- signatures; pretty=true strips the outer grouping parentheses.
  SELECT pg_get_constraintdef(c.oid, false), c.convalidated
  INTO v_definition, v_validated
  FROM pg_constraint c
  WHERE c.conrelid = 'public.absence_excuse_details'::regclass
    AND c.conname = 'aed_reason_chk'
    AND c.contype = 'c';

  IF v_definition IS NULL THEN
    RAISE EXCEPTION 'AED_REASON_CONSTRAINT_MISSING';
  END IF;

  v_normalized := regexp_replace(v_definition, '\s+', '', 'g');

  IF v_normalized IN (
    'CHECK((reason_type=ANY(ARRAY[''medical''::text,''family''::text,''emergency''::text,''other''::text])))',
    'CHECK((reason_type=ANY(ARRAY[''medical''::text,''family''::text,''emergency''::text,''other''::text])))NOTVALID'
  ) THEN
    ALTER TABLE public.absence_excuse_details DROP CONSTRAINT aed_reason_chk;
    ALTER TABLE public.absence_excuse_details ADD CONSTRAINT aed_reason_chk CHECK (
      reason_type IN ('medical','family_emergency','official','other','family','emergency')
    ) NOT VALID;
    ALTER TABLE public.absence_excuse_details VALIDATE CONSTRAINT aed_reason_chk;
  ELSIF v_normalized NOT IN (
    'CHECK((reason_type=ANY(ARRAY[''medical''::text,''family_emergency''::text,''official''::text,''other''::text,''family''::text,''emergency''::text])))',
    'CHECK((reason_type=ANY(ARRAY[''medical''::text,''family_emergency''::text,''official''::text,''other''::text,''family''::text,''emergency''::text])))NOTVALID'
  ) THEN
    RAISE EXCEPTION 'AED_REASON_CONSTRAINT_UNEXPECTED:%', v_definition;
  ELSIF NOT v_validated THEN
    ALTER TABLE public.absence_excuse_details VALIDATE CONSTRAINT aed_reason_chk;
  END IF;
END
$preflight$;

CREATE OR REPLACE FUNCTION public.enforce_canonical_absence_reason_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (TG_OP = 'INSERT' OR NEW.reason_type IS DISTINCT FROM OLD.reason_type)
     AND NEW.reason_type NOT IN ('medical','family_emergency','official','other') THEN
    RAISE EXCEPTION 'CANONICAL_ABSENCE_REASON_REQUIRED' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END
$$;

REVOKE ALL ON FUNCTION public.enforce_canonical_absence_reason_write()
  FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_enforce_canonical_absence_reason_write ON public.absence_excuse_details;
DO $trigger$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid='public.absence_excuse_details'::regclass
      AND tgname='trg_enforce_canonical_absence_reason_write'
      AND NOT tgisinternal
  ) THEN
    CREATE TRIGGER trg_enforce_canonical_absence_reason_write
      BEFORE INSERT OR UPDATE OF reason_type ON public.absence_excuse_details
      FOR EACH ROW EXECUTE FUNCTION public.enforce_canonical_absence_reason_write();
  ELSIF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid='public.absence_excuse_details'::regclass
      AND tgname='trg_enforce_canonical_absence_reason_write'
      AND tgfoid='public.enforce_canonical_absence_reason_write()'::regprocedure
      AND tgtype=23 AND tgenabled='O' AND tgconstraint=0 AND tgnargs=0
      AND tgqual IS NULL
      AND tgattr::smallint[] = ARRAY[(
        SELECT a.attnum::smallint FROM pg_attribute a
        WHERE a.attrelid='public.absence_excuse_details'::regclass
          AND a.attname='reason_type' AND NOT a.attisdropped
      )]::smallint[]
  ) THEN
    RAISE EXCEPTION 'CANONICAL_ABSENCE_REASON_TRIGGER_MISMATCH';
  END IF;
END
$trigger$;

COMMENT ON CONSTRAINT aed_reason_chk ON public.absence_excuse_details IS
  'New writes use medical/family_emergency/official/other. Historical family/emergency values remain readable; no backfill.';

COMMIT;


-- Migration: 20260725110300_b1_10_excused_absence_detail_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110300', '20260725110300_b1_10_excused_absence_detail_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 10
-- Source draft: docs/migration-drafts/REQUEST-B1-EXCUSED-ABSENCE-DETAIL-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Adds the canonical reason detail without rewriting historical rows.

BEGIN;

ALTER TABLE public.absence_excuse_details
  ADD COLUMN IF NOT EXISTS absence_reason_detail text;

DO $column$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_attribute a
    WHERE a.attrelid='public.absence_excuse_details'::regclass
      AND a.attname='absence_reason_detail' AND NOT a.attisdropped
      AND a.atttypid='text'::regtype AND a.atttypmod=-1 AND NOT a.attnotnull
      AND NOT EXISTS (SELECT 1 FROM pg_attrdef d WHERE d.adrelid=a.attrelid AND d.adnum=a.attnum)
  ) THEN RAISE EXCEPTION 'ABSENCE_REASON_DETAIL_COLUMN_MISMATCH'; END IF;
END
$column$;

CREATE OR REPLACE FUNCTION public.enforce_new_absence_reason_detail()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF (TG_OP='INSERT'
      OR NEW.absence_reason_detail IS DISTINCT FROM OLD.absence_reason_detail
      OR NEW.reason_type IS DISTINCT FROM OLD.reason_type
      OR NEW.course_section_id IS DISTINCT FROM OLD.course_section_id
      OR NEW.absence_date IS DISTINCT FROM OLD.absence_date)
     AND (NEW.absence_reason_detail IS NULL OR length(btrim(NEW.absence_reason_detail)) < 3) THEN
    RAISE EXCEPTION 'ABSENCE_REASON_DETAIL_REQUIRED' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION public.enforce_new_absence_reason_detail() FROM PUBLIC,anon,authenticated;

DO $trigger$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.absence_excuse_details'::regclass
      AND tgname='trg_enforce_new_absence_reason_detail' AND NOT tgisinternal) THEN
    CREATE TRIGGER trg_enforce_new_absence_reason_detail
      BEFORE INSERT OR UPDATE OF absence_reason_detail,reason_type,course_section_id,absence_date
      ON public.absence_excuse_details
      FOR EACH ROW EXECUTE FUNCTION public.enforce_new_absence_reason_detail();
  ELSIF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.absence_excuse_details'::regclass
      AND tgname='trg_enforce_new_absence_reason_detail'
      AND tgfoid='public.enforce_new_absence_reason_detail()'::regprocedure
      AND tgtype=23 AND tgenabled='O' AND tgconstraint=0 AND tgnargs=0 AND tgqual IS NULL
      AND cardinality(tgattr::smallint[])=4
      AND NOT EXISTS (SELECT 1 FROM unnest(ARRAY['absence_reason_detail','reason_type','course_section_id','absence_date']) n
        WHERE (SELECT attnum::smallint FROM pg_attribute WHERE attrelid='public.absence_excuse_details'::regclass
          AND attname=n AND NOT attisdropped)<>ALL(tgattr::smallint[]))
  ) THEN RAISE EXCEPTION 'ABSENCE_REASON_DETAIL_TRIGGER_MISMATCH'; END IF;
END
$trigger$;

ALTER TABLE public.absence_excuse_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.absence_excuse_details NO FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.absence_excuse_details FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON TABLE public.absence_excuse_details TO authenticated,service_role;

-- Fail-safe for Lovable/Supabase platform role. Never allowlisted in final ACL.
-- Role may be absent on local PG; migration must not fail in that case.
DO $revoke_sandbox_exec$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'sandbox_exec') THEN
    REVOKE ALL ON TABLE public.absence_excuse_details FROM sandbox_exec;
  END IF;
END
$revoke_sandbox_exec$;

DO $drop_legacy_policies$
DECLARE
  v_table constant text := 'absence_excuse_details';
  v_policy text;
BEGIN
  -- Allowlisted table + policy names only. No client-supplied identifiers.
  IF to_regclass('public.' || v_table) IS NULL THEN
    RAISE EXCEPTION 'ABSENCE_EXCUSE_DETAIL_MISSING';
  END IF;
  FOREACH v_policy IN ARRAY ARRAY[
    'aed_select',
    'aed_insert',
    'aed_update',
    'aed_delete',
    'absence_excuse_details_owner_select'
  ]
  LOOP
    IF EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'public'
        AND tablename = v_table
        AND policyname = v_policy
    ) THEN
      EXECUTE format('%s POLICY IF EXISTS %I ON public.%I', 'DROP', v_policy, v_table);
    END IF;
  END LOOP;
END
$drop_legacy_policies$;

CREATE POLICY absence_excuse_details_owner_select ON public.absence_excuse_details
  FOR SELECT TO authenticated USING (public.is_owner_of_request(auth.uid(),request_id));

DO $security$
BEGIN
  IF (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND tablename='absence_excuse_details')<>1
    OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='absence_excuse_details'
      AND policyname='absence_excuse_details_owner_select' AND cmd='SELECT' AND permissive='PERMISSIVE'
      AND roles=ARRAY['authenticated'::name] AND qual='is_owner_of_request(auth.uid(), request_id)' AND with_check IS NULL)
  THEN RAISE EXCEPTION 'ABSENCE_EXCUSE_POLICY_INVENTORY_MISMATCH'; END IF;
  IF EXISTS (SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) x
    LEFT JOIN pg_roles r ON r.oid=x.grantee WHERE c.oid='public.absence_excuse_details'::regclass
      AND NOT (x.grantee=c.relowner OR (r.rolname IN ('authenticated','service_role') AND x.privilege_type='SELECT' AND NOT x.is_grantable)))
  THEN RAISE EXCEPTION 'ABSENCE_EXCUSE_ACL_INVENTORY_MISMATCH'; END IF;
END
$security$;

COMMENT ON COLUMN public.absence_excuse_details.absence_reason_detail IS
  'Required for new/changed excused-absence writes; historical null rows are preserved without backfill.';

COMMIT;


-- Migration: 20260725110400_b1_11_file_withdrawal_details_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110400', '20260725110400_b1_11_file_withdrawal_details_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 11
-- Source draft: docs/migration-drafts/REQUEST-B1-FILE-WITHDRAWAL-DETAILS-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- RPC-only detail persistence foundation for file_withdrawal. No activation.

BEGIN;

CREATE TABLE IF NOT EXISTS public.file_withdrawal_details (
  request_id uuid CONSTRAINT file_withdrawal_details_pkey PRIMARY KEY,
  withdrawal_reason text NOT NULL,
  impact_ack boolean NOT NULL,
  library_cleared_at timestamptz,
  labs_cleared_at timestamptz,
  activities_cleared_at timestamptz,
  finance_cleared_at timestamptz,
  records_transferred_at timestamptz,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT file_withdrawal_details_request_fkey FOREIGN KEY (request_id)
    REFERENCES public.student_requests(id) MATCH SIMPLE ON UPDATE NO ACTION ON DELETE RESTRICT NOT DEFERRABLE,
  CONSTRAINT file_withdrawal_details_reason_check CHECK (length(btrim(withdrawal_reason)) >= 10),
  CONSTRAINT file_withdrawal_details_impact_check CHECK (impact_ack)
);

DO $catalog$
DECLARE
  v_signature text[];
BEGIN
  SELECT array_agg(a.attname || ':' || pg_catalog.format_type(a.atttypid,a.atttypmod)
                   || ':' || a.attnotnull::text ORDER BY a.attnum)
  INTO v_signature
  FROM pg_attribute a
  WHERE a.attrelid='public.file_withdrawal_details'::regclass
    AND a.attnum>0 AND NOT a.attisdropped;

  IF v_signature IS DISTINCT FROM ARRAY[
    'request_id:uuid:true','withdrawal_reason:text:true','impact_ack:boolean:true',
    'library_cleared_at:timestamp with time zone:false','labs_cleared_at:timestamp with time zone:false',
    'activities_cleared_at:timestamp with time zone:false','finance_cleared_at:timestamp with time zone:false',
    'records_transferred_at:timestamp with time zone:false','notes:text:false',
    'created_at:timestamp with time zone:true','updated_at:timestamp with time zone:true'
  ]::text[] THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_DETAILS_SCHEMA_MISMATCH:%', v_signature;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint c
    WHERE c.conrelid='public.file_withdrawal_details'::regclass
      AND c.conname='file_withdrawal_details_pkey' AND c.contype='p'
      AND c.conkey=ARRAY[(SELECT attnum::smallint FROM pg_attribute WHERE attrelid=c.conrelid AND attname='request_id')]
      AND NOT c.condeferrable AND NOT c.condeferred AND c.convalidated) THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_PRIMARY_KEY_MISMATCH';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint c
    WHERE c.conrelid='public.file_withdrawal_details'::regclass
      AND c.conname='file_withdrawal_details_request_fkey' AND c.contype='f'
      AND c.confrelid='public.student_requests'::regclass
      AND c.conkey=ARRAY[(SELECT attnum::smallint FROM pg_attribute WHERE attrelid=c.conrelid AND attname='request_id')]
      AND c.confkey=ARRAY[(SELECT attnum::smallint FROM pg_attribute WHERE attrelid=c.confrelid AND attname='id')]
      AND c.confmatchtype='s' AND c.confupdtype='a' AND c.confdeltype='r'
      AND NOT c.condeferrable AND NOT c.condeferred AND c.convalidated) THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_REQUEST_FK_MISMATCH';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid='public.file_withdrawal_details'::regclass
      AND c.conname='file_withdrawal_details_reason_check' AND c.contype='c' AND c.convalidated
      AND regexp_replace(pg_get_constraintdef(c.oid,false),'\s+','','g')='CHECK((length(btrim(withdrawal_reason))>=10))')
    OR NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid='public.file_withdrawal_details'::regclass
      AND c.conname='file_withdrawal_details_impact_check' AND c.contype='c' AND c.convalidated
      AND regexp_replace(pg_get_constraintdef(c.oid,false),'\s+','','g') IN ('CHECK(impact_ack)','CHECK((impact_ack))')) THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_CHECK_CONSTRAINT_MISMATCH';
  END IF;

  IF (SELECT count(*) FROM pg_constraint c WHERE c.conrelid='public.file_withdrawal_details'::regclass) <> 4 THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_CONSTRAINT_INVENTORY_MISMATCH';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum
      WHERE d.adrelid='public.file_withdrawal_details'::regclass AND a.attname='created_at'
        AND pg_get_expr(d.adbin,d.adrelid)='now()')
    OR NOT EXISTS (SELECT 1 FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum
      WHERE d.adrelid='public.file_withdrawal_details'::regclass AND a.attname='updated_at'
        AND pg_get_expr(d.adbin,d.adrelid)='now()') THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_DEFAULT_MISMATCH';
  END IF;
  IF (SELECT count(*) FROM pg_attrdef d WHERE d.adrelid='public.file_withdrawal_details'::regclass) <> 2 THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_DEFAULT_INVENTORY_MISMATCH';
  END IF;
END
$catalog$;

ALTER TABLE public.file_withdrawal_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.file_withdrawal_details NO FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.file_withdrawal_details FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.file_withdrawal_details FROM service_role;
GRANT SELECT ON TABLE public.file_withdrawal_details TO authenticated;
GRANT SELECT ON TABLE public.file_withdrawal_details TO service_role;

-- Fail-safe for Lovable/Supabase platform default ACL (sandbox_exec=ar).
-- Role may be absent on local PG; migration must not fail in that case.
-- Never allowlisted in final ACL inventory.
DO $revoke_sandbox_exec$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'sandbox_exec') THEN
    REVOKE ALL ON TABLE public.file_withdrawal_details FROM sandbox_exec;
  END IF;
END
$revoke_sandbox_exec$;

DO $acl$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_class c
    CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) x
    LEFT JOIN pg_roles r ON r.oid=x.grantee
    WHERE c.oid='public.file_withdrawal_details'::regclass
      AND NOT (
        x.grantee=c.relowner
        OR (r.rolname IN ('authenticated','service_role') AND x.privilege_type='SELECT' AND NOT x.is_grantable)
      )
  ) THEN RAISE EXCEPTION 'FILE_WITHDRAWAL_ACL_INVENTORY_MISMATCH'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.oid='public.file_withdrawal_details'::regclass
      AND c.relrowsecurity AND NOT c.relforcerowsecurity) THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_RLS_MODE_MISMATCH';
  END IF;
END
$acl$;

DO $policy$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='public' AND tablename='file_withdrawal_details'
      AND policyname='file_withdrawal_details_owner_select'
  ) THEN
    CREATE POLICY file_withdrawal_details_owner_select
      ON public.file_withdrawal_details FOR SELECT TO authenticated
      USING (public.is_owner_of_request(auth.uid(), request_id));
  ELSIF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='public' AND tablename='file_withdrawal_details'
      AND policyname='file_withdrawal_details_owner_select'
      AND cmd='SELECT' AND permissive='PERMISSIVE'
      AND roles=ARRAY['authenticated'::name]
      AND qual='is_owner_of_request(auth.uid(), request_id)' AND with_check IS NULL
  ) THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_OWNER_POLICY_MISMATCH';
  END IF;
  IF (SELECT count(*) FROM pg_policies
      WHERE schemaname='public' AND tablename='file_withdrawal_details') <> 1 THEN
    RAISE EXCEPTION 'FILE_WITHDRAWAL_POLICY_INVENTORY_MISMATCH';
  END IF;
END
$policy$;

COMMENT ON TABLE public.file_withdrawal_details IS
  'B1 file-withdrawal details. Writes are restricted to reviewed SECURITY DEFINER RPCs.';

COMMIT;


-- Migration: 20260725110500_b1_12_transfer_secure_attachment_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110500', '20260725110500_b1_12_transfer_secure_attachment_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 12
-- Source draft: docs/migration-drafts/REQUEST-B1-TRANSFER-SECURE-ATTACHMENT-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Extends the reviewed private attachment runtime to transfer certificates.
-- Must run after STUDENT-REQUEST-SECURE-ATTACHMENTS-SOURCE-01.sql and atomic 04.

BEGIN;

DO $field_constraint$
DECLARE v_def text; v_norm text; v_validated boolean;
BEGIN
  SELECT pg_get_constraintdef(c.oid,false),c.convalidated INTO v_def,v_validated
  FROM pg_constraint c WHERE c.conrelid='public.student_request_attachment_uploads'::regclass
    AND c.conname='student_request_attachment_uploads_field_key_check' AND c.contype='c';
  IF v_def IS NULL THEN RAISE EXCEPTION 'ATTACHMENT_FIELD_CONSTRAINT_MISSING'; END IF;
  v_norm:=regexp_replace(v_def,'\s+','','g');
  IF v_norm IN (
    'CHECK((field_key=''excuse_documents''::text))',
    'CHECK(field_key=''excuse_documents''::text)'
  ) THEN
    ALTER TABLE public.student_request_attachment_uploads
      DROP CONSTRAINT student_request_attachment_uploads_field_key_check;
    ALTER TABLE public.student_request_attachment_uploads
      ADD CONSTRAINT student_request_attachment_uploads_field_key_check
      CHECK (field_key IN ('excuse_documents','secondary_certificate')) NOT VALID;
    ALTER TABLE public.student_request_attachment_uploads
      VALIDATE CONSTRAINT student_request_attachment_uploads_field_key_check;
  ELSIF v_norm NOT IN (
    'CHECK((field_key=ANY(ARRAY[''excuse_documents''::text,''secondary_certificate''::text])))',
    'CHECK((field_key=ANY(ARRAY[''excuse_documents''::text,''secondary_certificate''::text])))NOTVALID',
    'CHECK(field_key=ANY(ARRAY[''excuse_documents''::text,''secondary_certificate''::text]))',
    'CHECK(field_key=ANY(ARRAY[''excuse_documents''::text,''secondary_certificate''::text]))NOTVALID'
  ) THEN RAISE EXCEPTION 'ATTACHMENT_FIELD_CONSTRAINT_UNEXPECTED:%',v_def;
  ELSIF NOT v_validated THEN
    ALTER TABLE public.student_request_attachment_uploads
      VALIDATE CONSTRAINT student_request_attachment_uploads_field_key_check;
  END IF;
  IF (SELECT count(*) FROM pg_constraint c WHERE c.conrelid='public.student_request_attachment_uploads'::regclass
      AND c.contype='c' AND pg_get_constraintdef(c.oid,true) ILIKE '%field_key%')<>1
    THEN RAISE EXCEPTION 'ATTACHMENT_FIELD_CONSTRAINT_INVENTORY_MISMATCH'; END IF;
END
$field_constraint$;

CREATE OR REPLACE FUNCTION public.b1_expected_secure_attachment_field(p_request_type text)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$
  SELECT CASE p_request_type
    WHEN 'excused_absence' THEN 'excuse_documents'
    WHEN 'absence_excuse' THEN 'excuse_documents'
    WHEN 'department_transfer' THEN 'secondary_certificate'
    WHEN 'transfer' THEN 'secondary_certificate'
    ELSE NULL END
$$;
REVOKE ALL ON FUNCTION public.b1_expected_secure_attachment_field(text) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.create_student_request_attachment_upload_intent(
  p_student_request_id uuid,p_field_key text,p_original_file_name text,p_mime_type text,
  p_size_bytes bigint,p_checksum_sha256 text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage,pg_temp AS $$
DECLARE
  v_uid uuid:=auth.uid(); v_profile_id uuid; v_req public.student_requests%ROWTYPE;
  v_id uuid:=gen_random_uuid(); v_path text; v_count integer; v_expected_field text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'ATTACHMENT_ACCESS_DENIED' USING ERRCODE='28000'; END IF;
  SELECT sp.id INTO v_profile_id FROM public.student_profiles sp WHERE sp.user_id=v_uid AND sp.status='active';
  SELECT * INTO v_req FROM public.student_requests r
    WHERE r.id=p_student_request_id AND r.student_profile_id=v_profile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTACHMENT_REQUEST_NOT_OWNED' USING ERRCODE='42501'; END IF;
  IF v_req.status NOT IN ('draft','returned','returned_for_completion')
    THEN RAISE EXCEPTION 'ATTACHMENT_REQUEST_NOT_EDITABLE' USING ERRCODE='42501'; END IF;
  v_expected_field:=public.b1_expected_secure_attachment_field(v_req.request_type);
  IF v_expected_field IS NULL OR p_field_key IS DISTINCT FROM v_expected_field
    THEN RAISE EXCEPTION 'ATTACHMENT_FIELD_NOT_ALLOWED' USING ERRCODE='42501'; END IF;
  IF p_mime_type NOT IN ('application/pdf','image/jpeg','image/png')
    THEN RAISE EXCEPTION 'ATTACHMENT_MIME_NOT_ALLOWED'; END IF;
  IF p_size_bytes<=0 OR p_size_bytes>5242880 THEN RAISE EXCEPTION 'ATTACHMENT_SIZE_EXCEEDED'; END IF;
  IF p_original_file_name IS NULL OR length(btrim(p_original_file_name)) NOT BETWEEN 1 AND 255
    OR p_original_file_name ~ '[\\/]' OR p_original_file_name LIKE '%..%'
    THEN RAISE EXCEPTION 'ATTACHMENT_OBJECT_MISMATCH'; END IF;
  SELECT count(*) INTO v_count FROM public.student_request_attachment_uploads a
    WHERE a.student_request_id=v_req.id AND a.field_key=p_field_key AND a.upload_status<>'rejected';
  IF v_count>=3 THEN RAISE EXCEPTION 'ATTACHMENT_COUNT_EXCEEDED'; END IF;
  v_path:=format('student-requests/%s/%s/%s/content.%s',v_profile_id,v_req.id,v_id,
    CASE p_mime_type WHEN 'application/pdf' THEN 'pdf' WHEN 'image/png' THEN 'png' ELSE 'jpg' END);
  INSERT INTO public.student_request_attachment_uploads(
    id,student_request_id,student_profile_id,field_key,original_file_name,mime_type,size_bytes,
    storage_bucket,storage_object_path,checksum_sha256,created_by)
  VALUES(v_id,v_req.id,v_profile_id,p_field_key,p_original_file_name,p_mime_type,p_size_bytes,
    'student-request-secure-attachments',v_path,p_checksum_sha256,v_uid);
  PERFORM public.log_audit(
    'student_request_attachment'::text,
    v_id::uuid,
    'attachment_upload_intent_created'::text,
    NULL::jsonb,
    jsonb_build_object('request_id',v_req.id,'field_key',p_field_key)::jsonb,
    NULL::text,
    v_uid::uuid
  );
  RETURN jsonb_build_object('attachment_id',v_id);
END $$;

CREATE OR REPLACE FUNCTION public.assert_required_student_request_attachments(
  p_student_request_id uuid,p_attachment_ids uuid[]
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE
  v_uid uuid:=auth.uid(); v_profile_id uuid; v_request public.student_requests%ROWTYPE;
  v_expected integer; v_attached integer; v_expected_field text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'ATTACHMENT_ACCESS_DENIED' USING ERRCODE='28000'; END IF;
  SELECT sp.id INTO v_profile_id FROM public.student_profiles sp WHERE sp.user_id=v_uid AND sp.status='active';
  SELECT r.* INTO v_request FROM public.student_requests r WHERE r.id=p_student_request_id
    AND r.student_profile_id=v_profile_id AND r.status IN ('draft','returned','returned_for_completion') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTACHMENT_REQUEST_NOT_OWNED' USING ERRCODE='42501'; END IF;
  v_expected_field:=public.b1_expected_secure_attachment_field(v_request.request_type);
  IF v_expected_field IS NULL THEN RAISE EXCEPTION 'ATTACHMENT_FIELD_NOT_ALLOWED' USING ERRCODE='42501'; END IF;
  v_expected:=COALESCE(cardinality(p_attachment_ids),0);
  IF v_expected NOT BETWEEN 1 AND 3 OR v_expected<>(SELECT count(DISTINCT x) FROM unnest(p_attachment_ids) x)
    THEN RAISE EXCEPTION 'ATTACHMENT_UPLOAD_NOT_COMPLETED'; END IF;
  PERFORM 1 FROM public.student_request_attachment_uploads a WHERE a.id=ANY(p_attachment_ids)
    AND a.student_request_id=p_student_request_id AND a.student_profile_id=v_profile_id FOR UPDATE;
  SELECT count(*) INTO v_attached FROM public.student_request_attachment_uploads a
    WHERE a.id=ANY(p_attachment_ids) AND a.student_request_id=p_student_request_id
      AND a.student_profile_id=v_profile_id AND a.field_key=v_expected_field
      AND a.upload_status='attached' AND a.mime_type IN ('application/pdf','image/jpeg','image/png')
      AND a.size_bytes BETWEEN 1 AND 5242880;
  IF v_attached<>v_expected THEN RAISE EXCEPTION 'ATTACHMENT_OBJECT_MISMATCH' USING ERRCODE='42501'; END IF;
END $$;

REVOKE ALL ON FUNCTION public.create_student_request_attachment_upload_intent(uuid,text,text,text,bigint,text)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_student_request_attachment_upload_intent(uuid,text,text,text,bigint,text)
  TO authenticated;
REVOKE ALL ON FUNCTION public.assert_required_student_request_attachments(uuid,uuid[])
  FROM PUBLIC,anon,authenticated;

-- Old wrapper cannot satisfy atomic 04's form/version arguments and must not bypass it.
REVOKE ALL ON FUNCTION public.submit_student_request_with_secure_attachments(uuid,uuid[])
  FROM PUBLIC,anon,authenticated;

COMMIT;


-- Migration: 20260725110600_b1_13_final_chance_canonical_write_03.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110600', '20260725110600_b1_13_final_chance_canonical_write_03') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 13
-- Source draft: docs/migration-drafts/FINAL-CHANCE-CANONICAL-WRITE-03.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Migration 3/3 for EXTERNAL_UNIVERSITY_PAYMENT_CONFIRMATION.
-- Stored request_types may be either canonical final_chance or legacy
-- extra_chance, but must resolve to exactly one row across both codes.
-- This migration constrains new academic chance values only; it performs
-- no historical rewrite or backfill and does not mutate request_types.

BEGIN;

DO $preflight$
DECLARE
  v_extra_chance_type_count integer;
  v_final_chance_type_count integer;
  v_legacy_only boolean;
  v_canonical_only boolean;
BEGIN
  IF to_regclass('public.extra_chance_details') IS NULL
     OR to_regclass('public.student_extra_chances') IS NULL THEN
    RAISE EXCEPTION 'FINAL_CHANCE_REQUIRED_TABLES_MISSING';
  END IF;

  SELECT count(*) INTO v_extra_chance_type_count
  FROM public.request_types rt
  WHERE rt.code = 'extra_chance';

  SELECT count(*) INTO v_final_chance_type_count
  FROM public.request_types rt
  WHERE rt.code = 'final_chance';

  -- Exactly one stored request type across both codes:
  -- A) legacy-only: extra_chance=1 AND final_chance=0
  -- B) canonical-only: extra_chance=0 AND final_chance=1
  -- Fail-closed for both/neither/duplicates/any other count.
  v_legacy_only := (v_extra_chance_type_count = 1 AND v_final_chance_type_count = 0);
  v_canonical_only := (v_extra_chance_type_count = 0 AND v_final_chance_type_count = 1);

  IF NOT (v_legacy_only OR v_canonical_only) THEN
    RAISE EXCEPTION 'FINAL_CHANCE_STORED_ALIAS_CONTRACT_MISMATCH:extra=%:canonical=%',
      v_extra_chance_type_count, v_final_chance_type_count;
  END IF;
END;
$preflight$;

CREATE OR REPLACE FUNCTION public.assert_final_chance_type_for_new_write(
  p_chance_type text
)
RETURNS void
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public
AS $$
BEGIN
  IF p_chance_type IS DISTINCT FROM 'final_chance' THEN
    RAISE EXCEPTION 'FINAL_CHANCE_TYPE_REQUIRED_FOR_NEW_WRITE'
      USING ERRCODE = '22023';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.assert_final_chance_type_for_new_write(text)
  FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION public.assert_final_chance_type_for_new_write(text) IS
  'Fail-closed validator for new final-exam-chance writes. Historical aliases are read-only.';

CREATE OR REPLACE FUNCTION public.enforce_final_chance_detail_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.assert_final_chance_type_for_new_write(NEW.chance_type);
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.enforce_final_chance_detail_write()
  FROM PUBLIC, anon, authenticated;

DO $triggers$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'public.extra_chance_details'::regclass
      AND tgname = 'trg_enforce_final_chance_detail_write'
      AND NOT tgisinternal
  ) THEN
    CREATE TRIGGER trg_enforce_final_chance_detail_write
      BEFORE INSERT OR UPDATE OF chance_type ON public.extra_chance_details
      FOR EACH ROW EXECUTE FUNCTION public.enforce_final_chance_detail_write();
  ELSIF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'public.extra_chance_details'::regclass
      AND tgname = 'trg_enforce_final_chance_detail_write'
      AND tgfoid = 'public.enforce_final_chance_detail_write()'::regprocedure
      AND tgenabled = 'O'
      AND tgtype = 23 -- ROW + BEFORE + INSERT + UPDATE
      AND tgconstraint = 0
      AND tgnargs = 0
      AND (
        SELECT count(*) = 1 AND bool_and(a.attname = 'chance_type')
        FROM unnest(tgattr::smallint[]) AS cols(attnum)
        JOIN pg_attribute a
          ON a.attrelid = tgrelid AND a.attnum = cols.attnum
      )
  ) THEN
    RAISE EXCEPTION 'FINAL_CHANCE_DETAIL_TRIGGER_CONTRACT_MISMATCH';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'public.student_extra_chances'::regclass
      AND tgname = 'trg_enforce_final_chance_record_write'
      AND NOT tgisinternal
  ) THEN
    CREATE TRIGGER trg_enforce_final_chance_record_write
      BEFORE INSERT OR UPDATE OF chance_type ON public.student_extra_chances
      FOR EACH ROW EXECUTE FUNCTION public.enforce_final_chance_detail_write();
  ELSIF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'public.student_extra_chances'::regclass
      AND tgname = 'trg_enforce_final_chance_record_write'
      AND tgfoid = 'public.enforce_final_chance_detail_write()'::regprocedure
      AND tgenabled = 'O'
      AND tgtype = 23 -- ROW + BEFORE + INSERT + UPDATE
      AND tgconstraint = 0
      AND tgnargs = 0
      AND (
        SELECT count(*) = 1 AND bool_and(a.attname = 'chance_type')
        FROM unnest(tgattr::smallint[]) AS cols(attnum)
        JOIN pg_attribute a
          ON a.attrelid = tgrelid AND a.attnum = cols.attnum
      )
  ) THEN
    RAISE EXCEPTION 'FINAL_CHANCE_RECORD_TRIGGER_CONTRACT_MISMATCH';
  END IF;
END;
$triggers$;

-- NOT VALID preserves existing historical rows without scanning or rewriting
-- them, while PostgreSQL enforces the predicate for every new/changed row.
DO $constraints$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.extra_chance_details'::regclass
      AND conname = 'ecd_final_chance_new_write_chk'
  ) THEN
    ALTER TABLE public.extra_chance_details
      ADD CONSTRAINT ecd_final_chance_new_write_chk
      CHECK (chance_type = 'final_chance') NOT VALID;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    WHERE c.conrelid = 'public.extra_chance_details'::regclass
      AND c.conname = 'ecd_final_chance_new_write_chk'
      AND c.contype = 'c'
      AND c.convalidated = false
      AND c.connoinherit = false
      AND pg_get_expr(c.conbin, c.conrelid) = '(chance_type = ''final_chance''::text)'
  ) THEN
    RAISE EXCEPTION 'FINAL_CHANCE_DETAIL_CONSTRAINT_CONTRACT_MISMATCH';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.student_extra_chances'::regclass
      AND conname = 'sxc_final_chance_new_write_chk'
  ) THEN
    ALTER TABLE public.student_extra_chances
      ADD CONSTRAINT sxc_final_chance_new_write_chk
      CHECK (chance_type = 'final_chance') NOT VALID;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    WHERE c.conrelid = 'public.student_extra_chances'::regclass
      AND c.conname = 'sxc_final_chance_new_write_chk'
      AND c.contype = 'c'
      AND c.convalidated = false
      AND c.connoinherit = false
      AND pg_get_expr(c.conbin, c.conrelid) = '(chance_type = ''final_chance''::text)'
  ) THEN
    RAISE EXCEPTION 'FINAL_CHANCE_RECORD_CONSTRAINT_CONTRACT_MISMATCH';
  END IF;
END;
$constraints$;

-- Direct client detail writes remain closed until the atomic server-side B1
-- submit boundary is installed and reviewed.
REVOKE ALL PRIVILEGES ON public.extra_chance_details FROM authenticated;
GRANT SELECT ON public.extra_chance_details TO authenticated;

COMMIT;


-- Migration: 20260725110700_b1_14_detail_rpc_write_boundaries_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110700', '20260725110700_b1_14_detail_rpc_write_boundaries_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 14
-- Source draft: docs/migration-drafts/REQUEST-B1-DETAIL-RPC-WRITE-BOUNDARIES-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Installs a locked cutover primitive only; it does not change table access by itself.
-- The future reviewed dispatcher/caller migration must invoke it inside its own transaction.
CREATE OR REPLACE FUNCTION public.apply_b1_detail_rpc_write_boundaries()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $boundaries$
DECLARE
  v_table text; v_prefix text; v_policy text; v_rel regclass; v_count integer;
BEGIN
  IF to_regprocedure('public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[])') IS NULL
     OR EXISTS (
       SELECT 1 FROM pg_proc
       WHERE oid='public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[])'::regprocedure
         AND prosrc LIKE '%B1_SERVICE_PERSISTENCE_NOT_INSTALLED%'
     )
  THEN RAISE EXCEPTION 'B1_DETAIL_DISPATCHER_NOT_INSTALLED'; END IF;

  FOR v_table,v_prefix IN VALUES
    ('enrollment_suspension_details','esd'),
    ('transfer_request_details','trd'),
    ('extra_chance_details','ecd')
  LOOP
    v_rel:=to_regclass('public.'||v_table);
    IF v_rel IS NULL THEN RAISE EXCEPTION 'B1_DETAIL_RELATION_MISSING:%',v_table; END IF;

    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',v_table);
    EXECUTE format('ALTER TABLE public.%I NO FORCE ROW LEVEL SECURITY',v_table);
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',v_table);
    EXECUTE format('GRANT SELECT ON TABLE public.%I TO authenticated,service_role',v_table);
    -- Fail-safe for platform default ACL. Fixed role name only; never allowlisted.
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'sandbox_exec') THEN
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM sandbox_exec', v_table);
    END IF;

    IF EXISTS (SELECT 1 FROM pg_policies
      WHERE schemaname='public' AND tablename=v_table
        AND policyname<>ALL(ARRAY[v_prefix||'_select',v_prefix||'_insert',v_prefix||'_update',v_prefix||'_delete',v_table||'_owner_select']))
      THEN RAISE EXCEPTION 'B1_DETAIL_UNEXPECTED_POLICY:%',v_table; END IF;

    FOR v_policy IN SELECT unnest(ARRAY[v_prefix||'_select',v_prefix||'_insert',v_prefix||'_update',v_prefix||'_delete',v_table||'_owner_select'])
    LOOP
      EXECUTE format('%s POLICY IF EXISTS %I ON public.%I','DROP',v_policy,v_table);
    END LOOP;
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (public.is_owner_of_request(auth.uid(),request_id))',
      v_table||'_owner_select',v_table);

    SELECT count(*) INTO v_count FROM pg_policies
      WHERE schemaname='public' AND tablename=v_table
        AND policyname=v_table||'_owner_select' AND cmd='SELECT' AND permissive='PERMISSIVE'
        AND roles=ARRAY['authenticated'::name]
        AND qual='is_owner_of_request(auth.uid(), request_id)' AND with_check IS NULL;
    IF v_count<>1 OR (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND tablename=v_table)<>1
      THEN RAISE EXCEPTION 'B1_DETAIL_POLICY_INVENTORY_MISMATCH:%',v_table; END IF;

    IF EXISTS (SELECT 1 FROM pg_class c
      CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) x
      LEFT JOIN pg_roles r ON r.oid=x.grantee WHERE c.oid=v_rel
        AND NOT (x.grantee=c.relowner OR
          (r.rolname IN ('authenticated','service_role') AND x.privilege_type='SELECT' AND NOT x.is_grantable)))
      THEN RAISE EXCEPTION 'B1_DETAIL_ACL_INVENTORY_MISMATCH:%',v_table; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.oid=v_rel AND c.relrowsecurity AND NOT c.relforcerowsecurity)
      THEN RAISE EXCEPTION 'B1_DETAIL_RLS_MODE_MISMATCH:%',v_table; END IF;
  END LOOP;
END;
$boundaries$;

REVOKE ALL ON FUNCTION public.apply_b1_detail_rpc_write_boundaries() FROM PUBLIC, anon, authenticated, service_role;


-- Migration: 20260725110800_b1_15_service_details_dispatcher_05a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110800', '20260725110800_b1_15_service_details_dispatcher_05a') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 15
-- Source draft: docs/migration-drafts/REQUEST-B1-SERVICE-DETAILS-05A.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Five-service detail dispatcher installation. Caller/ACL cutover remains separate and fail-closed.

BEGIN;

CREATE OR REPLACE FUNCTION public.persist_validated_b1_request_details(
  p_request_id uuid,p_canonical_code text,p_form_data jsonb,p_attachment_ids uuid[]
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE
  v_request public.student_requests%ROWTYPE;
  v_profile public.student_profiles%ROWTYPE;
  v_allowed text[];
  v_year uuid; v_semester uuid; v_section uuid; v_target_program uuid; v_target_department uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE='28000'; END IF;
  IF p_canonical_code NOT IN ('enrollment_suspension','excused_absence','department_transfer','final_chance','file_withdrawal')
    THEN RAISE EXCEPTION 'B1_CANONICAL_CODE_REQUIRED' USING ERRCODE='22023'; END IF;
  IF p_form_data IS NULL OR jsonb_typeof(p_form_data)<>'object'
    THEN RAISE EXCEPTION 'B1_FORM_OBJECT_REQUIRED' USING ERRCODE='22023'; END IF;

  SELECT r.* INTO v_request FROM public.student_requests r WHERE r.id=p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'B1_REQUEST_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT sp.* INTO v_profile FROM public.student_profiles sp
    WHERE sp.id=v_request.student_profile_id AND sp.user_id=auth.uid() AND sp.status='active' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'B1_ACTIVE_REQUEST_OWNER_REQUIRED' USING ERRCODE='42501'; END IF;
  IF v_request.status NOT IN ('draft','returned','returned_for_completion')
    THEN RAISE EXCEPTION 'B1_REQUEST_NOT_WRITABLE' USING ERRCODE='42501'; END IF;
  IF (CASE v_request.request_type WHEN 'absence_excuse' THEN 'excused_absence'
       WHEN 'transfer' THEN 'department_transfer' WHEN 'extra_chance' THEN 'final_chance'
       ELSE v_request.request_type END) IS DISTINCT FROM p_canonical_code
    THEN RAISE EXCEPTION 'B1_REQUEST_TYPE_MISMATCH' USING ERRCODE='42501'; END IF;

  v_allowed:=CASE p_canonical_code
    WHEN 'enrollment_suspension' THEN ARRAY['target_academic_year','target_semester','suspension_reason','suspension_duration_type','notes','terms_acknowledgment']
    WHEN 'excused_absence' THEN ARRAY['course_section_id','absence_date','reason_type','absence_reason_detail','excuse_documents']
    WHEN 'department_transfer' THEN ARRAY['target_department_id','target_program_id','transfer_reason','secondary_certificate_file']
    WHEN 'final_chance' THEN ARRAY['target_academic_year','target_semester','reason','chance_type']
    WHEN 'file_withdrawal' THEN ARRAY['withdrawal_reason','impact_acknowledgment'] END;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_form_data) k WHERE k<>ALL(v_allowed))
    THEN RAISE EXCEPTION 'B1_UNEXPECTED_FORM_FIELD' USING ERRCODE='22023'; END IF;

  IF p_canonical_code='enrollment_suspension' THEN
    IF COALESCE(cardinality(p_attachment_ids),0)<>0 OR p_form_data->'terms_acknowledgment'<>'true'::jsonb
      OR p_form_data->>'suspension_duration_type' NOT IN ('one_semester','full_year')
      OR length(btrim(COALESCE(p_form_data->>'suspension_reason','')))<3
      THEN RAISE EXCEPTION 'B1_SUSPENSION_INPUT_INVALID' USING ERRCODE='23514'; END IF;
    v_year:=(p_form_data->>'target_academic_year')::uuid; v_semester:=(p_form_data->>'target_semester')::uuid;
    PERFORM public.assert_b1_academic_period_reference(v_year,v_semester);
    INSERT INTO public.enrollment_suspension_details(request_id,requested_from_academic_year_id,requested_from_semester_id,suspension_reason,suspension_duration_type,notes)
      VALUES(p_request_id,v_year,v_semester,btrim(p_form_data->>'suspension_reason'),p_form_data->>'suspension_duration_type',nullif(btrim(p_form_data->>'notes'),''))
      ON CONFLICT(request_id) DO UPDATE SET requested_from_academic_year_id=EXCLUDED.requested_from_academic_year_id,
        requested_from_semester_id=EXCLUDED.requested_from_semester_id,suspension_reason=EXCLUDED.suspension_reason,
        suspension_duration_type=EXCLUDED.suspension_duration_type,notes=EXCLUDED.notes,updated_at=now();

  ELSIF p_canonical_code='excused_absence' THEN
    IF EXISTS (SELECT 1 FROM public.absence_excuse_details d
      WHERE d.request_id=p_request_id AND d.record_applied_at IS NOT NULL)
      THEN RAISE EXCEPTION 'B1_ABSENCE_EFFECT_ALREADY_APPLIED' USING ERRCODE='55000'; END IF;
    v_section:=(p_form_data->>'course_section_id')::uuid;
    IF p_form_data->>'reason_type' NOT IN ('medical','family_emergency','official','other')
      OR length(btrim(COALESCE(p_form_data->>'absence_reason_detail','')))<3
      OR (p_form_data->>'absence_date')::date>current_date
      THEN RAISE EXCEPTION 'B1_ABSENCE_INPUT_INVALID' USING ERRCODE='23514'; END IF;
    PERFORM public.assert_b1_active_course_enrollment(v_profile.id,v_section);
    PERFORM public.assert_required_student_request_attachments(p_request_id,p_attachment_ids);
    INSERT INTO public.absence_excuse_details(request_id,course_section_id,absence_date,reason_type,absence_reason_detail)
      VALUES(p_request_id,v_section,(p_form_data->>'absence_date')::date,p_form_data->>'reason_type',btrim(p_form_data->>'absence_reason_detail'))
      ON CONFLICT(request_id) DO UPDATE SET course_section_id=EXCLUDED.course_section_id,absence_date=EXCLUDED.absence_date,
        reason_type=EXCLUDED.reason_type,absence_reason_detail=EXCLUDED.absence_reason_detail,updated_at=now();

  ELSIF p_canonical_code='department_transfer' THEN
    v_target_department:=(p_form_data->>'target_department_id')::uuid;
    v_target_program:=(p_form_data->>'target_program_id')::uuid;
    IF v_profile.program_id IS NULL OR v_profile.department_id IS NULL
      OR v_target_department=v_profile.department_id OR length(btrim(COALESCE(p_form_data->>'transfer_reason','')))<3
      THEN RAISE EXCEPTION 'B1_TRANSFER_INPUT_INVALID' USING ERRCODE='23514'; END IF;
    PERFORM public.assert_b1_target_program_department(v_target_program,v_target_department);
    PERFORM public.assert_required_student_request_attachments(p_request_id,p_attachment_ids);
    INSERT INTO public.transfer_request_details(request_id,current_program_id,requested_program_id,current_department_id,requested_department_id,transfer_reason)
      VALUES(p_request_id,v_profile.program_id,v_target_program,v_profile.department_id,v_target_department,btrim(p_form_data->>'transfer_reason'))
      ON CONFLICT(request_id) DO UPDATE SET current_program_id=EXCLUDED.current_program_id,requested_program_id=EXCLUDED.requested_program_id,
        current_department_id=EXCLUDED.current_department_id,requested_department_id=EXCLUDED.requested_department_id,
        transfer_reason=EXCLUDED.transfer_reason,updated_at=now();

  ELSIF p_canonical_code='final_chance' THEN
    IF EXISTS (SELECT 1 FROM public.extra_chance_details d
      WHERE d.request_id=p_request_id AND d.chance_applied_at IS NOT NULL)
      THEN RAISE EXCEPTION 'B1_FINAL_CHANCE_EFFECT_ALREADY_APPLIED' USING ERRCODE='55000'; END IF;
    IF COALESCE(cardinality(p_attachment_ids),0)<>0 OR COALESCE(p_form_data->>'chance_type','final_chance')<>'final_chance'
      OR length(btrim(COALESCE(p_form_data->>'reason','')))<3
      THEN RAISE EXCEPTION 'B1_FINAL_CHANCE_INPUT_INVALID' USING ERRCODE='23514'; END IF;
    v_year:=(p_form_data->>'target_academic_year')::uuid; v_semester:=(p_form_data->>'target_semester')::uuid;
    PERFORM public.assert_b1_academic_period_reference(v_year,v_semester);
    INSERT INTO public.extra_chance_details(request_id,academic_year_id,semester_id,reason,chance_type)
      VALUES(p_request_id,v_year,v_semester,btrim(p_form_data->>'reason'),'final_chance')
      ON CONFLICT(request_id) DO UPDATE SET academic_year_id=EXCLUDED.academic_year_id,semester_id=EXCLUDED.semester_id,
        reason=EXCLUDED.reason,chance_type='final_chance',updated_at=now();

  ELSE
    IF EXISTS (SELECT 1 FROM public.file_withdrawal_details d WHERE d.request_id=p_request_id
      AND num_nonnulls(d.library_cleared_at,d.labs_cleared_at,d.activities_cleared_at,
        d.finance_cleared_at,d.records_transferred_at)>0)
      THEN RAISE EXCEPTION 'B1_WITHDRAWAL_CLEARANCE_ALREADY_APPLIED' USING ERRCODE='55000'; END IF;
    IF COALESCE(cardinality(p_attachment_ids),0)<>0 OR p_form_data->'impact_acknowledgment'<>'true'::jsonb
      OR length(btrim(COALESCE(p_form_data->>'withdrawal_reason','')))<10
      THEN RAISE EXCEPTION 'B1_WITHDRAWAL_INPUT_INVALID' USING ERRCODE='23514'; END IF;
    INSERT INTO public.file_withdrawal_details(request_id,withdrawal_reason,impact_ack)
      VALUES(p_request_id,btrim(p_form_data->>'withdrawal_reason'),true)
      ON CONFLICT(request_id) DO UPDATE SET withdrawal_reason=EXCLUDED.withdrawal_reason,impact_ack=true,updated_at=now();
  END IF;
END $$;

REVOKE ALL ON FUNCTION public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[]) FROM PUBLIC,anon,authenticated,service_role;

COMMIT;


-- Migration: 20260725110900_b1_16_free_service_workflows_08.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725110900', '20260725110900_b1_16_free_service_workflows_08') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 16
-- Source draft: docs/migration-drafts/B1-FREE-SERVICE-WORKFLOWS-08.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Creates inactive workflow drafts for exactly the three FREE_NO_PAYMENT services.
-- No activation, student visibility, payment, financial ledger, document, or data backfill.
BEGIN;

DO $migration$
DECLARE
  v_service record; v_step record; v_transition record;
  v_request_type_id uuid; v_workflow_id uuid; v_unit_id uuid; v_role_id uuid;
  v_step_ids jsonb; v_from_id uuid; v_to_id uuid; v_count integer; v_matching_count integer; v_version integer;
  v_marker constant text := 'B1_FREE_NO_PAYMENT/workflow-v1';
BEGIN
  FOR v_service IN SELECT * FROM (VALUES
    ('enrollment_suspension'::text,ARRAY['enrollment_suspension']::text[],'وقف القيد'::text,
      jsonb_build_array(
        jsonb_build_object('key','initial_review','name','المراجعة الأولية','unit','student_affairs','role','student_affairs_specialist','action','review'),
        jsonb_build_object('key','manager_approval','name','اعتماد مدير شؤون الطلاب','unit','student_affairs','role','student_affairs_manager','action','approve'),
        jsonb_build_object('key','registrar_apply','name','تطبيق قرار وقف القيد','unit','registrar','role','registrar_general','action','apply_decision')),
      jsonb_build_array(
        jsonb_build_object('from',NULL,'to','initial_review','result','submit'),
        jsonb_build_object('from','initial_review','to','manager_approval','result','reviewed'),
        jsonb_build_object('from','manager_approval','to','registrar_apply','result','approved'),
        jsonb_build_object('from','registrar_apply','to',NULL,'result','applied'))),
    ('excused_absence'::text,ARRAY['excused_absence','absence_excuse']::text[],'غياب بعذر'::text,
      jsonb_build_array(
        jsonb_build_object('key','student_affairs_intake','name','استلام شؤون الطلاب','unit','student_affairs','role','student_affairs_specialist','action','review'),
        jsonb_build_object('key','manager_review','name','اعتماد مدير شؤون الطلاب','unit','student_affairs','role','student_affairs_manager','action','approve'),
        jsonb_build_object('key','record_apply','name','تطبيق العذر في السجل','unit','student_affairs','role','student_affairs_specialist','action','apply_decision')),
      jsonb_build_array(
        jsonb_build_object('from',NULL,'to','student_affairs_intake','result','submit'),
        jsonb_build_object('from','student_affairs_intake','to','manager_review','result','reviewed'),
        jsonb_build_object('from','manager_review','to','record_apply','result','approved'),
        jsonb_build_object('from','record_apply','to',NULL,'result','applied'))),
    ('file_withdrawal'::text,ARRAY['file_withdrawal']::text[],'سحب الملف'::text,
      jsonb_build_array(
        jsonb_build_object('key','student_affairs_intake','name','استلام شؤون الطلاب','unit','student_affairs','role','student_affairs_specialist','action','review'),
        jsonb_build_object('key','library_clearance','name','مخالصة المكتبة','unit','library','role','library_officer','action','clear'),
        jsonb_build_object('key','labs_clearance','name','مخالصة المعامل','unit','labs','role','labs_manager','action','clear'),
        jsonb_build_object('key','activities_clearance','name','مخالصة الأنشطة','unit','student_affairs','role','student_affairs_manager','action','clear'),
        jsonb_build_object('key','finance_clearance','name','المخالصة المالية','unit','finance','role','revenue_finance_officer','action','clear'),
        jsonb_build_object('key','registrar_apply','name','تطبيق قرار سحب الملف','unit','registrar','role','registrar_general','action','apply_decision'),
        jsonb_build_object('key','archive','name','الأرشفة','unit','archive','role','archive_officer','action','archive')),
      jsonb_build_array(
        jsonb_build_object('from',NULL,'to','student_affairs_intake','result','submit'),
        jsonb_build_object('from','student_affairs_intake','to','library_clearance','result','reviewed'),
        jsonb_build_object('from','library_clearance','to','labs_clearance','result','cleared'),
        jsonb_build_object('from','labs_clearance','to','activities_clearance','result','cleared'),
        jsonb_build_object('from','activities_clearance','to','finance_clearance','result','cleared'),
        jsonb_build_object('from','finance_clearance','to','registrar_apply','result','cleared'),
        jsonb_build_object('from','registrar_apply','to','archive','result','applied'),
        jsonb_build_object('from','archive','to',NULL,'result','archived')))
  ) AS services(canonical_code,stored_codes,name_ar,steps,transitions)
  LOOP
    SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_count,v_request_type_id
    FROM public.request_types WHERE code=ANY(v_service.stored_codes);
    IF v_count<>1 THEN RAISE EXCEPTION 'FREE_WORKFLOW_REQUEST_TYPE_MUST_RESOLVE_ONCE:%:%',v_service.canonical_code,v_count; END IF;

    SELECT count(*),
      count(*) FILTER (WHERE status='draft' AND is_active=false AND description_ar=v_marker),
      (array_agg(id ORDER BY id) FILTER (WHERE status='draft' AND is_active=false AND description_ar=v_marker))[1]
      INTO v_count,v_matching_count,v_workflow_id
    FROM public.request_type_workflows
    WHERE request_type_id=v_request_type_id AND code=v_service.canonical_code||'_free_workflow';
    IF v_count>1 OR (v_count=1 AND v_matching_count<>1) THEN
      RAISE EXCEPTION 'FREE_WORKFLOW_INVENTORY_MISMATCH:%:%:%',v_service.canonical_code,v_count,v_matching_count;
    END IF;
    IF v_count=0 THEN
      SELECT COALESCE(max(version),0)+1 INTO v_version FROM public.request_type_workflows
      WHERE request_type_id=v_request_type_id AND code=v_service.canonical_code||'_free_workflow';
      INSERT INTO public.request_type_workflows(request_type_id,code,name_ar,description_ar,version,status,is_active)
      VALUES(v_request_type_id,v_service.canonical_code||'_free_workflow',v_service.name_ar,v_marker,v_version,'draft',false)
      RETURNING id INTO v_workflow_id;
      v_step_ids:='{}'::jsonb;
      FOR v_step IN SELECT value,ordinality FROM jsonb_array_elements(v_service.steps) WITH ORDINALITY ORDER BY ordinality LOOP
        SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_count,v_unit_id
        FROM public.request_processing_units WHERE code=v_step.value->>'unit' AND is_active=true;
        IF v_count<>1 THEN RAISE EXCEPTION 'FREE_WORKFLOW_UNIT_MUST_RESOLVE_ONCE:%:%',v_step.value->>'unit',v_count; END IF;
        SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_count,v_role_id
        FROM public.request_processing_roles WHERE code=v_step.value->>'role' AND unit_id=v_unit_id AND is_active=true;
        IF v_count<>1 THEN RAISE EXCEPTION 'FREE_WORKFLOW_ROLE_MUST_RESOLVE_ONCE:%:%',v_step.value->>'role',v_count; END IF;
        INSERT INTO public.request_type_workflow_steps(workflow_id,step_key,step_name_ar,step_order,
          processing_unit_id,processing_role_id,assignment_strategy,action_type,status_on_enter,status_on_complete,
          is_required,can_skip,requires_payment,produces_document,config)
        VALUES(v_workflow_id,v_step.value->>'key',v_step.value->>'name',v_step.ordinality,v_unit_id,v_role_id,
          'specific_user',v_step.value->>'action','in_progress','completed',true,false,false,false,
          jsonb_build_object('authorization','exactly_one_direct_assignee','payment_policy','FREE_NO_PAYMENT'))
        RETURNING id INTO v_unit_id;
        v_step_ids:=v_step_ids||jsonb_build_object(v_step.value->>'key',v_unit_id);
      END LOOP;
      FOR v_transition IN SELECT value FROM jsonb_array_elements(v_service.transitions) LOOP
        v_from_id:=CASE WHEN v_transition.value->>'from' IS NULL THEN NULL ELSE (v_step_ids->>(v_transition.value->>'from'))::uuid END;
        v_to_id:=CASE WHEN v_transition.value->>'to' IS NULL THEN NULL ELSE (v_step_ids->>(v_transition.value->>'to'))::uuid END;
        INSERT INTO public.request_type_workflow_transitions(workflow_id,from_step_id,to_step_id,action_result,is_default)
        VALUES(v_workflow_id,v_from_id,v_to_id,v_transition.value->>'result',true);
      END LOOP;
    END IF;

    SELECT count(*) INTO v_count FROM public.request_type_workflow_steps WHERE workflow_id=v_workflow_id;
    IF v_count<>jsonb_array_length(v_service.steps) OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_service.steps) WITH ORDINALITY e(value,ordinality)
      LEFT JOIN public.request_type_workflow_steps s ON s.workflow_id=v_workflow_id AND s.step_key=e.value->>'key'
      LEFT JOIN public.request_processing_units u ON u.id=s.processing_unit_id
      LEFT JOIN public.request_processing_roles r ON r.id=s.processing_role_id
      WHERE s.id IS NULL OR s.step_order<>e.ordinality OR u.code IS DISTINCT FROM e.value->>'unit'
        OR r.code IS DISTINCT FROM e.value->>'role' OR s.action_type IS DISTINCT FROM e.value->>'action'
        OR s.assignment_strategy IS DISTINCT FROM 'specific_user' OR s.status_on_enter IS DISTINCT FROM 'in_progress'
        OR s.status_on_complete IS DISTINCT FROM 'completed' OR s.is_required IS DISTINCT FROM true
        OR s.can_skip IS DISTINCT FROM false OR s.requires_payment IS DISTINCT FROM false
        OR s.produces_document IS DISTINCT FROM false OR s.config->>'authorization' IS DISTINCT FROM 'exactly_one_direct_assignee'
        OR s.config->>'payment_policy' IS DISTINCT FROM 'FREE_NO_PAYMENT')
    THEN RAISE EXCEPTION 'FREE_WORKFLOW_STEP_STRUCTURE_MISMATCH:%',v_service.canonical_code; END IF;

    SELECT count(*) INTO v_count FROM public.request_type_workflow_transitions WHERE workflow_id=v_workflow_id;
    IF v_count<>jsonb_array_length(v_service.transitions) OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_service.transitions) e WHERE NOT EXISTS (
        SELECT 1 FROM public.request_type_workflow_transitions t
        LEFT JOIN public.request_type_workflow_steps fs ON fs.id=t.from_step_id
        LEFT JOIN public.request_type_workflow_steps ts ON ts.id=t.to_step_id
        WHERE t.workflow_id=v_workflow_id AND fs.step_key IS NOT DISTINCT FROM e.value->>'from'
          AND ts.step_key IS NOT DISTINCT FROM e.value->>'to' AND t.action_result=e.value->>'result' AND t.is_default=true))
    THEN RAISE EXCEPTION 'FREE_WORKFLOW_TRANSITION_STRUCTURE_MISMATCH:%',v_service.canonical_code; END IF;
  END LOOP;
END
$migration$;

COMMIT;


-- Migration: 20260725111000_b1_17_external_university_payment_workflows_02.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725111000', '20260725111000_b1_17_external_university_payment_workflows_02') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 17
-- Source draft: docs/migration-drafts/EXTERNAL-UNIVERSITY-PAYMENT-WORKFLOWS-02.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Migration 2/3 for EXTERNAL_UNIVERSITY_PAYMENT_CONFIRMATION.
-- Creates inactive workflow drafts only. It does not activate a workflow, mutate
-- a request, or store any financial ledger data.

DO $migration$
DECLARE
  v_service record;
  v_request_type_id uuid;
  v_workflow_id uuid;
  v_version integer;
  v_existing_count integer;
  v_unit_id uuid;
  v_role_id uuid;
  v_step record;
  v_transition record;
  v_step_ids jsonb;
  v_from_id uuid;
  v_to_id uuid;
  v_contract_marker constant text :=
    'EXTERNAL_UNIVERSITY_PAYMENT_CONFIRMATION/workflow-v1';
BEGIN
  FOR v_service IN
    SELECT *
    FROM (VALUES
      (
        'department_transfer'::text,
        ARRAY['department_transfer','transfer']::text[],
        'تحويل من قسم إلى قسم'::text,
        jsonb_build_array(
          jsonb_build_object('key','student_affairs_intake','name_ar','مراجعة شؤون الطلاب','unit','student_affairs','role','student_affairs_specialist','action','review','scope','request'),
          jsonb_build_object('key','source_department_head_approval','name_ar','موافقة رئيس القسم الحالي','unit','department','role','department_head','action','approve','scope','source_department'),
          jsonb_build_object('key','target_department_head_approval','name_ar','موافقة رئيس القسم المطلوب','unit','department','role','department_head','action','approve','scope','target_department'),
          jsonb_build_object('key','dean_approval','name_ar','موافقة العميد','unit','dean','role','dean','action','approve','scope','request'),
          jsonb_build_object('key','payment_confirmation','name_ar','تأكيد استلام الرسوم خارج البوابة','unit','finance','role','revenue_finance_officer','action','confirm_payment','scope','request'),
          jsonb_build_object('key','registrar_apply','name_ar','تطبيق قرار التحويل','unit','registrar','role','registrar_general','action','apply_decision','scope','request')
        ),
        jsonb_build_array(
          jsonb_build_object('from',NULL,'to','student_affairs_intake','result','submit'),
          jsonb_build_object('from','student_affairs_intake','to','source_department_head_approval','result','reviewed'),
          jsonb_build_object('from','source_department_head_approval','to','target_department_head_approval','result','approved'),
          jsonb_build_object('from','target_department_head_approval','to','dean_approval','result','approved'),
          jsonb_build_object('from','dean_approval','to','payment_confirmation','result','approved'),
          jsonb_build_object('from','payment_confirmation','to','registrar_apply','result','payment_confirmed'),
          jsonb_build_object('from','registrar_apply','to',NULL,'result','applied')
        )
      ),
      (
        'final_chance'::text,
        ARRAY['final_chance','extra_chance']::text[],
        'فرصة نهائية للاختبار'::text,
        jsonb_build_array(
          jsonb_build_object('key','student_affairs_intake','name_ar','مراجعة شؤون الطلاب','unit','student_affairs','role','student_affairs_specialist','action','review','scope','request'),
          jsonb_build_object('key','manager_review','name_ar','مراجعة مدير شؤون الطلاب','unit','student_affairs','role','student_affairs_manager','action','approve','scope','request'),
          jsonb_build_object('key','dean_decision','name_ar','قرار العميد','unit','dean','role','dean','action','approve','scope','request'),
          jsonb_build_object('key','payment_confirmation','name_ar','تأكيد استلام الرسوم خارج البوابة','unit','finance','role','revenue_finance_officer','action','confirm_payment','scope','request'),
          jsonb_build_object('key','registrar_apply','name_ar','تطبيق فرصة الاختبار النهائية','unit','registrar','role','registrar_general','action','apply_decision','scope','request')
        ),
        jsonb_build_array(
          jsonb_build_object('from',NULL,'to','student_affairs_intake','result','submit'),
          jsonb_build_object('from','student_affairs_intake','to','manager_review','result','reviewed'),
          jsonb_build_object('from','manager_review','to','dean_decision','result','approved'),
          jsonb_build_object('from','dean_decision','to','payment_confirmation','result','approved'),
          jsonb_build_object('from','payment_confirmation','to','registrar_apply','result','payment_confirmed'),
          jsonb_build_object('from','registrar_apply','to',NULL,'result','applied')
        )
      )
    ) AS services(canonical_code, stored_codes, name_ar, steps, transitions)
  LOOP
    SELECT count(*), (array_agg(rt.id ORDER BY rt.id))[1]
      INTO v_existing_count, v_request_type_id
    FROM public.request_types rt
    WHERE rt.code = ANY(v_service.stored_codes);

    IF v_existing_count <> 1 THEN
      RAISE EXCEPTION 'PAYMENT_WORKFLOW_REQUEST_TYPE_MUST_RESOLVE_EXACTLY_ONCE:%:%',
        v_service.canonical_code, v_existing_count;
    END IF;

    SELECT count(*), (array_agg(w.id ORDER BY w.id))[1]
      INTO v_existing_count, v_workflow_id
    FROM public.request_type_workflows w
    WHERE w.request_type_id = v_request_type_id
      AND w.code = v_service.canonical_code || '_external_payment_workflow'
      AND w.status = 'draft'
      AND w.is_active = false
      AND w.description_ar = v_contract_marker;

    IF v_existing_count > 1 THEN
      RAISE EXCEPTION 'DUPLICATE_EXTERNAL_PAYMENT_WORKFLOW_DRAFT:%', v_service.canonical_code;
    END IF;

    IF v_existing_count = 0 THEN
      SELECT COALESCE(max(w.version), 0) + 1
        INTO v_version
      FROM public.request_type_workflows w
      WHERE w.request_type_id = v_request_type_id
        AND w.code = v_service.canonical_code || '_external_payment_workflow';

      INSERT INTO public.request_type_workflows (
        request_type_id, code, name_ar, description_ar, version, status, is_active
      ) VALUES (
        v_request_type_id,
        v_service.canonical_code || '_external_payment_workflow',
        v_service.name_ar,
        v_contract_marker,
        v_version,
        'draft',
        false
      ) RETURNING id INTO v_workflow_id;

      v_step_ids := '{}'::jsonb;
      FOR v_step IN
        SELECT value, ordinality
        FROM jsonb_array_elements(v_service.steps) WITH ORDINALITY
        ORDER BY ordinality
      LOOP
        SELECT count(*), (array_agg(u.id ORDER BY u.id))[1]
          INTO v_existing_count, v_unit_id
        FROM public.request_processing_units u
        WHERE u.code = v_step.value ->> 'unit' AND u.is_active = true;
        IF v_existing_count <> 1 THEN
          RAISE EXCEPTION 'PROCESSING_UNIT_MUST_RESOLVE_EXACTLY_ONCE:%:%',
            v_step.value ->> 'unit', v_existing_count;
        END IF;

        SELECT count(*), (array_agg(r.id ORDER BY r.id))[1]
          INTO v_existing_count, v_role_id
        FROM public.request_processing_roles r
        WHERE r.code = v_step.value ->> 'role'
          AND r.unit_id = v_unit_id
          AND r.is_active = true;
        IF v_existing_count <> 1 THEN
          RAISE EXCEPTION 'PROCESSING_ROLE_MUST_RESOLVE_EXACTLY_ONCE:%:%',
            v_step.value ->> 'role', v_existing_count;
        END IF;

        INSERT INTO public.request_type_workflow_steps (
          workflow_id, step_key, step_name_ar, step_order,
          processing_unit_id, processing_role_id, assignment_strategy,
          action_type, status_on_enter, status_on_complete,
          is_required, can_skip, requires_payment, produces_document, config
        ) VALUES (
          v_workflow_id,
          v_step.value ->> 'key',
          v_step.value ->> 'name_ar',
          v_step.ordinality,
          v_unit_id,
          v_role_id,
          'specific_user',
          v_step.value ->> 'action',
          CASE WHEN v_step.value ->> 'key' = 'payment_confirmation'
            THEN 'awaiting_payment_confirmation' ELSE 'in_progress' END,
          CASE WHEN v_step.value ->> 'key' = 'payment_confirmation'
            THEN 'payment_confirmed' ELSE 'completed' END,
          true,
          false,
          false,
          false,
          jsonb_build_object(
            'authorization', 'exactly_one_direct_assignee',
            'department_scope', v_step.value ->> 'scope',
            'payment_policy', CASE WHEN v_step.value ->> 'key' = 'payment_confirmation'
              THEN 'EXTERNAL_UNIVERSITY_PAYMENT_CONFIRMATION' ELSE NULL END
          )
        ) RETURNING id INTO v_unit_id;
        v_step_ids := v_step_ids || jsonb_build_object(v_step.value ->> 'key', v_unit_id);
      END LOOP;

      FOR v_transition IN SELECT value FROM jsonb_array_elements(v_service.transitions)
      LOOP
        v_from_id := CASE WHEN v_transition.value ->> 'from' IS NULL THEN NULL
          ELSE (v_step_ids ->> (v_transition.value ->> 'from'))::uuid END;
        v_to_id := CASE WHEN v_transition.value ->> 'to' IS NULL THEN NULL
          ELSE (v_step_ids ->> (v_transition.value ->> 'to'))::uuid END;

        INSERT INTO public.request_type_workflow_transitions (
          workflow_id, from_step_id, to_step_id, action_result, is_default
        ) VALUES (
          v_workflow_id, v_from_id, v_to_id, v_transition.value ->> 'result', true
        );
      END LOOP;
    END IF;

    -- Reused drafts are accepted only when their full structure still equals the
    -- declared contract. A partial or edited marker-matching draft fails closed.
    SELECT count(*) INTO v_existing_count
    FROM public.request_type_workflow_steps s
    WHERE s.workflow_id = v_workflow_id;
    IF v_existing_count <> jsonb_array_length(v_service.steps) OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_service.steps) WITH ORDINALITY expected(value, ordinality)
      LEFT JOIN public.request_type_workflow_steps s
        ON s.workflow_id = v_workflow_id
       AND s.step_key = expected.value ->> 'key'
      LEFT JOIN public.request_processing_units u ON u.id = s.processing_unit_id
      LEFT JOIN public.request_processing_roles r ON r.id = s.processing_role_id
      WHERE s.id IS NULL
         OR s.step_order <> expected.ordinality
         OR u.code IS DISTINCT FROM expected.value ->> 'unit'
         OR r.code IS DISTINCT FROM expected.value ->> 'role'
         OR s.action_type IS DISTINCT FROM expected.value ->> 'action'
         OR s.assignment_strategy IS DISTINCT FROM 'specific_user'
         OR s.is_required IS DISTINCT FROM true
         OR s.can_skip IS DISTINCT FROM false
         OR s.requires_payment IS DISTINCT FROM false
         OR s.produces_document IS DISTINCT FROM false
         OR s.config ->> 'authorization' IS DISTINCT FROM 'exactly_one_direct_assignee'
         OR s.config ->> 'department_scope' IS DISTINCT FROM expected.value ->> 'scope'
         OR (expected.value ->> 'key' = 'payment_confirmation' AND (
              s.status_on_enter IS DISTINCT FROM 'awaiting_payment_confirmation'
              OR s.status_on_complete IS DISTINCT FROM 'payment_confirmed'
              OR s.config ->> 'payment_policy' IS DISTINCT FROM 'EXTERNAL_UNIVERSITY_PAYMENT_CONFIRMATION'
            ))
         OR (expected.value ->> 'key' <> 'payment_confirmation' AND (
              s.status_on_enter IS DISTINCT FROM 'in_progress'
              OR s.status_on_complete IS DISTINCT FROM 'completed'
              OR s.config ->> 'payment_policy' IS NOT NULL
            ))
    ) THEN
      RAISE EXCEPTION 'EXTERNAL_PAYMENT_WORKFLOW_STEP_STRUCTURE_MISMATCH:%',
        v_service.canonical_code;
    END IF;

    SELECT count(*) INTO v_existing_count
    FROM public.request_type_workflow_transitions t
    WHERE t.workflow_id = v_workflow_id;
    IF v_existing_count <> jsonb_array_length(v_service.transitions) OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_service.transitions) expected
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.request_type_workflow_transitions t
        LEFT JOIN public.request_type_workflow_steps fs ON fs.id = t.from_step_id
        LEFT JOIN public.request_type_workflow_steps ts ON ts.id = t.to_step_id
        WHERE t.workflow_id = v_workflow_id
          AND fs.step_key IS NOT DISTINCT FROM expected.value ->> 'from'
          AND ts.step_key IS NOT DISTINCT FROM expected.value ->> 'to'
          AND t.action_result = expected.value ->> 'result'
          AND t.is_default = true
      )
    ) THEN
      RAISE EXCEPTION 'EXTERNAL_PAYMENT_WORKFLOW_TRANSITION_STRUCTURE_MISMATCH:%',
        v_service.canonical_code;
    END IF;

    SELECT count(*) INTO v_existing_count
    FROM public.request_type_workflow_transitions t
    JOIN public.request_type_workflow_steps s ON s.id = t.from_step_id
    WHERE t.workflow_id = v_workflow_id
      AND s.step_key = 'payment_confirmation'
      AND t.action_result = 'payment_confirmed';
    IF v_existing_count <> 1 THEN
      RAISE EXCEPTION 'EXACTLY_ONE_PAYMENT_CONFIRMED_TRANSITION_REQUIRED:%:%',
        v_service.canonical_code, v_existing_count;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.request_type_workflow_steps s
      WHERE s.workflow_id = v_workflow_id
        AND (s.step_key = 'fee_assessment' OR s.requires_payment = true)
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_LEDGER_STEP_FORBIDDEN:%', v_service.canonical_code;
    END IF;
  END LOOP;
END;
$migration$;


-- Migration: 20260725111100_b1_18_detail_acl_cutover_06.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725111100', '20260725111100_b1_18_detail_acl_cutover_06') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-FIVE-SERVICES-BACKEND-IMPLEMENTATION-01 / order 18
-- Source draft: docs/migration-drafts/REQUEST-B1-DETAIL-ACL-CUTOVER-06.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/
-- Semantic parity with the source draft is required; production apply is a separate gate.

-- Atomic final cutover: only after 04, every 05A prerequisite, free/paid inactive
-- workflows, and trustworthy atomic-caller release evidence (order-1 stamp).
BEGIN;

DO $preflight$
DECLARE
  v_atomic text;
  v_dispatcher text;
  v_release text;
  v_table text;
  v_rel regclass;
BEGIN
  IF to_regprocedure('public.submit_b1_student_request_atomic(uuid,text,jsonb,timestamptz,uuid[])') IS NULL
     OR to_regprocedure('public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[])') IS NULL
     OR to_regprocedure('public.apply_b1_detail_rpc_write_boundaries()') IS NULL
  THEN
    RAISE EXCEPTION 'B1_ACL_CUTOVER_PREREQUISITE_MISSING';
  END IF;

  SELECT p.prosrc INTO v_atomic
  FROM pg_proc p
  WHERE p.oid = 'public.submit_b1_student_request_atomic(uuid,text,jsonb,timestamptz,uuid[])'::regprocedure;
  SELECT p.prosrc INTO v_dispatcher
  FROM pg_proc p
  WHERE p.oid = 'public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[])'::regprocedure;

  IF v_atomic NOT LIKE '%PERFORM public.persist_validated_b1_request_details(%'
     OR v_dispatcher LIKE '%B1_SERVICE_PERSISTENCE_NOT_INSTALLED%'
     OR v_dispatcher NOT LIKE '%enrollment_suspension%'
     OR v_dispatcher NOT LIKE '%excused_absence%'
     OR v_dispatcher NOT LIKE '%department_transfer%'
     OR v_dispatcher NOT LIKE '%final_chance%'
     OR v_dispatcher NOT LIKE '%file_withdrawal%'
  THEN
    RAISE EXCEPTION 'B1_ACL_CUTOVER_CALLER_DISPATCHER_MISMATCH';
  END IF;

  v_release := obj_description(
    'public.submit_b1_student_request_atomic(uuid,text,jsonb,timestamptz,uuid[])'::regprocedure,
    'pg_proc'
  );
  IF v_release IS NULL
     OR v_release !~ '^B1_ATOMIC_CALLER_RELEASE_EVIDENCE=[0-9a-f]{40}$'
  THEN
    RAISE EXCEPTION 'B1_ACL_CUTOVER_RELEASE_EVIDENCE_MISSING';
  END IF;

  IF has_function_privilege('anon','public.submit_b1_student_request_atomic(uuid,text,jsonb,timestamptz,uuid[])','EXECUTE')
     OR NOT has_function_privilege('authenticated','public.submit_b1_student_request_atomic(uuid,text,jsonb,timestamptz,uuid[])','EXECUTE')
     OR has_function_privilege('authenticated','public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[])','EXECUTE')
     OR has_function_privilege('service_role','public.persist_validated_b1_request_details(uuid,text,jsonb,uuid[])','EXECUTE')
     OR has_function_privilege('authenticated','public.apply_b1_detail_rpc_write_boundaries()','EXECUTE')
     OR has_function_privilege('service_role','public.apply_b1_detail_rpc_write_boundaries()','EXECUTE')
  THEN
    RAISE EXCEPTION 'B1_ACL_CUTOVER_FUNCTION_ACL_MISMATCH';
  END IF;

  -- Five detail-boundary prerequisites: absence and withdrawal must already be
  -- owner-read / RPC-write (05A). The three legacy tables are cut over below.
  FOREACH v_table IN ARRAY ARRAY[
    'absence_excuse_details',
    'file_withdrawal_details'
  ]
  LOOP
    v_rel := to_regclass('public.' || v_table);
    IF v_rel IS NULL
       OR has_table_privilege('anon', v_rel, 'SELECT,INSERT,UPDATE,DELETE')
       OR has_table_privilege('authenticated', v_rel, 'INSERT,UPDATE,DELETE')
       OR has_table_privilege('service_role', v_rel, 'INSERT,UPDATE,DELETE')
       OR NOT has_table_privilege('authenticated', v_rel, 'SELECT')
       OR NOT has_table_privilege('service_role', v_rel, 'SELECT')
    THEN
      RAISE EXCEPTION 'B1_ACL_CUTOVER_FIVE_BOUNDARY_PREREQUISITE_FAILED:%', v_table;
    END IF;
  END LOOP;

  FOREACH v_table IN ARRAY ARRAY[
    'enrollment_suspension_details',
    'transfer_request_details',
    'extra_chance_details'
  ]
  LOOP
    IF to_regclass('public.' || v_table) IS NULL THEN
      RAISE EXCEPTION 'B1_ACL_CUTOVER_LEGACY_DETAIL_MISSING:%', v_table;
    END IF;
  END LOOP;
END
$preflight$;

SELECT public.apply_b1_detail_rpc_write_boundaries();

DO $verify$
DECLARE
  v_table text;
  v_rel regclass;
BEGIN
  FOREACH v_table IN ARRAY ARRAY[
    'enrollment_suspension_details',
    'absence_excuse_details',
    'transfer_request_details',
    'extra_chance_details',
    'file_withdrawal_details'
  ]
  LOOP
    v_rel := to_regclass('public.' || v_table);
    IF v_rel IS NULL
       OR has_table_privilege('anon', v_rel, 'SELECT,INSERT,UPDATE,DELETE')
       OR has_table_privilege('authenticated', v_rel, 'INSERT,UPDATE,DELETE')
       OR has_table_privilege('service_role', v_rel, 'INSERT,UPDATE,DELETE')
       OR NOT has_table_privilege('authenticated', v_rel, 'SELECT')
       OR NOT has_table_privilege('service_role', v_rel, 'SELECT')
    THEN
      RAISE EXCEPTION 'B1_ACL_CUTOVER_POSTVERIFY_FAILED:%', v_table;
    END IF;
  END LOOP;
END
$verify$;

COMMIT;


-- Migration: 20260725120000_b1_confirm_payment_predecessor_guard_01.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260725120000', '20260725120000_b1_confirm_payment_predecessor_guard_01') ON CONFLICT (version) DO NOTHING;
-- PROMOTED MIGRATION - NOT APPLIED TO PRODUCTION
-- REQUIRES EXPLICIT SINGLE-MIGRATION APPROVAL
-- Track: PORTAL-B1-CONFIRM-PAYMENT-PREDECESSOR-GUARD-01 / sequence 20
-- Source draft: docs/migration-drafts/B1-CONFIRM-PAYMENT-PREDECESSOR-GUARD-01.sql
-- Companion preflight/post-verifier: docs/migration-drafts/b1-backend-verifiers/19-*
-- Forward-only REPLACE of record_external_university_payment_confirmation(uuid,text).
-- Does not modify historical migration 20260725002135_*.
-- B1-CONFIRM-PAYMENT-PREDECESSOR-GUARD-01
-- Forward-only remediation for record_external_university_payment_confirmation(uuid,text).
-- Closes incomplete-predecessor bypass on payment_confirmation for
-- department_transfer/transfer and final_chance/extra_chance.
-- Does NOT modify historical migration 20260725002135_*.
-- Signature, success shape, grants, and simplified revenue contract are unchanged.

CREATE OR REPLACE FUNCTION public.record_external_university_payment_confirmation(
  p_step_id uuid,
  p_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_step public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_request_type text;
  v_unit_code text;
  v_role_code text;
  v_transition public.request_type_workflow_transitions%ROWTYPE;
  v_next_step_id uuid;
  v_direct_count integer;
  v_transition_count integer;
  v_actor_matches boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '28000';
  END IF;
  PERFORM set_config('b1.specialized_action', '1', true);
  IF p_note IS NOT NULL AND char_length(btrim(p_note)) > 2000 THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRMATION_NOTE_TOO_LONG' USING ERRCODE = '22023';
  END IF;

  -- Lock before authorization: the assignee and active state cannot change
  -- between authorization and mutation.
  SELECT s.* INTO v_step
  FROM public.student_request_workflow_steps s
  WHERE s.id = p_step_id
  FOR UPDATE OF s;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRMATION_STEP_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  SELECT r.request_type, u.code, pr.code
  INTO v_request_type, v_unit_code, v_role_code
  FROM public.student_requests r
  LEFT JOIN public.request_processing_units u ON u.id = v_step.processing_unit_id
  LEFT JOIN public.request_processing_roles pr ON pr.id = v_step.processing_role_id
  WHERE r.id = v_step.student_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRMATION_REQUEST_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;
  -- transfer and extra_chance are historical stored-code aliases for the two
  -- approved canonical services; they do not broaden the service policy.
  IF v_request_type NOT IN ('department_transfer','transfer','final_chance','extra_chance') THEN
    RAISE EXCEPTION 'REQUEST_TYPE_NOT_EXTERNAL_PAYMENT_SERVICE' USING ERRCODE = '22023';
  END IF;
  IF v_step.status IS DISTINCT FROM 'active'
     OR v_step.step_key IS DISTINCT FROM 'payment_confirmation'
     OR v_unit_code IS DISTINCT FROM 'finance'
     OR v_role_code IS DISTINCT FROM 'revenue_finance_officer' THEN
    RAISE EXCEPTION 'INVALID_ACTIVE_PAYMENT_CONFIRMATION_STEP' USING ERRCODE = '22023';
  END IF;

  SELECT c.* INTO v_config
  FROM public.request_type_workflow_steps c
  WHERE c.id = v_step.workflow_step_id;
  IF NOT FOUND OR v_config.action_type IS DISTINCT FROM 'confirm_payment' THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRMATION_ACTION_MISMATCH' USING ERRCODE = '22023';
  END IF;

  -- Direct assignment is mandatory and exclusive. No role-pool helper is called.
  v_direct_count := num_nonnulls(
    v_step.assigned_user_id,
    v_step.assigned_staff_profile_id,
    v_step.assigned_faculty_profile_id,
    v_step.assigned_position_assignment_id
  );
  IF v_direct_count IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'EXACTLY_ONE_DIRECT_PAYMENT_ASSIGNEE_REQUIRED' USING ERRCODE = '42501';
  END IF;

  v_actor_matches :=
    v_step.assigned_user_id = v_uid
    OR EXISTS (SELECT 1 FROM public.staff_profiles sp
      WHERE sp.id = v_step.assigned_staff_profile_id AND sp.user_id = v_uid)
    OR EXISTS (SELECT 1 FROM public.faculty_profiles fp
      WHERE fp.id = v_step.assigned_faculty_profile_id AND fp.user_id = v_uid)
    OR EXISTS (SELECT 1 FROM public.position_assignments pa
      WHERE pa.id = v_step.assigned_position_assignment_id
        AND pa.user_id = v_uid AND pa.is_active = true
        AND (pa.assigned_to IS NULL OR pa.assigned_to >= CURRENT_DATE));
  IF NOT COALESCE(v_actor_matches, false) THEN
    RAISE EXCEPTION 'DIRECT_PAYMENT_ASSIGNEE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_has_exact_processing_binding(
    v_step.processing_unit_id, v_step.processing_role_id
  ) THEN
    RAISE EXCEPTION 'EXACT_FINANCE_PROCESSING_BINDING_REQUIRED' USING ERRCODE = '42501';
  END IF;

  -- Authorization complete. Deny incomplete predecessors for the authorized
  -- finance assignee only (same rule as act_on_b1_student_request_step_atomic).
  IF EXISTS (
    SELECT 1
    FROM public.student_request_workflow_steps prior
    WHERE prior.student_request_id = v_step.student_request_id
      AND prior.step_order < v_step.step_order
      AND prior.status NOT IN ('completed','skipped')
  ) THEN
    RAISE EXCEPTION 'B1_PREDECESSOR_INCOMPLETE';
  END IF;

  -- No non-payment rejection path exists. If the officer takes no action the
  -- step simply stays active and the request remains pending indefinitely.

  SELECT count(*) INTO v_transition_count
  FROM public.request_type_workflow_transitions t
  WHERE t.workflow_id = v_step.workflow_id
    AND t.from_step_id IS NOT DISTINCT FROM v_step.workflow_step_id
    AND t.action_result = 'payment_confirmed';
  IF v_transition_count IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'EXACTLY_ONE_PAYMENT_CONFIRMED_TRANSITION_REQUIRED' USING ERRCODE = '22023';
  END IF;

  SELECT t.* INTO v_transition
  FROM public.request_type_workflow_transitions t
  WHERE t.workflow_id = v_step.workflow_id
    AND t.from_step_id IS NOT DISTINCT FROM v_step.workflow_step_id
    AND t.action_result = 'payment_confirmed'
  ORDER BY t.is_default DESC, t.created_at
  LIMIT 1;
  IF v_transition.id IS NULL OR v_transition.to_step_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRMED_TRANSITION_REQUIRED' USING ERRCODE = '22023';
  END IF;

  SELECT s.id INTO v_next_step_id
  FROM public.student_request_workflow_steps s
  WHERE s.student_request_id = v_step.student_request_id
    AND s.workflow_step_id = v_transition.to_step_id
    AND s.status = 'pending'
  FOR UPDATE;
  IF v_next_step_id IS NULL THEN
    RAISE EXCEPTION 'NEXT_PAYMENT_WORKFLOW_STEP_NOT_READY' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.student_request_workflow_steps
  SET status = 'completed', decision = 'payment_confirmed',
      comment = NULLIF(btrim(p_note), ''), completed_by = v_uid,
      completed_at = now(), updated_at = now()
  WHERE id = v_step.id;

  UPDATE public.student_request_workflow_steps
  SET status = 'active', entered_at = now(), updated_at = now()
  WHERE id = v_next_step_id AND status = 'pending';

  -- This is a non-terminal transition. The request remains under_review;
  -- only the active runtime step changes, matching act_on_student_request_step.

  INSERT INTO public.student_request_workflow_events (
    student_request_id, workflow_step_runtime_id, event_type, actor_user_id,
    actor_unit_id, actor_role_id, message_ar, payload, visible_to_student
  ) VALUES (
    v_step.student_request_id, v_step.id, 'payment_confirmed', v_uid,
    v_step.processing_unit_id, v_step.processing_role_id, NULLIF(btrim(p_note), ''),
    jsonb_build_object('action','confirm_payment','action_result','payment_confirmed'), true
  );

  INSERT INTO public.student_request_workflow_events (
    student_request_id, workflow_step_runtime_id, event_type, actor_user_id,
    actor_unit_id, actor_role_id, message_ar, payload, visible_to_student
  ) VALUES (
    v_step.student_request_id, v_next_step_id, 'step_entered', v_uid,
    NULL, NULL, NULL,
    jsonb_build_object('from_step_id',v_step.id,'transition_id',v_transition.id,'action_result','payment_confirmed'),
    false
  );

  RETURN jsonb_build_object(
    'success', true, 'status', 'payment_confirmed',
    'request_id', v_step.student_request_id, 'step_id', v_step.id,
    'next_step_id', v_next_step_id, 'transition_applied', true
  );
END;
$$;

