  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tag text NOT NULL,
  assignment_id uuid NOT NULL,
  unit_id uuid NOT NULL,
  role_id uuid,
  assignment_type text NOT NULL,
