CREATE OR REPLACE FUNCTION public.reject_student_request_attachment(p_attachment_id uuid, p_rejection_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_att public.student_request_attachment_uploads%rowtype;
  v_req public.student_requests%rowtype;
  v_owner boolean := false;
  v_field text;
  v_val jsonb;
  v_new jsonb;
  v_code text := coalesce(nullif(btrim(p_rejection_code), ''), 'REMOVED_BY_STUDENT');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ATTACHMENT_ACCESS_DENIED';
  END IF;

  SELECT * INTO v_att
  FROM public.student_request_attachment_uploads
  WHERE id = p_attachment_id
  FOR UPDATE;

  IF v_att.id IS NULL THEN
    RAISE EXCEPTION 'ATTACHMENT_ACCESS_DENIED';
  END IF;

  SELECT exists (
    SELECT 1 FROM public.student_profiles sp
    WHERE sp.id = v_att.student_profile_id
      AND sp.user_id = v_uid
  ) INTO v_owner;

  IF NOT (v_owner OR v_att.created_by = v_uid) THEN
    RAISE EXCEPTION 'ATTACHMENT_ACCESS_DENIED';
  END IF;

  SELECT * INTO v_req
  FROM public.student_requests
  WHERE id = v_att.student_request_id
  FOR UPDATE;

  IF v_req.id IS NULL OR v_req.student_profile_id <> v_att.student_profile_id THEN
    RAISE EXCEPTION 'ATTACHMENT_ACCESS_DENIED';
  END IF;

  IF v_req.status NOT IN ('draft', 'returned', 'returned_for_completion') THEN
    RAISE EXCEPTION 'ATTACHMENT_REMOVAL_NOT_ALLOWED';
  END IF;

  -- Idempotent: already removed leaves no second trace and does not fail.
  IF v_att.upload_status = 'rejected' THEN
    RETURN true;
  END IF;

  IF v_att.upload_status NOT IN ('pending', 'uploaded', 'attached') THEN
    RAISE EXCEPTION 'ATTACHMENT_REMOVAL_NOT_ALLOWED';
  END IF;

  UPDATE public.student_request_attachment_uploads
     SET upload_status = 'rejected',
         rejected_at = now(),
         rejection_code = v_code
   WHERE id = p_attachment_id;

  -- Drop only this attachment reference from the matching form_data field.
  v_field := v_att.field_key;
  v_val := coalesce(v_req.form_data, '{}'::jsonb) -> v_field;

  IF jsonb_typeof(v_val) = 'array' THEN
    SELECT coalesce(jsonb_agg(e), '[]'::jsonb) INTO v_new
    FROM jsonb_array_elements(v_val) e
    WHERE e <> to_jsonb(p_attachment_id::text);

    UPDATE public.student_requests
       SET form_data = jsonb_set(coalesce(form_data, '{}'::jsonb), ARRAY[v_field], v_new, true),
           updated_at = now()
     WHERE id = v_req.id;
  ELSIF jsonb_typeof(v_val) = 'string' AND (v_val #>> '{}') = p_attachment_id::text THEN
    UPDATE public.student_requests
       SET form_data = coalesce(form_data, '{}'::jsonb) - v_field,
           updated_at = now()
     WHERE id = v_req.id;
  ELSE
    UPDATE public.student_requests
       SET updated_at = now()
     WHERE id = v_req.id;
  END IF;

  PERFORM public.log_audit(
    'student_request_attachment'::text,
    p_attachment_id::uuid,
    'attachment_rejected'::text,
    NULL::jsonb,
    NULL::jsonb,
    v_code::text,
    v_uid::uuid
  );

  RETURN true;
END $function$;

CREATE OR REPLACE FUNCTION public.list_my_student_request_attachments(p_student_request_id uuid)
 RETURNS SETOF public.student_request_attachment_uploads
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT a.*
  FROM public.student_request_attachment_uploads a
  JOIN public.student_profiles sp ON sp.id = a.student_profile_id
  WHERE a.student_request_id = p_student_request_id
    AND sp.user_id = auth.uid()
    AND a.upload_status IN ('pending', 'uploaded', 'attached')
$function$;

-- Migration: 20260728015540_9a307610-cd06-4e91-b3f8-4b9b58ab2819.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260728015540', '20260728015540_9a307610-cd06-4e91-b3f8-4b9b58ab2819') ON CONFLICT (version) DO NOTHING;
-- SOURCE-ONLY DRAFT - NOT APPLIED TO PRODUCTION
-- Track: PORTAL-B1-PAYMENT-CONFIRMATION-AUTHORIZATION-HARDENING-01 / order 28
-- Forward-only. Requires explicit single-migration approval before apply.
-- Companion preflight/post-verifier:
--   docs/migration-drafts/b1-backend-verifiers/28-B1_28_PAYMENT_CONFIRMATION_AUTHORIZATION_HARDENING_01-PREFLIGHT.sql
--   docs/migration-drafts/b1-backend-verifiers/28-B1_28_PAYMENT_CONFIRMATION_AUTHORIZATION_HARDENING_01-POST-VERIFIER.sql
--
-- PURPOSE
-- Remove the payment-confirmation authorization bypasses for B1 canonical
-- services only:
--   * is_current_user_admin_actor() early RETURN in the assert helper
--   * has_any_role(revenue_finance_officer|finance_officer) without any runtime
--     assignment
--   * is_current_user_admin_actor() OR user_matches_workflow_runtime_step()
--     step check (admin bypass of the runtime assignee)
-- B1 payment confirmation now routes through the SAME central contract used by
-- act_on_b1_student_request_step_atomic:
--     public.can_current_user_act_on_step(step_id, 'confirm_payment')
-- which already enforces: active step, exactly one assignment identity, direct
-- assignee match, exact processing unit/role binding, config<->runtime
-- correspondence, predecessors satisfied, B1 runtime step contract and a
-- single resolving transition. No duplicated authorization logic is introduced.
--
-- NON-B1 IMPACT: none. The legacy branch keeps the applied behaviour verbatim
-- (assert_can_confirm_student_request_fee_payment + admin/assignee check), so
-- enrollment_certificate and every other non-B1 service are untouched. The
-- assert helper itself is intentionally NOT modified, because it is the legacy
-- contract; B1 simply no longer calls it.

CREATE OR REPLACE FUNCTION public.confirm_student_request_fee_payment(
  p_request_id uuid,
  p_payment_reference text,
  p_notes text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_runtime_step public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_assessment public.student_request_fee_assessments%ROWTYPE;
  v_request public.student_requests%ROWTYPE;
  v_canonical text;
  v_is_b1 boolean := false;
  v_active_count integer;
  v_transition_count integer;
  v_next_step_id uuid;
  v_ref text;
  v_user_id uuid;
BEGIN
  -- (1) authenticated
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTHENTICATION_REQUIRED' USING ERRCODE = '28000';
  END IF;
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'معرّف الطلب مطلوب' USING ERRCODE = '22023'; END IF;
  v_ref := NULLIF(btrim(p_payment_reference), '');
  IF v_ref IS NULL THEN RAISE EXCEPTION 'مرجع الدفع مطلوب' USING ERRCODE = '22023'; END IF;

  SELECT r.* INTO v_request FROM public.student_requests r WHERE r.id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;

  -- (2) B1 canonical scope resolution (stored aliases included)
  v_is_b1 := public.is_b1_stored_request_type(v_request.request_type);
  v_canonical := CASE v_request.request_type
    WHEN 'absence_excuse' THEN 'excused_absence'
    WHEN 'transfer' THEN 'department_transfer'
    WHEN 'extra_chance' THEN 'final_chance'
    ELSE v_request.request_type
  END;

  IF NOT v_is_b1 THEN
    -- LEGACY (non-B1) PATH - preserved verbatim.
    PERFORM public.assert_can_confirm_student_request_fee_payment();
    IF NOT public.can_current_user_access_request(p_request_id) THEN
      RAISE EXCEPTION 'غير مصرح بالوصول إلى هذا الطلب' USING ERRCODE = '42501';
    END IF;
  ELSE
    -- B1 PATH - strict direct-assignee only; every broad-role bypass removed.
    -- (9) expected request status: a payment step can only exist on a live request.
    IF v_request.status NOT IN ('submitted', 'in_progress', 'under_review', 'pending_payment') THEN
      RAISE EXCEPTION 'B1_REQUEST_STATUS_NOT_ACTIONABLE:%', v_request.status USING ERRCODE = '42501';
    END IF;
    IF public.is_owner_of_request(v_uid, p_request_id) THEN
      RAISE EXCEPTION 'B1_DIRECT_ASSIGNEE_AUTHORIZATION_REQUIRED' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Active runtime step (3)
  SELECT s.* INTO v_runtime_step FROM public.student_request_workflow_steps s
  WHERE s.student_request_id = p_request_id AND s.status = 'active'
  ORDER BY s.step_order LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'لا توجد خطوة نشطة' USING ERRCODE = '42501'; END IF;

  SELECT c.* INTO v_config FROM public.request_type_workflow_steps c
  WHERE c.id = v_runtime_step.workflow_step_id;
  IF v_config.action_type IS DISTINCT FROM 'confirm_payment' THEN
    RAISE EXCEPTION 'الخطوة الحالية ليست تأكيد دفع' USING ERRCODE = '42501';
  END IF;

  IF v_is_b1 THEN
    -- (4)(5)(6)(7) single central contract: direct assignee only, exactly one
    -- assignment identity, exact unit/role binding, config<->runtime match,
    -- predecessors satisfied, one resolving transition.
    IF NOT public.can_current_user_act_on_step(v_runtime_step.id, 'confirm_payment') THEN
      RAISE EXCEPTION 'B1_DIRECT_ASSIGNEE_AUTHORIZATION_REQUIRED' USING ERRCODE = '42501';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.student_request_workflow_steps prior
      WHERE prior.student_request_id = v_runtime_step.student_request_id
        AND prior.step_order < v_runtime_step.step_order
        AND prior.status NOT IN ('completed', 'skipped')
    ) THEN
      RAISE EXCEPTION 'B1_PREDECESSOR_INCOMPLETE' USING ERRCODE = '42501';
    END IF;
    SELECT count(*) INTO v_transition_count FROM public.request_type_workflow_transitions t
    WHERE t.workflow_id = v_runtime_step.workflow_id
      AND t.from_step_id = v_runtime_step.workflow_step_id
      AND t.action_result = 'payment_confirmed';
    IF v_transition_count <> 1 THEN
      RAISE EXCEPTION 'B1_TRANSITION_MUST_RESOLVE_ONCE:%', v_transition_count;
    END IF;
  ELSE
    -- LEGACY step check preserved verbatim (admin actor allowed off the B1 path).
    IF NOT public.is_current_user_admin_actor()
       AND NOT public.user_matches_workflow_runtime_step(v_runtime_step.id) THEN
      RAISE EXCEPTION 'غير مصرح بتنفيذ الخطوة الحالية' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- (8) fee assessment prerequisite + (10) idempotency.
  -- Authorization is fully resolved above, so a replay can never leak state to
  -- an unauthorized caller.
  SELECT fa.* INTO v_assessment FROM public.student_request_fee_assessments fa
  WHERE fa.request_id = p_request_id AND fa.payment_status = 'paid'
    AND fa.payment_reference = v_ref
  ORDER BY fa.payment_confirmed_at DESC NULLS LAST LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('success', true, 'assessment_id', v_assessment.id,
      'payment_status', 'paid', 'payment_reference', v_ref,
      'next_step_id', NULL, 'notify_student', false, 'idempotent_replay', true);
  END IF;

  SELECT fa.* INTO v_assessment FROM public.student_request_fee_assessments fa
  WHERE fa.request_id = p_request_id AND fa.payment_status = 'pending_payment'
  ORDER BY fa.created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'لا يوجد تقييم رسوم بانتظار الدفع' USING ERRCODE = '42501'; END IF;

  IF v_assessment.payment_confirmed_at IS NOT NULL OR v_assessment.payment_status = 'paid' THEN
    RAISE EXCEPTION 'تم تأكيد الدفع مسبقاً' USING ERRCODE = '23505';
  END IF;

  UPDATE public.student_request_fee_assessments
  SET payment_status = 'paid', payment_confirmed_by = v_uid, payment_confirmed_at = now(),
    payment_reference = v_ref, hafiza_reference = COALESCE(hafiza_reference, v_ref),
    notes = COALESCE(p_notes, notes), updated_at = now()
  WHERE id = v_assessment.id;

  v_next_step_id := public.apply_student_request_workflow_transition(
    p_request_id, v_runtime_step.id, 'payment_confirmed', v_uid);

  -- Exactly one active step must remain (or none on a terminal transition).
  IF v_is_b1 THEN
    SELECT count(*) INTO v_active_count FROM public.student_request_workflow_steps s
    WHERE s.student_request_id = p_request_id AND s.status = 'active';
    IF v_active_count <> (CASE WHEN v_next_step_id IS NULL THEN 0 ELSE 1 END) THEN
      RAISE EXCEPTION 'B1_ACTIVE_STEP_INVARIANT_FAILED';
    END IF;
  END IF;

  INSERT INTO public.student_request_workflow_events (
    student_request_id, workflow_step_runtime_id, event_type, actor_user_id,
    actor_unit_id, actor_role_id, message_ar, payload, visible_to_student
  ) VALUES (
    p_request_id, v_runtime_step.id, 'completed', v_uid,
    v_runtime_step.processing_unit_id, v_runtime_step.processing_role_id,
    'تم تأكيد سداد الرسوم',
    jsonb_build_object('assessment_id', v_assessment.id, 'payment_reference', v_ref,
      'amount', v_assessment.amount, 'action_result', 'payment_confirmed'),
    true
  );

  SELECT sp.user_id INTO v_user_id FROM public.student_requests sr
  JOIN public.student_profiles sp ON sp.id = sr.student_profile_id WHERE sr.id = p_request_id;
  IF v_user_id IS NOT NULL THEN
    PERFORM public.create_notification(v_user_id, 'تأكيد سداد الرسوم',
      'تم تأكيد سداد رسوم طلبك بمبلغ ' || v_assessment.amount::text || ' YER (مرجع: ' || v_ref || ').',
      'request', 'student_request', p_request_id);
  END IF;

  PERFORM public.log_audit('student_request_fee_assessment'::text, v_assessment.id::uuid,
    'fee_payment_confirmed'::text,
    jsonb_build_object('payment_status', 'pending_payment')::jsonb,
    jsonb_build_object('payment_status', 'paid', 'payment_reference', v_ref,
      'request_id', p_request_id, 'b1_strict', v_is_b1)::jsonb,
    'Fee payment confirmed for student request'::text, v_uid::uuid);

  RETURN jsonb_build_object('success', true, 'assessment_id', v_assessment.id,
    'payment_status', 'paid', 'payment_reference', v_ref,
    'next_step_id', v_next_step_id, 'notify_student', true,
    'idempotent_replay', false);
END;
$function$;

REVOKE ALL ON FUNCTION public.confirm_student_request_fee_payment(uuid, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.confirm_student_request_fee_payment(uuid, text, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.confirm_student_request_fee_payment(uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.confirm_student_request_fee_payment(uuid, text, text) TO service_role;

-- Migration: 20260729014518_65fd6606-34b7-430e-89f5-d58f9b2a4ac2.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260729014518', '20260729014518_65fd6606-34b7-430e-89f5-d58f9b2a4ac2') ON CONFLICT (version) DO NOTHING;
-- ============================================================================
-- B1-RUNTIME-ASSIGNEE-PROPAGATION-01
-- Forward-only. NOT APPLIED. Source-only draft.
--
-- Purpose
--   Generic fail-closed re-validation of the effective direct assignee at the
--   moment ANY B1 runtime step becomes 'active', regardless of which engine
--   performs the activation (act_on_b1_student_request_step_atomic,
--   apply_student_request_workflow_transition, specialized action RPCs,
--   or resubmit resume inside initialize_b1_request_workflow_strict).
--
--   Assignment identities are already resolved and stored at initialization
--   time by initialize_b1_request_workflow_strict (one identity per step,
--   department-scoped for the two department_transfer head steps). The
--   remaining gap is temporal: an assignment may be deactivated, ended,
--   re-scoped, duplicated, or detached — or the PRINCIPAL PROFILE behind it may
--   be disabled, re-pointed to another auth user, or moved to another
--   department — between submit and activation, and no engine re-checks it
--   before flipping pending -> active. This migration closes that gap.
--
-- TOCTOU root cause (why re-reading alone is NOT sufficient)
--   The rows the assert depends on are mutated by direct table DML through
--   PostgREST under RLS (admin surfaces) AND by a small set of SECURITY DEFINER
--   RPCs (admin_set_staff_status, admin_set_faculty_status,
--   admin_unlink_portal_login, link_staff_profile_account,
--   link_faculty_profile_account, apply_b1_department_transfer_effect, …).
--   None of those writers takes a lock the activation path could observe.
--   Under READ COMMITTED (the PostgREST default), the assert's SELECTs take a
--   fresh snapshot, so a concurrent transaction can COMMIT a deactivate /
--   delete / second INSERT / department re-scope / profile disable / user_id
--   swap AFTER the assert reads and BEFORE the activating transaction commits.
--   MVCC gives the reader a consistent snapshot; it does NOT give it a
--   predicate lock. Without SERIALIZABLE (which this database does not
--   enforce) the "exactly one effective identity" predicate is therefore not
--   stable across the activation commit.
--
-- Mutable identity surface covered (every field the effective-identity
-- predicate reads, directly or through is_valid_b1_direct_assignment):
--   request_processing_assignments : unit_id, role_id, assignment_type,
--     user_id, staff_profile_id, faculty_profile_id, position_assignment_id,
--     department_id, is_active, starts_at, ends_at  (+ row INSERT/DELETE)
--   staff_profiles                 : user_id, status                (+ DELETE)
--   faculty_profiles               : user_id, status, department_id (+ DELETE)
--   position_assignments           : user_id, is_active, assigned_from,
--     assigned_to, position_id                                      (+ I/U/D)
--   transfer_request_details       : current_department_id, requested_department_id
--   student_request_workflow_steps : the activating row itself, on BOTH the
--     initial INSERT with status='active' (initialize_b1_request_workflow_strict
--     creates the first step already active — it never performs a
--     pending -> active UPDATE) and the later pending -> active UPDATE
--
-- Remedy below: ONE global transaction-scoped advisory lock ("B1 assignment
--   identity boundary"), acquired by BEFORE STATEMENT lock-only triggers —
--   i.e. before the executor takes any row lock — on every identity table and
--   on the runtime-step table, plus TWO row-level validation guards
--   (BEFORE INSERT active, BEFORE UPDATE OF status to active) sharing one
--   validation body. A single key taken before any row lock cannot participate
--   in a lock cycle, so multi-row / opposite-order statements are deadlock-free
--   by construction and no phantom row can appear inside the window.

--
-- Legacy impact
--   The activation guard is a strict no-op for every non-B1 request type,
--   including enrollment_certificate: the trigger function returns immediately
--   — before taking the lock — when is_b1_stored_request_type(request_type) is
--   false. Administrative profile/assignment maintenance keeps its exact
--   functional contract; the only observable change is that two concurrent
--   identity-boundary writers now serialize on one advisory lock. These are
--   rare, low-volume admin operations, so the added wait is bounded by the
--   duration of a single admin statement. No legacy function, policy, grant,
--   or row is modified.
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 0. Shared GLOBAL lock primitive
--    One constant key for the whole B1 assignment-identity boundary. Every
--    path that can change an effective identity, and the activation path that
--    depends on it, take the SAME key in the SAME transaction-scoped mode.
--    Single key => no lock ordering, no cycle, no phantom gap.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.b1_assignment_identity_lock_key()
RETURNS bigint
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public'
AS $function$
  -- Constant, namespaced to B1 assignment identity. Never derive it from row
  -- data: a single global key is what makes the contract deadlock-free.
  SELECT 7346501982230114001::bigint;
$function$;

CREATE OR REPLACE FUNCTION public.b1_lock_assignment_identity_boundary()
RETURNS void
LANGUAGE plpgsql
VOLATILE
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(public.b1_assignment_identity_lock_key());
END;
$function$;

REVOKE ALL ON FUNCTION public.b1_assignment_identity_lock_key() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.b1_assignment_identity_lock_key() FROM anon;
REVOKE ALL ON FUNCTION public.b1_assignment_identity_lock_key() FROM authenticated;
REVOKE ALL ON FUNCTION public.b1_lock_assignment_identity_boundary() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.b1_lock_assignment_identity_boundary() FROM anon;
REVOKE ALL ON FUNCTION public.b1_lock_assignment_identity_boundary() FROM authenticated;

-- ----------------------------------------------------------------------------
-- 0b. Statement-level lock-only trigger function
--     FOR EACH STATEMENT, BEFORE. It runs once, before the executor takes ANY
--     row lock of the statement, so multi-row DML in opposite row order can
--     never build a wait-for cycle: every identity-boundary writer is already
--     serialized on the single global key before the first tuple is touched.
--     It reads no business row, writes nothing, emits no event, and uses no
--     dynamic SQL.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.b1_lock_assignment_identity_stmt()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.b1_lock_assignment_identity_boundary();
  RETURN NULL; -- BEFORE STATEMENT triggers ignore the return value.
END;
$function$;

REVOKE ALL ON FUNCTION public.b1_lock_assignment_identity_stmt() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.b1_lock_assignment_identity_stmt() FROM anon;
REVOKE ALL ON FUNCTION public.b1_lock_assignment_identity_stmt() FROM authenticated;

-- ----------------------------------------------------------------------------
-- 1. Effective-identity re-resolver (lock-then-read, fail-closed)
--
--    Row-shaped entry point: the guard must also run from a BEFORE INSERT
--    trigger, where the runtime row does NOT yet exist in the table and cannot
--    be re-selected by id. Both entry points share ONE body, so the INSERT and
--    the UPDATE activation guards can never diverge.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.assert_b1_runtime_step_row_assignee_effective(
  p_step public.student_request_workflow_steps
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$

DECLARE
  v_step public.student_request_workflow_steps%ROWTYPE;
  v_request_type text;
  v_canonical text;
  v_department_id uuid;
  v_assignment public.request_processing_assignments%ROWTYPE;
  v_count integer;
  v_assignment_id uuid;
BEGIN
  v_step := p_step;
  IF v_step.id IS NULL OR v_step.student_request_id IS NULL THEN
    RAISE EXCEPTION 'B1_RUNTIME_STEP_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;


  SELECT r.request_type INTO v_request_type
  FROM public.student_requests r
  WHERE r.id = v_step.student_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'B1_RUNTIME_REQUEST_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- Legacy / non-B1: untouched behaviour. Early return BEFORE the lock.
  IF NOT public.is_b1_stored_request_type(v_request_type) THEN
    RETURN;
  END IF;

  -- LOCK BEFORE READ. Everything below observes an identity boundary that no
  -- concurrent assignment, profile, position or transfer-scope mutation can
  -- change until this transaction commits or aborts.
  PERFORM public.b1_lock_assignment_identity_boundary();

  v_canonical := CASE v_request_type
    WHEN 'absence_excuse' THEN 'excused_absence'
    WHEN 'transfer' THEN 'department_transfer'
    WHEN 'extra_chance' THEN 'final_chance'
    ELSE v_request_type
  END;

  -- Department scope: source head resolves ONLY the head of
  -- current_department_id, target head ONLY the head of requested_department_id.
  IF v_canonical = 'department_transfer'
     AND v_step.step_key IN ('source_department_head_approval','target_department_head_approval') THEN
    SELECT CASE v_step.step_key
             WHEN 'source_department_head_approval' THEN d.current_department_id
             ELSE d.requested_department_id
           END
      INTO v_department_id
    FROM public.transfer_request_details d
    WHERE d.request_id = v_step.student_request_id;
    IF v_department_id IS NULL THEN
      RAISE EXCEPTION 'B1_TRANSFER_DEPARTMENT_SCOPE_MISSING:%', v_step.step_key
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Exactly one effective assignment for (unit, role, department scope).
  -- is_valid_b1_direct_assignment re-reads staff_profiles.status/user_id,
  -- faculty_profiles.status/user_id/department_id and
  -- position_assignments.user_id/is_active/assigned_from/assigned_to under the
  -- lock, so a disabled profile or a swapped user_id is seen here.
  SELECT count(*) INTO v_count
  FROM public.request_processing_assignments a
  WHERE a.unit_id = v_step.processing_unit_id
    AND a.role_id = v_step.processing_role_id
    AND a.is_active = true
    AND (a.starts_at IS NULL OR a.starts_at <= now())
    AND (a.ends_at IS NULL OR a.ends_at > now())
    AND (v_department_id IS NULL OR a.department_id = v_department_id)
    AND public.is_valid_b1_direct_assignment(a.id, v_department_id, false)
    AND (v_department_id IS NULL OR (
      a.assignment_type = 'position_assignment'
      AND a.position_assignment_id IS NOT NULL
      AND a.user_id IS NULL AND a.staff_profile_id IS NULL AND a.faculty_profile_id IS NULL));

  IF v_count <> 1 THEN
    RAISE EXCEPTION 'B1_RUNTIME_ASSIGNEE_MUST_RESOLVE_ONCE:%:%', v_step.step_key, v_count
      USING ERRCODE = '42501';
  END IF;

  SELECT a.* INTO v_assignment
  FROM public.request_processing_assignments a
  WHERE a.unit_id = v_step.processing_unit_id
    AND a.role_id = v_step.processing_role_id
    AND a.is_active = true
    AND (a.starts_at IS NULL OR a.starts_at <= now())
    AND (a.ends_at IS NULL OR a.ends_at > now())
    AND (v_department_id IS NULL OR a.department_id = v_department_id)
    AND public.is_valid_b1_direct_assignment(a.id, v_department_id, false)
    AND (v_department_id IS NULL OR (
      a.assignment_type = 'position_assignment'
      AND a.position_assignment_id IS NOT NULL
      AND a.user_id IS NULL AND a.staff_profile_id IS NULL AND a.faculty_profile_id IS NULL));

  -- Exactly one identity kind stored on the resolved assignment.
  IF num_nonnulls(v_assignment.user_id, v_assignment.staff_profile_id,
       v_assignment.faculty_profile_id, v_assignment.position_assignment_id) <> 1 THEN
    RAISE EXCEPTION 'B1_RUNTIME_ASSIGNEE_IDENTITY_NOT_SINGULAR:%', v_step.step_key
      USING ERRCODE = '42501';
  END IF;

  -- Exactly one identity kind stored on the runtime step.
  IF num_nonnulls(v_step.assigned_user_id, v_step.assigned_staff_profile_id,
       v_step.assigned_faculty_profile_id, v_step.assigned_position_assignment_id) <> 1 THEN
    RAISE EXCEPTION 'B1_RUNTIME_ASSIGNEE_MUST_RESOLVE_ONCE:%:%', v_step.step_key, 0
      USING ERRCODE = '42501';
  END IF;

  -- Stored runtime identity must still equal the effective identity.
  IF v_step.assigned_user_id IS DISTINCT FROM v_assignment.user_id
     OR v_step.assigned_staff_profile_id IS DISTINCT FROM v_assignment.staff_profile_id
     OR v_step.assigned_faculty_profile_id IS DISTINCT FROM v_assignment.faculty_profile_id
     OR v_step.assigned_position_assignment_id IS DISTINCT FROM v_assignment.position_assignment_id THEN
    RAISE EXCEPTION 'B1_RUNTIME_ASSIGNEE_IDENTITY_MISMATCH:%', v_step.step_key
      USING ERRCODE = '42501';
  END IF;

  -- Provenance pin, when recorded at initialization.
  v_assignment_id := (v_step.metadata ->> 'direct_assignment_id')::uuid;
  IF v_assignment_id IS NOT NULL AND v_assignment_id IS DISTINCT FROM v_assignment.id THEN
    RAISE EXCEPTION 'B1_RUNTIME_ASSIGNEE_PROVENANCE_MISMATCH:%', v_step.step_key
      USING ERRCODE = '42501';
  END IF;
END;
$function$;

REVOKE ALL ON FUNCTION public.assert_b1_runtime_step_row_assignee_effective(
  public.student_request_workflow_steps) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.assert_b1_runtime_step_row_assignee_effective(
  public.student_request_workflow_steps) FROM anon;
REVOKE ALL ON FUNCTION public.assert_b1_runtime_step_row_assignee_effective(
  public.student_request_workflow_steps) FROM authenticated;

-- By-id entry point, kept for callers/tests that address a persisted step.
-- It only fetches the row and delegates: one body, no divergence.
CREATE OR REPLACE FUNCTION public.assert_b1_runtime_step_assignee_effective(p_step_id uuid)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_step public.student_request_workflow_steps%ROWTYPE;
BEGIN
  SELECT s.* INTO v_step
  FROM public.student_request_workflow_steps s
  WHERE s.id = p_step_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'B1_RUNTIME_STEP_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public.assert_b1_runtime_step_row_assignee_effective(v_step);
END;
$function$;

REVOKE ALL ON FUNCTION public.assert_b1_runtime_step_assignee_effective(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.assert_b1_runtime_step_assignee_effective(uuid) FROM anon;
REVOKE ALL ON FUNCTION public.assert_b1_runtime_step_assignee_effective(uuid) FROM authenticated;

-- ----------------------------------------------------------------------------
-- 2. Activation guards (generic, engine-agnostic)
--
--    Two row-level guards share one validation body:
--      * BEFORE INSERT  WHEN NEW.status = 'active'
--          The FIRST runtime step of every B1 request is created ALREADY
--          active by initialize_b1_request_workflow_strict
--          (status = CASE WHEN step_order = first_order THEN 'active' ...),
--          so it never performs a pending -> active UPDATE and the UPDATE
--          guard alone would never see it. The same hole exists for any direct
--          INSERT of an active row through PostgREST DML.
--      * BEFORE UPDATE OF status WHEN NEW.status = 'active'
--          AND OLD.status IS DISTINCT FROM 'active'
--
--    Both run AFTER the BEFORE STATEMENT lock trigger below has already taken
--    the global identity boundary, so every identity read they perform is
--    inside the boundary and no row lock was acquired before it.
--
--    Failure of either aborts the whole calling transaction: for the INSERT
--    case that means NO runtime step of the request is created at all, no
--    workflow event exists, and no partial request survives.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_b1_runtime_step_activation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.assert_b1_runtime_step_row_assignee_effective(NEW);
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.guard_b1_runtime_step_activation() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_b1_runtime_step_activation() FROM anon;
REVOKE ALL ON FUNCTION public.guard_b1_runtime_step_activation() FROM authenticated;

-- Statement-level lock for the runtime-step table itself: taken once, before
-- the executor locks any runtime row, for BOTH the initial active INSERT path
-- and every activation UPDATE path (RPC engines and direct DML alike).
DROP TRIGGER IF EXISTS trg_b1_lock_runtime_step_identity_stmt
  ON public.student_request_workflow_steps;

CREATE TRIGGER trg_b1_lock_runtime_step_identity_stmt
BEFORE INSERT OR UPDATE ON public.student_request_workflow_steps
FOR EACH STATEMENT
EXECUTE FUNCTION public.b1_lock_assignment_identity_stmt();

DROP TRIGGER IF EXISTS trg_guard_b1_runtime_step_activation_insert
  ON public.student_request_workflow_steps;

CREATE TRIGGER trg_guard_b1_runtime_step_activation_insert
BEFORE INSERT ON public.student_request_workflow_steps
FOR EACH ROW
WHEN (NEW.status = 'active')
EXECUTE FUNCTION public.guard_b1_runtime_step_activation();


DROP TRIGGER IF EXISTS trg_guard_b1_runtime_step_activation
  ON public.student_request_workflow_steps;

-- Name is intentionally ordered AFTER trg_guard_b1_runtime_mutation_boundary
-- so the atomic-boundary guard still runs first.
CREATE TRIGGER trg_guard_b1_runtime_step_activation
BEFORE UPDATE OF status ON public.student_request_workflow_steps
FOR EACH ROW
WHEN (NEW.status = 'active' AND OLD.status IS DISTINCT FROM 'active')
EXECUTE FUNCTION public.guard_b1_runtime_step_activation();

-- ----------------------------------------------------------------------------
-- 3. Mutation side of the SAME global lock contract — STATEMENT LEVEL
--
--    Why statement level and not row level:
--      A BEFORE ROW trigger fires per tuple, and by the time it fires for the
--      SECOND tuple of a multi-row statement the executor already holds the
--      row lock of the FIRST tuple. Two transactions updating the same set of
--      rows in opposite order can therefore each hold a row lock and then
--      block on the advisory key / on each other — the row-level design could
--      not guarantee deadlock freedom for multi-row DML.
--      A BEFORE STATEMENT trigger fires exactly once, before the executor
--      touches any tuple, so the single global key is always acquired BEFORE
--      the first row lock. With one key and no row lock held at acquisition
--      time, no wait-for cycle can be constructed, whatever the row order or
--      row count.
--
--    Every trigger below only takes the lock. It reads no business row, writes
--    nothing, emits no event, performs no backfill and uses no dynamic SQL.
--
--    Covered writer paths (both plain PostgREST DML under RLS and the
--    SECURITY DEFINER admin RPCs — triggers cover both, which is why the
--    contract does not depend on an RPC inventory being complete):
--      a. request_processing_assignments  INSERT / UPDATE / DELETE
--      b. staff_profiles                  UPDATE OF user_id, status / DELETE
--         (admin_set_staff_status, admin_unlink_portal_login,
--          link_staff_profile_account, admin surfaces)
--      c. faculty_profiles                UPDATE OF user_id, status,
--         department_id / DELETE (admin_set_faculty_status,
--          admin_unlink_portal_login, link_faculty_profile_account)
--      d. position_assignments            INSERT / UPDATE / DELETE
--      e. transfer_request_details        UPDATE OF current_department_id,
--         requested_department_id (apply_b1_department_transfer_effect, admin)
--
--    Note on UPDATE OF <cols> at statement level: the column list still gates
--    which statements fire the trigger; it is deliberately kept so unrelated
--    profile edits (name, phone, …) never take the boundary lock.
-- ----------------------------------------------------------------------------

-- The superseded row-lock-only design is removed, not left behind.
DROP TRIGGER IF EXISTS trg_b1_lock_processing_assignment_scope
  ON public.request_processing_assignments;
DROP TRIGGER IF EXISTS trg_b1_lock_position_assignment_scope
  ON public.position_assignments;
DROP TRIGGER IF EXISTS trg_b1_lock_staff_profile_identity
  ON public.staff_profiles;
DROP TRIGGER IF EXISTS trg_b1_lock_staff_profile_identity_delete
  ON public.staff_profiles;
DROP TRIGGER IF EXISTS trg_b1_lock_faculty_profile_identity
  ON public.faculty_profiles;
DROP TRIGGER IF EXISTS trg_b1_lock_faculty_profile_identity_delete
  ON public.faculty_profiles;
DROP TRIGGER IF EXISTS trg_b1_lock_transfer_department_scope
  ON public.transfer_request_details;
DROP FUNCTION IF EXISTS public.b1_lock_assignment_identity_row();

DROP TRIGGER IF EXISTS trg_b1_lock_processing_assignment_stmt
  ON public.request_processing_assignments;

CREATE TRIGGER trg_b1_lock_processing_assignment_stmt
BEFORE INSERT OR UPDATE OR DELETE ON public.request_processing_assignments
FOR EACH STATEMENT
EXECUTE FUNCTION public.b1_lock_assignment_identity_stmt();

DROP TRIGGER IF EXISTS trg_b1_lock_position_assignment_stmt
  ON public.position_assignments;

CREATE TRIGGER trg_b1_lock_position_assignment_stmt
BEFORE INSERT OR UPDATE OR DELETE ON public.position_assignments
FOR EACH STATEMENT
EXECUTE FUNCTION public.b1_lock_assignment_identity_stmt();

DROP TRIGGER IF EXISTS trg_b1_lock_staff_profile_identity_stmt
  ON public.staff_profiles;

CREATE TRIGGER trg_b1_lock_staff_profile_identity_stmt
BEFORE UPDATE OF user_id, status OR DELETE ON public.staff_profiles
FOR EACH STATEMENT
EXECUTE FUNCTION public.b1_lock_assignment_identity_stmt();

DROP TRIGGER IF EXISTS trg_b1_lock_faculty_profile_identity_stmt
  ON public.faculty_profiles;

CREATE TRIGGER trg_b1_lock_faculty_profile_identity_stmt
BEFORE UPDATE OF user_id, status, department_id OR DELETE ON public.faculty_profiles
FOR EACH STATEMENT
EXECUTE FUNCTION public.b1_lock_assignment_identity_stmt();

DROP TRIGGER IF EXISTS trg_b1_lock_transfer_department_scope_stmt
  ON public.transfer_request_details;

CREATE TRIGGER trg_b1_lock_transfer_department_scope_stmt
BEFORE UPDATE OF current_department_id, requested_department_id
  ON public.transfer_request_details
FOR EACH STATEMENT
EXECUTE FUNCTION public.b1_lock_assignment_identity_stmt();

-- ----------------------------------------------------------------------------
-- 4. FAIL-CLOSED ACL ASSERTION (in-migration, same transaction)
--    Every function created above is internal / trigger-only. None of them is
--    granted to any client role. The REVOKEs above are what materialise an
--    explicit proacl: without them PostgreSQL leaves proacl NULL and the
--    built-in default (EXECUTE to PUBLIC) applies. This block refuses to
--    commit if that contract is not satisfied, so the apply itself is
--    fail-closed and never depends on the post-verifier being run.
--    It grants nothing and widens nothing.
-- ----------------------------------------------------------------------------
DO $acl$
DECLARE
  v_sig  text;
  v_oid  oid;
  v_acl  aclitem[];
  v_role text;
BEGIN
  FOREACH v_sig IN ARRAY ARRAY[
    'public.b1_assignment_identity_lock_key()',
    'public.b1_lock_assignment_identity_boundary()',
    'public.b1_lock_assignment_identity_stmt()',
    'public.guard_b1_runtime_step_activation()',
    'public.assert_b1_runtime_step_row_assignee_effective(public.student_request_workflow_steps)',
    'public.assert_b1_runtime_step_assignee_effective(uuid)'
  ] LOOP
    v_oid := to_regprocedure(v_sig);
    IF v_oid IS NULL THEN
      RAISE EXCEPTION 'B1_ACL_CONTRACT_FAIL: % missing with the exact required signature', v_sig;
    END IF;
    SELECT p.proacl INTO v_acl FROM pg_proc p WHERE p.oid = v_oid;
    IF v_acl IS NULL THEN
      RAISE EXCEPTION
        'B1_ACL_CONTRACT_FAIL: % has NULL proacl (default PUBLIC EXECUTE applies)', v_sig;
    END IF;
    IF has_function_privilege('public', v_oid, 'EXECUTE') THEN
      RAISE EXCEPTION 'B1_ACL_CONTRACT_FAIL: % is EXECUTE-able by PUBLIC', v_sig;
    END IF;
    FOREACH v_role IN ARRAY ARRAY['anon','authenticated'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname = v_role)
         AND has_function_privilege(v_role, v_oid, 'EXECUTE') THEN
        RAISE EXCEPTION 'B1_ACL_CONTRACT_FAIL: % is EXECUTE-able by %', v_sig, v_role;
      END IF;
    END LOOP;
  END LOOP;
END
$acl$;

COMMIT;


-- ============================================================================
-- Fail-closed semantics
--   Any RAISE above aborts the whole calling transaction. Therefore:
--     * for the INITIAL ACTIVE INSERT path, NO runtime step row of the request
--       is created at all (the whole initialize transaction rolls back): no
--       partial workflow, no event, no half-built request,
--     * for the activation UPDATE path, the predecessor step is NOT completed,
--     * no workflow event row is created,
--     * the active-step count stays exactly as it was (never 0, never >1),
--     * no partial mutation persists,
--     * a retry after the assignment data is corrected is idempotent.
--   Pre-existing 'pending' steps (including SR-20260727-88D885F0 steps 2 and 3)
--   are covered without any backfill: the guard runs at their activation.
--
-- Concurrency semantics
--   * The advisory key is global and transaction-scoped: it is released only at
--     COMMIT or ROLLBACK, so the "exactly one effective identity" predicate
--     proven by the assert still holds at the instant the activation commits.
--   * The key is acquired by BEFORE STATEMENT triggers, i.e. before the
--     executor takes the first row lock of the statement, on both the identity
--     tables and the runtime-step table itself.
--   * A concurrent deactivate / delete / second INSERT / department re-scope /
--     staff or faculty profile disable / user_id swap / department move BLOCKS
--     until the activating transaction finishes; the mirror case (mutation
--     first) makes activation block and then re-read the committed state, so it
--     can never act on a stale snapshot.
--   * Deadlock freedom: exactly ONE key for the whole boundary, taken before
--     any row lock, so no wait-for cycle between two identity-boundary
--     transactions can be built — regardless of how many rows a statement
--     touches or in which row order.
--   * Phantom freedom: the predicate is protected by the boundary lock rather
--     than by per-row locks, so a newly INSERTed second assignment cannot slip
--     into the window.
--   * Both outcomes are total: either activation with exactly one valid
--     assignee, or a fully rejected transaction. Retry is safe.
--
-- Legacy scope of the runtime-step statement lock
--   trg_b1_lock_runtime_step_identity_stmt is lock-only and unconditional on
--   student_request_workflow_steps. It changes no functional behaviour for
--   enrollment_certificate or any non-B1 flow (the row guards still return
--   before validating them); the only effect is that two concurrent workflow
--   statements serialize on one advisory key for the duration of a single
--   statement's transaction.
--
-- Proof
--   tests/b1-runtime-assignee-lock-concurrency-01/run-harness.py executes this
--   exact file against a throwaway Postgres 17 cluster with real concurrent
--   sessions (initial active INSERT accept/reject, disabled profile, user_id
--   swap, phantom assignment, multi-row reversed order on assignments and on
--   profiles, activation vs multi-row mutation, deactivate, department
--   re-scope, legacy control, retry). Results:
--   tests/b1-runtime-assignee-lock-concurrency-01/RESULTS.md
-- ============================================================================



-- Migration: 20260729173359_9a749214-c28e-489b-95ec-038f290a5c3c.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260729173359', '20260729173359_9a749214-c28e-489b-95ec-038f290a5c3c') ON CONFLICT (version) DO NOTHING;
-- ============================================================================
-- B1-ACTOR-IS-ACTIONABLE-CONFIGURED-ACTION-01
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Configured-action resolver (read-only, fail-closed)
-- ---------------------------------------------------------------------------
create or replace function public.workflow_runtime_step_configured_action(
  p_step_id uuid
)
returns text
language sql
stable
security definer
set search_path to 'public', 'pg_temp'
as $function$
  select c.action_type
  from public.student_request_workflow_steps s
  join public.request_type_workflow_steps c on c.id = s.workflow_step_id
  where s.id = p_step_id
$function$;

revoke all on function public.workflow_runtime_step_configured_action(uuid)
  from public, anon, authenticated;

-- Pin the owner explicitly (fail-closed against ownership drift).
alter function public.workflow_runtime_step_configured_action(uuid) owner to postgres;

-- ---------------------------------------------------------------------------
-- 2. Actor inbox — configured-action probe
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_my_request_actor_inbox(p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(workflow_step_runtime_id uuid, student_request_id uuid, request_type_code text, request_type_name_ar text, student_id uuid, student_name text, department_id uuid, department_name_ar text, step_key text, step_name_ar text, step_status text, processing_unit_id uuid, processing_unit_name_ar text, processing_role_id uuid, processing_role_name_ar text, submitted_at timestamp with time zone, is_actionable boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_safe_limit integer;
  v_safe_offset integer;
  v_status_filter text[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
  END IF;

  v_safe_limit  := GREATEST(LEAST(COALESCE(p_limit,  50), 200), 1);
  v_safe_offset := GREATEST(COALESCE(p_offset, 0), 0);

  IF p_filters ? 'status' THEN
    SELECT array_agg(x::text) INTO v_status_filter
    FROM jsonb_array_elements_text(p_filters -> 'status') AS x;
  ELSE
    v_status_filter := ARRAY['pending', 'active'];
  END IF;

  RETURN QUERY
  SELECT
    s.id,
    sr.id,
    sr.request_type,
    rt.name_ar,
    sp.id,
    sp.full_name_ar,
    sp.department_id,
    d.name_ar,
    s.step_key,
    s.step_name_ar,
    s.status,
    s.processing_unit_id,
    rpu.name_ar,
    s.processing_role_id,
    rpr.name_ar,
    sr.submitted_at,
    (
      s.status = 'active'
      AND public.workflow_runtime_step_configured_action(s.id) IS NOT NULL
      AND public.can_current_user_act_on_step(
            s.id,
            public.workflow_runtime_step_configured_action(s.id)
          )
    ) AS is_actionable
  FROM public.student_request_workflow_steps s
  JOIN public.student_requests sr ON sr.id = s.student_request_id
  JOIN public.student_profiles sp ON sp.id = sr.student_profile_id
  LEFT JOIN public.request_types rt ON rt.code = sr.request_type
  LEFT JOIN public.departments d ON d.id = sp.department_id
  LEFT JOIN public.request_processing_units rpu ON rpu.id = s.processing_unit_id
  LEFT JOIN public.request_processing_roles rpr ON rpr.id = s.processing_role_id
  WHERE s.status = ANY(v_status_filter)
    AND public.user_matches_workflow_runtime_step(s.id)
    AND (NOT (p_filters ? 'processing_unit_code') OR rpu.code = p_filters ->> 'processing_unit_code')
    AND (NOT (p_filters ? 'request_type_code')    OR sr.request_type = p_filters ->> 'request_type_code')
    AND (NOT (p_filters ? 'department_id')         OR sp.department_id::text = p_filters ->> 'department_id')
    AND (
      NOT (p_filters ? 'search')
      OR sr.request_number ILIKE '%' || (p_filters ->> 'search') || '%'
      OR sp.full_name_ar    ILIKE '%' || (p_filters ->> 'search') || '%'
      OR sp.academic_number ILIKE '%' || (p_filters ->> 'search') || '%'
    )
  ORDER BY COALESCE(sr.submitted_at, s.created_at) DESC, s.step_order ASC
  LIMIT v_safe_limit
  OFFSET v_safe_offset;
END;
$function$;

-- ---------------------------------------------------------------------------
-- 3. Actor detail — configured-action probe
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_student_request_detail_for_actor(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_owner boolean;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول'
      USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_current_user_access_request(p_request_id) THEN
    RAISE EXCEPTION 'غير مصرح بعرض هذا الطلب'
      USING ERRCODE = '42501';
  END IF;

  v_is_owner := public.is_owner_of_request(v_uid, p_request_id);

  SELECT jsonb_build_object(
    'request', jsonb_build_object(
      'id', sr.id,
      'request_number', sr.request_number,
      'request_type', sr.request_type,
      'request_type_name_ar', rt.name_ar,
      'title', sr.title,
      'status', sr.status,
      'form_data', CASE WHEN v_is_owner THEN sr.form_data ELSE COALESCE(sr.form_data, '{}'::jsonb) END,
      'student_notes', sr.student_notes,
      'submitted_at', sr.submitted_at,
      'created_at', sr.created_at,
      'updated_at', sr.updated_at,
      'current_step_index', sr.current_step_index,
      'current_role_key', sr.current_role_key
    ),
    'student', jsonb_build_object(
      'id', sp.id,
      'full_name_ar', sp.full_name_ar,
      'academic_number', sp.academic_number,
      'department_id', sp.department_id,
      'department_name_ar', d.name_ar,
      'status', sp.status
    ),
    'workflow_steps', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'step_key', s.step_key,
          'step_name_ar', s.step_name_ar,
          'step_order', s.step_order,
          'status', s.status,
          'decision', s.decision,
          'comment', s.comment,
          'processing_unit_name_ar', rpu.name_ar,
          'processing_role_name_ar', rpr.name_ar,
          'entered_at', s.entered_at,
          'completed_at', s.completed_at,
          'is_actionable', (
            s.status = 'active'
            AND public.workflow_runtime_step_configured_action(s.id) IS NOT NULL
            AND public.can_current_user_act_on_step(
                  s.id,
                  public.workflow_runtime_step_configured_action(s.id)
                )
          )
        )
        ORDER BY s.step_order
      )
      FROM public.student_request_workflow_steps s
      LEFT JOIN public.request_processing_units rpu ON rpu.id = s.processing_unit_id
      LEFT JOIN public.request_processing_roles rpr ON rpr.id = s.processing_role_id
      WHERE s.student_request_id = sr.id
    ), '[]'::jsonb),
    'events', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', e.id,
          'event_type', e.event_type,
          'message_ar', e.message_ar,
          'payload', e.payload,
          'created_at', e.created_at,
          'visible_to_student', e.visible_to_student
        )
        ORDER BY e.created_at
      )
      FROM public.student_request_workflow_events e
      WHERE e.student_request_id = sr.id
        AND (
          NOT v_is_owner
          OR e.visible_to_student = true
        )
    ), '[]'::jsonb),
    'attachments', '[]'::jsonb
  )
  INTO v_result
  FROM public.student_requests sr
  JOIN public.student_profiles sp ON sp.id = sr.student_profile_id
  LEFT JOIN public.request_types rt ON rt.code = sr.request_type
  LEFT JOIN public.departments d ON d.id = sp.department_id
  WHERE sr.id = p_request_id;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'الطلب غير موجود'
      USING ERRCODE = 'P0002';
  END IF;

  RETURN v_result;
END;
$function$;

-- ---------------------------------------------------------------------------
-- 4. Fee processing context — configured-action probe
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_student_request_fee_processing_context(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_runtime public.student_request_workflow_steps%ROWTYPE;
  v_config public.request_type_workflow_steps%ROWTYPE;
  v_fee public.student_request_fee_assessments%ROWTYPE;
  v_can_execute boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000'; END IF;
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'معرّف الطلب مطلوب' USING ERRCODE = '22023'; END IF;
  IF NOT public.can_current_user_access_request(p_request_id) THEN
    RAISE EXCEPTION 'غير مصرح بالوصول إلى هذا الطلب' USING ERRCODE = '42501';
  END IF;

  SELECT s.* INTO v_runtime FROM public.student_request_workflow_steps s
  WHERE s.student_request_id = p_request_id AND s.status = 'active'
  ORDER BY s.step_order LIMIT 1;

  IF FOUND THEN
    SELECT c.* INTO v_config FROM public.request_type_workflow_steps c WHERE c.id = v_runtime.workflow_step_id;
    v_can_execute := public.is_current_user_admin_actor()
      OR (
        v_config.action_type IS NOT NULL
        AND public.can_current_user_act_on_step(v_runtime.id, v_config.action_type)
      );
  END IF;

  SELECT fa.* INTO v_fee FROM public.student_request_fee_assessments fa
  WHERE fa.request_id = p_request_id AND fa.payment_status <> 'cancelled'
  ORDER BY fa.created_at DESC LIMIT 1;

  RETURN jsonb_build_object('success', true, 'request_id', p_request_id,
    'runtime_step_id', v_runtime.id, 'step_key', v_runtime.step_key,
    'step_status', v_runtime.status, 'action_type', v_config.action_type,
    'processing_unit_id', v_runtime.processing_unit_id,
    'processing_role_id', v_runtime.processing_role_id,
    'can_execute_current_step', COALESCE(v_can_execute, false),
    'fee_assessment', CASE WHEN v_fee.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_fee.id, 'amount', v_fee.amount, 'currency', COALESCE(v_fee.currency, 'YER'),
      'payment_status', v_fee.payment_status, 'payment_reference', v_fee.payment_reference,
      'assessed_at', v_fee.assessed_at, 'payment_confirmed_at', v_fee.payment_confirmed_at
    ) END);
END;
$function$;

-- ---------------------------------------------------------------------------
-- 5. Ownership pins for the three replaced RPCs (no privilege change)
-- ---------------------------------------------------------------------------
alter function public.get_my_request_actor_inbox(jsonb, integer, integer) owner to postgres;
alter function public.get_student_request_detail_for_actor(uuid) owner to postgres;
alter function public.get_student_request_fee_processing_context(uuid) owner to postgres;

commit;

