DROP POLICY IF EXISTS "Authenticated can list research pdfs" ON storage.objects;
DROP POLICY IF EXISTS "Public can view research pdfs" ON storage.objects;

CREATE POLICY "Published research pdfs are listable"
ON storage.objects
FOR SELECT
USING (
  bucket_id = 'research-pdfs'
  AND EXISTS (
    SELECT 1
    FROM public.research_papers rp
    WHERE rp.is_published = true
      AND rp.pdf_url IS NOT NULL
      AND rp.pdf_url LIKE '%/research-pdfs/' || storage.objects.name
  )
);

CREATE POLICY "Admins can list research pdfs"
ON storage.objects
FOR SELECT
TO authenticated
USING (
  bucket_id = 'research-pdfs'
  AND has_any_role(auth.uid(), ARRAY['admin','system_admin'])
);

-- Migration: 20260730175527_89e2a6a3-4e9f-48d7-9371-8e996ae1c00a.sql
INSERT INTO supabase_migrations.schema_migrations(version, name) VALUES ('20260730175527', '20260730175527_89e2a6a3-4e9f-48d7-9371-8e996ae1c00a') ON CONFLICT (version) DO NOTHING;
GRANT EXECUTE ON FUNCTION public.act_on_b1_student_request_step_atomic(uuid,text,text,jsonb) TO authenticated, service_role;
UPDATE public.request_types SET student_visible = false WHERE code IN ('enrollment_suspension','excused_absence','absence_excuse','department_transfer','transfer','final_chance','extra_chance','file_withdrawal');
-- PORTAL-B1-ATOMIC-RPC-LITERAL-CONFIGURED-ACTION-PRODUCTION-MIGRATION-PACKAGE-66
BEGIN;

DO $pre$
DECLARE v_acl text; v_owner text; v_cfg text[];
