      ( 7,'enrollment_suspension',3),
      ( 8,'excused_absence'      ,2),
      ( 9,'excused_absence'      ,3),
      (10,'file_withdrawal'      ,2),
      (11,'file_withdrawal'      ,3),
      (12,'file_withdrawal'      ,4),
      (13,'file_withdrawal'      ,5),
      (14,'file_withdrawal'      ,6),
