    END IF;
    v_created_req := v_created_req + 1;

    IF r.service = 'department_transfer' THEN
      v_detail_id := ('f1300002-0000-4000-8000-' || lpad(r.ord::text, 12, '0'))::uuid;

      SELECT count(*) INTO v_n FROM public.transfer_request_details d
