      );
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'FIXTURE13_FAIL: transfer detail insert affected % rows (expected 1)', v_rows;
      END IF;
      v_created_details := v_created_details + 1;
