   WHERE req.internal_notes = k_marker;
  IF v_n <> 104 THEN
    RAISE EXCEPTION 'FIXTURE13_POSTFAIL: % distinct fixture step ids (expected 104)', v_n;
  END IF;
  SELECT count(*) INTO v_n
    FROM public.student_request_workflow_steps s
